/* Detailed N26 learning procedures and hypothetical practice; never touches live records. */
(function(){
'use strict';
const details={"gang-foundations":{"budget":{"objective":{"ko":"시작 예산을 파이터·장비·잔액으로 나눠, 첫 모집 전에 쓸 수 있는 금액을 정합니다.","en":"Divide the starting budget into fighters, equipment and a reserve before recruiting."},"preparation":[{"ko":"캠페인인지 스커미시인지, 기본 1000크레딧을 쓰는지 아비트레이터에게 확인합니다.","en":"Confirm campaign or skirmish play and whether the arbitrator uses the default 1000 credits."}],"walkthrough":[{"title":{"ko":"예산 기준 적기","en":"Write the budget"},"body":{"ko":"새 갱 화면에서 N26과 갱 유형을 고른 뒤 실제 시작 예산을 따로 적습니다. 예산을 바꾼 캠페인이면 1000을 자동 적용하지 않습니다.","en":"Select N26 and a gang type, then note the actual starting allowance. Do not assume 1000 if the campaign changes it."},"result":{"ko":"계산에 쓸 기준 금액이 하나로 정해집니다.","en":"You have one agreed budget for every later calculation."}},{"title":{"ko":"모델과 장비를 분리하기","en":"Separate model and equipment costs"},"body":{"ko":"리더와 나머지 모델의 모집비를 먼저 합산하고, 구매할 무기·방어구 비용을 두 번째 줄에 적습니다.","en":"Add recruitment costs first, then list weapons and armour on a second line."},"result":{"ko":"모집비와 장비비가 같은 비용으로 두 번 기록되지 않습니다.","en":"Recruitment and equipment are not counted twice."}},{"title":{"ko":"남은 금액과 사용 방식 확인","en":"Check the remainder"},"body":{"ko":"예산에서 두 지출을 뺍니다. 캠페인은 남은 크레딧을 보관하고, 스커미시는 창설 잔액 소멸을 확인한 뒤 최종 명단을 확정합니다.","en":"Subtract both costs. Keep the remainder for campaign play; check the lost creation remainder for skirmish before finalizing."},"result":{"ko":"예산 초과 여부와 보관할 잔액을 설명할 수 있습니다.","en":"You can explain whether the roster fits and what reserve remains."}}],"workedExample":{"situation":{"ko":"기본 예산 1000에서 모델 600, 장비 250을 계획한 캠페인 갱입니다.","en":"A campaign gang plans 600 credits of models and 250 of equipment from the default 1000."},"steps":[{"ko":"600 + 250 = 850크레딧을 사용합니다.","en":"600 + 250 = 850 credits spent."},{"ko":"1000 − 850 = 150크레딧이 남습니다.","en":"1000 − 850 = 150 credits remain."}],"result":{"ko":"캠페인 잔액은 150입니다. 예산이 맞아도 구성 비율과 장비 제한은 별도 검사합니다.","en":"The campaign reserve is 150. Budget compliance does not replace composition and equipment checks."}},"pitfalls":[{"problem":{"ko":"잔액이 있으니 어떤 무기든 구매할 수 있다고 생각합니다.","en":"Assuming any weapon is available because credits remain."},"fix":{"ko":"해당 파이터 전용 목록과 접근 조건을 먼저 확인하고 구매비를 계산합니다.","en":"Check the fighter list and access conditions before calculating purchase cost."}}],"selfCheck":{"ko":"우리 캠페인의 시작 예산과 내가 남기려는 크레딧을 서로 구분해 말할 수 있나요?","en":"Can you distinguish the campaign starting allowance from your planned credit reserve?"}},"composition":{"objective":{"ko":"이름이 아닌 실제 유형으로 리더 수와 제한 대상 비율을 검사합니다.","en":"Check Leader count and the restricted-model ratio using actual types rather than names."},"preparation":[{"ko":"후보 명단의 유형·하위유형, 갱별 구성 예외를 펼쳐 둡니다.","en":"Have the candidate types, subtypes and gang-specific composition exceptions available."}],"walkthrough":[{"title":{"ko":"리더를 정확히 세기","en":"Count actual Leaders"},"body":{"ko":"모집 목록의 리더 하위유형을 확인해 정확히 한 명인지 셉니다. 모델 이름에 붙인 별명은 유형을 바꾸지 않습니다.","en":"Count entries with the actual Leader subtype and require exactly one. A nickname does not change a type."},"result":{"ko":"리더가 없거나 두 명인 문제를 먼저 발견합니다.","en":"Missing or duplicate Leaders are caught first."}},{"title":{"ko":"두 집단으로 분류하기","en":"Sort into two groups"},"body":{"ko":"챔피언·브루트·행어온 합계를 제한 집단으로 적고, 그 밖의 모델을 다른 집단으로 셉니다. 펫은 두 집단의 비율 계산에서 제외합니다.","en":"Total Champions, Brutes and Hangers-on as the restricted group, then count other models. Exclude Pets from the ratio."},"result":{"ko":"비교할 두 숫자를 얻습니다.","en":"You have the two numbers to compare."}},{"title":{"ko":"비율과 예외를 적용하기","en":"Apply the ratio and exceptions"},"body":{"ko":"제한 집단이 다른 모델 수보다 크면 모집안을 조정합니다. 갱별 예외는 어떤 조건을 바꾸는지 확인해 적용합니다.","en":"If the restricted total exceeds the other models, revise recruitment. Apply an explicit gang exception only to the condition it changes."},"result":{"ko":"기본 제한을 충족하는지 근거를 남깁니다.","en":"You retain a reason why the composition is legal."}}],"workedExample":{"situation":{"ko":"리더 1, 갱어 2, 챔피언 2, 행어온 1, 펫 2를 계획했습니다.","en":"You plan 1 Leader, 2 Gangers, 2 Champions, 1 Hanger-on and 2 Pets."},"steps":[{"ko":"제한 집단은 챔피언 2 + 행어온 1 = 3입니다.","en":"The restricted group is 2 Champions + 1 Hanger-on = 3."},{"ko":"다른 모델은 리더 1 + 갱어 2 = 3이며 펫 2는 제외합니다.","en":"Other models are 1 Leader + 2 Gangers = 3; exclude the 2 Pets."}],"result":{"ko":"기본 비율 3 ≤ 3과 리더 1명을 모두 충족합니다. 갱별 추가 조건은 계속 적용됩니다.","en":"The standard ratio 3 ≤ 3 and exactly one Leader are satisfied. Additional gang conditions still apply."}},"pitfalls":[{"problem":{"ko":"펫을 더하면 제한 대상 모델을 계속 늘릴 수 있다고 계산합니다.","en":"Counting Pets as a way to support more restricted models."},"fix":{"ko":"펫을 제외하고 두 집단을 다시 세세요. 펫의 장비 가치와 구성 비율은 다른 문제입니다.","en":"Recount both groups without Pets. Their equipment value and the composition ratio are separate questions."}}],"selfCheck":{"ko":"내 명단에서 제한 집단과 다른 모델 집단에 누가 들어가는지 설명할 수 있나요?","en":"Can you explain which of your entries belongs in each composition group?"}},"recruit":{"objective":{"ko":"파이터 추가 화면의 선택 항목과 저장 후 카드가 같은 파이터를 나타내는지 대조합니다.","en":"Compare the Add Fighter selection with the saved card to verify the recruited fighter."},"preparation":[{"ko":"선택한 갱의 N26 유형 목록과 남은 모집 예산을 확인합니다.","en":"Check the gang’s N26 fighter list and remaining recruitment budget."}],"walkthrough":[{"title":{"ko":"유형을 먼저 선택하기","en":"Select the type first"},"body":{"ko":"파이터 추가에서 해당 갱의 실제 유형을 고릅니다. 같은 별명이나 비슷한 번역 이름이 아니라 유형·하위유형으로 역할을 판단합니다.","en":"Choose an actual type from the gang list. Judge its role by type and subtype, not a nickname or similar translated label."},"result":{"ko":"모집할 모델의 규칙상 역할이 정해집니다.","en":"The model’s rules role is established."}},{"title":{"ko":"기본값을 읽고 확정하기","en":"Inspect defaults before confirming"},"body":{"ko":"이름, 모집 비용, 시작 XP와 능력치를 확인합니다. 기본 장비가 있는지 보고 같은 아이템을 다시 구매하지 않도록 합니다.","en":"Review name, cost, starting XP and characteristics. Check default equipment so you do not buy the same item again."},"result":{"ko":"모집 직후의 기준 상태를 파악합니다.","en":"You know the model’s initial state."}},{"title":{"ko":"저장 카드와 명단 검사","en":"Verify the saved card"},"body":{"ko":"모집한 파이터를 열어 유형, 능력치, 장비와 잔액을 대조합니다. 시작 XP를 새로 얻은 XP처럼 성장 처리하지 않습니다.","en":"Open the recruited card and compare type, stats, equipment and credits. Do not treat starting XP as newly earned XP for advancements."},"result":{"ko":"잘못된 커스텀 입력이나 중복 구매를 초기에 바로잡습니다.","en":"Custom-entry mistakes and duplicate purchases are caught early."}}],"workedExample":{"situation":{"ko":"제한 집단이 4명, 다른 모델이 3명인 상태에서 펫 2마리를 더하려 합니다.","en":"The restricted group has 4 models and the other group has 3; you want to add 2 Pets."},"steps":[{"ko":"파이터와 장비를 구분해 펫은 비율에서 제외합니다.","en":"Separate models from equipment and exclude Pets from the ratio."},{"ko":"제한 집단 4와 다른 모델 3을 그대로 비교합니다.","en":"Compare the unchanged totals: restricted 4 against other 3."}],"result":{"ko":"4 > 3이므로 펫 추가만으로 해결되지 않습니다. 적법한 다른 모델 추가 또는 제한 집단 조정이 필요합니다.","en":"Because 4 > 3, adding Pets does not fix the ratio. Add eligible other models or reduce the restricted group."}},"pitfalls":[{"problem":{"ko":"시작 XP를 보고 모집 순간에 성장까지 추가합니다.","en":"Adding advancements immediately because the recruit has starting XP."},"fix":{"ko":"시작 XP와 캠페인 중 새로 얻은 XP를 구분해 성장 조건을 확인합니다.","en":"Distinguish starting XP from newly earned campaign XP before checking advancement timing."}}],"selfCheck":{"ko":"유형·능력치·기본 장비·모집비 중 저장 후 확인할 네 항목을 찾았나요?","en":"Have you located the type, characteristics, default equipment and recruitment cost on the saved record?"},"exerciseHint":{"ko":"펫을 장비로 취급한 뒤 두 모델 집단의 숫자를 다시 비교해 보세요.","en":"Treat Pets as equipment, then compare the two model totals again."},"optionFeedback":{"1":{"ko":"펫은 다른 모델 수를 늘리지 않으므로 4 대 3의 위반이 그대로 남습니다.","en":"Pets do not increase the other-model count, so the 4-to-3 failure remains."},"2":{"ko":"펫을 제외한 4와 3을 비교한 판단입니다. 제한 집단이 더 크므로 기본 제한을 충족하지 않습니다.","en":"This correctly compares 4 with 3 after excluding Pets; the restricted group is too large."},"3":{"ko":"리더가 정확히 한 명이라는 조건과 구성 비율은 각각 충족해야 합니다.","en":"Exactly one Leader and the composition ratio are separate requirements."}}},"profiles":{"objective":{"ko":"N26 무기 표의 각 열과 무기 슬롯 계산을 분리해서 읽습니다.","en":"Read the N26 profile columns separately from weapon-slot capacity."},"preparation":[{"ko":"파이터의 무기 목록과 각 무기의 별표·프로필·액세서리를 확인합니다.","en":"Have the fighter’s weapons, stars, profiles and accessories in view."}],"walkthrough":[{"title":{"ko":"프로필 열을 순서대로 읽기","en":"Read each profile column"},"body":{"ko":"사거리와 명중 수정, S, AP, L, 특성을 차례로 읽습니다. 한 무기에 여러 사격 모드가 있으면 사용할 행을 먼저 정합니다.","en":"Read range, hit modifiers, S, AP, L and traits in order. If a weapon has several firing modes, first identify the row being used."},"result":{"ko":"서로 다른 모드의 좋은 값만 섞지 않게 됩니다.","en":"You avoid mixing the best values from different modes."}},{"title":{"ko":"슬롯을 별도 합산하기","en":"Total slots separately"},"body":{"ko":"일반 무기 1칸, 별표 무기 2칸으로 계산합니다. 그레네이드는 제외하며 일반 전투원의 기본 한도 3칸과 비교합니다.","en":"Count a normal weapon as 1 slot and a starred weapon as 2. Exclude grenades and compare with the normal fighter limit of 3."},"result":{"ko":"가격과 무관하게 슬롯 초과를 확인합니다.","en":"You detect slot overflow independently of price."}},{"title":{"ko":"액세서리와 예외 점검","en":"Check accessories and exceptions"},"body":{"ko":"무기 하나당 액세서리 최대 1개인지 확인하고, 차량이나 명시적 슬롯 예외는 해당 항목을 읽습니다. L을 이전 판본의 D로 바꾸지 않습니다.","en":"Check at most 1 accessory per weapon and read explicit slot exceptions or vehicle entries. Do not replace L with a legacy D value."},"result":{"ko":"슬롯과 카드 해석을 모두 마칩니다.","en":"Both carrying capacity and profile interpretation are checked."}}],"workedExample":{"situation":{"ko":"별표 무기 1개와 일반 무기 1개, 그레네이드 1개를 든 전투원입니다.","en":"A fighter carries 1 starred weapon, 1 normal weapon and 1 grenade."},"steps":[{"ko":"별표 2칸 + 일반 1칸 = 3칸입니다.","en":"The starred weapon uses 2 slots and the normal weapon 1: total 3."},{"ko":"그레네이드는 슬롯에 더하지 않습니다. 일반 무기를 하나 더 들면 4칸이 됩니다.","en":"Do not add the grenade. One more normal weapon would raise the total to 4."}],"result":{"ko":"기본 한도 3칸에는 맞지만 일반 무기 추가는 별도 예외 없이 불가능합니다.","en":"The current load fits 3 slots, but another normal weapon needs an explicit exception."}},"pitfalls":[{"problem":{"ko":"L 2이면 언제나 W를 2 깎는다고 처리합니다.","en":"Treating L 2 as always removing 2 W."},"fix":{"ko":"막지 못한 운드로 W를 줄이는 절차와 W 0에서 L로 부상 주사위를 정하는 절차를 분리합니다.","en":"Separate W loss from an unsaved wound and the L-based injury dice when W reaches zero."}}],"selfCheck":{"ko":"현재 세트의 슬롯 합과 실제 사용할 프로필 행을 각각 가리킬 수 있나요?","en":"Can you identify both the current set’s slot total and the profile row you will use?"}},"sets-finances":{"objective":{"ko":"같은 모델의 여러 장비 세트를 모델 복제나 중복 구매로 오해하지 않고 레이팅·자산을 계산합니다.","en":"Treat equipment sets as one model’s alternatives and distinguish Rating from Wealth."},"preparation":[{"ko":"동일 모델의 세트별 무기와 실제 보유 아이템, 잔액, 보관고를 펼칩니다.","en":"List the same model’s sets, owned items, credit reserve and stash."}],"walkthrough":[{"title":{"ko":"모델 하나로 묶기","en":"Keep one model identity"},"body":{"ko":"세트 A와 B가 같은 파이터의 선택지인지 확인합니다. XP·성장·지속 부상은 공통이며 명부의 모델 수는 하나입니다.","en":"Check that sets A and B belong to the same fighter. XP, advancements and lasting injuries are shared; the roster still has one model."},"result":{"ko":"세트 수 때문에 모델이나 XP가 늘어나지 않습니다.","en":"Extra sets do not create extra models or XP."}},{"title":{"ko":"실물 아이템 중복 제거","en":"Count owned items once"},"body":{"ko":"두 세트에 같은 보유 아이템을 지정했다면 구매·가치를 한 번만 계산합니다. 이름만 같은 별도 실물 두 개와 혼동하지 않습니다.","en":"When the same owned item is assigned to two sets, purchase and value it once. Distinguish it from two separate items with the same name."},"result":{"ko":"장비 값이 세트 수만큼 부풀지 않습니다.","en":"Equipment value is not multiplied by the number of sets."}},{"title":{"ko":"레이팅 다음 자산 계산","en":"Calculate Rating, then Wealth"},"body":{"ko":"모델 가치 합계를 레이팅으로 확인하고 잔액과 보관고 가치를 더해 자산을 구합니다. 전투에는 선택한 세트 하나를 사용합니다.","en":"Check total model value as Rating, then add reserve credits and stash value for Wealth. Use one selected set in battle."},"result":{"ko":"명단 가치와 전체 보유 자산을 구분합니다.","en":"You distinguish roster value from everything the gang owns."}}],"workedExample":{"situation":{"ko":"모델 가치 합계 900, 잔액 70, 보관고 장비 30인 갱입니다.","en":"A gang has model values totaling 900, 70 unspent credits and 30 of stash equipment."},"steps":[{"ko":"레이팅은 모델 가치 합계인 900입니다.","en":"Rating is the 900 total model value."},{"ko":"자산은 900 + 70 + 30 = 1000입니다. 같은 보유 무기의 세트 재사용은 새 구매가 아닙니다.","en":"Wealth is 900 + 70 + 30 = 1000. Reusing an owned weapon across sets is not another purchase."}],"result":{"ko":"레이팅 900과 자산 1000은 서로 다른 목적의 값입니다.","en":"Rating 900 and Wealth 1000 answer different questions."}},"pitfalls":[{"problem":{"ko":"세트를 늘릴 때마다 같은 파이터와 무기 가치를 다시 더합니다.","en":"Adding the same fighter and weapon value again for each set."},"fix":{"ko":"먼저 모델 ID와 실제 보유 아이템을 기준으로 중복을 제거한 뒤 가치 합계를 확인합니다.","en":"Use model identity and owned-item identity to remove duplicate counting before totaling value."}}],"selfCheck":{"ko":"내 갱의 레이팅과 자산의 차이가 잔액·보관고로 설명되나요?","en":"Can you explain your gang’s Rating-to-Wealth difference through credits and stash?"}},"budget-practice":{"objective":{"ko":"창설 장부의 산술 검산과 구성·슬롯 검사를 서로 독립적으로 수행합니다.","en":"Audit the creation arithmetic separately from composition and slot legality."},"preparation":[{"ko":"이 연습은 기본 1000크레딧의 캠페인 갱이며 실제 구매를 하지 않습니다.","en":"This is a hypothetical campaign gang with the default 1000 credits; no purchase is made."}],"walkthrough":[{"title":{"ko":"지출 줄을 더하기","en":"Add the spending lines"},"body":{"ko":"모델 모집비 650과 장비비 280을 더합니다. 장비가 이미 모델 기본값에 포함됐는지도 실제 명단에서는 확인합니다.","en":"Add recruitment 650 and equipment 280. For a real roster, also check whether any equipment was included in a model’s base cost."},"result":{"ko":"연습 사용액은 930입니다.","en":"The example spending total is 930."}},{"title":{"ko":"잔액 검산하기","en":"Verify the reserve"},"body":{"ko":"시작 예산에서 사용액을 빼고 사용액 + 잔액이 다시 예산인지 확인합니다. 캠페인이므로 남은 금액을 보관합니다.","en":"Subtract spending from the starting budget, then check spending plus reserve equals the budget. This campaign retains the remainder."},"result":{"ko":"잔액은 70이며 930 + 70 = 1000입니다.","en":"The reserve is 70 and 930 + 70 = 1000."}},{"title":{"ko":"돈 외의 제한 검사","en":"Audit nonfinancial limits"},"body":{"ko":"리더 한 명, 제한 집단 비율, 각 전투원의 무기 슬롯과 장비 접근을 별도로 확인합니다. 예산 적합을 명단 전체 적법 판정으로 쓰지 않습니다.","en":"Separately check one Leader, the restricted-group ratio, weapon slots and equipment access. A balanced budget is not a complete legality ruling."},"result":{"ko":"명단을 확정하기 전 마지막 확인 목록이 생깁니다.","en":"You have a final checklist before approving the roster."}}],"workedExample":{"situation":{"ko":"사용액 650 + 280과 기본 창설 예산 1000을 대조합니다.","en":"Compare spending of 650 + 280 with the default creation budget of 1000."},"steps":[{"ko":"650 + 280 = 930을 먼저 계산합니다.","en":"First calculate 650 + 280 = 930."},{"ko":"1000 − 930 = 70, 역산하면 930 + 70 = 1000입니다.","en":"Then 1000 − 930 = 70; reverse-check 930 + 70 = 1000."}],"result":{"ko":"930 사용, 70 보관이 정답입니다. 같은 지출이라도 스커미시 잔액 규칙은 다릅니다.","en":"930 spent and 70 retained is correct. The skirmish remainder rule differs even with identical spending."}},"pitfalls":[{"problem":{"ko":"잔액이 70이니 실제 구입하지 않은 아이템도 명단에 적습니다.","en":"Listing unpurchased items because 70 credits remain."},"fix":{"ko":"보유 장비와 살 수 있는 장비를 구분하고 실제 구매 때만 지출을 기록합니다.","en":"Distinguish owned items from affordable items and record spending only for purchases."}}],"selfCheck":{"ko":"930과 70을 얻는 식, 돈 외에 확인할 제한 두 가지를 말할 수 있나요?","en":"Can you show the arithmetic for 930 and 70 and name two nonfinancial checks?"},"exerciseHint":{"ko":"모집비와 장비비를 먼저 더한 뒤 1000에서 빼세요. 캠페인이라는 조건도 확인하세요.","en":"Add recruitment and equipment first, then subtract from 1000. Remember that this is a campaign."},"optionFeedback":{"1":{"ko":"650 + 280 = 930, 1000 − 930 = 70이며 캠페인에서는 잔액을 보관합니다.","en":"650 + 280 = 930 and 1000 − 930 = 70; campaign play keeps the reserve."},"2":{"ko":"사용액은 맞지만 잔액 소멸을 캠페인에 적용한 점이 잘못됐습니다.","en":"The spending is correct, but losing the remainder is wrong for this campaign example."},"3":{"ko":"무기·방어구 등 장비비도 창설 예산의 지출에 포함합니다.","en":"Weapons, armour and other equipment also spend the creation budget."}}}},"prepare-round":{"prebattle-order":{"objective":{"ko":"크루·전술·배치를 정해진 순서로 준비하고 참가할 수 없는 모델을 미리 걸러냅니다.","en":"Prepare crew, tactics and deployment in order, filtering unavailable models first."},"preparation":[{"ko":"캠페인 판본, 도전 대상, 시나리오와 회복 중 모델 목록을 준비합니다.","en":"Have the campaign edition, challenge, scenario and Recovery list ready."}],"walkthrough":[{"title":{"ko":"전투의 조건 정하기","en":"Agree the battle conditions"},"body":{"ko":"도전과 내기할 영토를 정하고 시나리오를 확인합니다. 참가 크루 수와 배치 조건을 확인하기 전에 모델을 전장에 놓지 않습니다.","en":"Agree the challenge and territory stake, then check the scenario. Do not deploy before reading crew and deployment conditions."},"result":{"ko":"무엇을 걸고 어떤 조건으로 싸우는지 공통 기준이 생깁니다.","en":"Both players share the battle’s stakes and conditions."}},{"title":{"ko":"전장과 크루 확정","en":"Prepare battlefield and crew"},"body":{"ko":"전장을 구성하고 시나리오 방식으로 크루를 고릅니다. 캠페인 회복 등 참가 불가 모델을 제외하고 장비 세트도 확인합니다.","en":"Prepare the battlefield and choose the crew by the scenario procedure. Exclude unavailable models and confirm equipment sets."},"result":{"ko":"실제로 배치할 모델과 사용할 카드가 정해집니다.","en":"The deployable models and their cards are established."}},{"title":{"ko":"효과·전술 후 배치","en":"Apply effects and tactics, then deploy"},"body":{"ko":"전장 효과를 처리하고 갱 전술을 정한 다음 배치합니다. 지형과 선택 규칙의 의미를 양쪽이 같은 방식으로 이해했는지 확인합니다.","en":"Resolve battlefield effects, select gang tactics, then deploy. Confirm that both players interpret terrain and optional rules consistently."},"result":{"ko":"배치 뒤 임의로 전술·지형 의미를 바꾸는 일을 줄입니다.","en":"You avoid changing tactics or terrain interpretations after deployment."}}],"workedExample":{"situation":{"ko":"명부에는 8명이 있지만 그중 1명은 캠페인 회복 상태입니다.","en":"The roster has 8 models, including 1 in campaign Recovery."},"steps":[{"ko":"참가 불가인 회복 모델을 후보에서 제외하면 가용 후보는 7명입니다.","en":"Exclude the unavailable Recovery model: 7 candidates remain."},{"ko":"그 7명 중 시나리오의 크루 선정 절차를 적용한 뒤 효과·전술·배치를 진행합니다.","en":"Apply the scenario crew-selection procedure to those 7 before effects, tactics and deployment."}],"result":{"ko":"명부 8명과 전투에 쓸 수 있는 크루는 같지 않습니다.","en":"The 8-model roster and the usable battle crew are not the same list."}},"pitfalls":[{"problem":{"ko":"전술을 고르고 배치까지 마친 뒤 회복 모델을 제외합니다.","en":"Removing a Recovery model only after choosing tactics and deploying."},"fix":{"ko":"크루 후보를 정리한 다음 그 크루와 시나리오 조건으로 나머지 준비를 진행합니다.","en":"Clean up crew candidates first, then complete preparation using that crew and the scenario."}}],"selfCheck":{"ko":"도전·시나리오·전장·크루·효과·전술·배치 순서를 말할 수 있나요?","en":"Can you name challenge, scenario, battlefield, crew, effects, tactics and deployment in order?"}},"tactics":{"objective":{"ko":"기본 전술과 레이팅 차이에 의한 추가 전술을 분리하고 사용 횟수를 추적합니다.","en":"Separate basic tactics from underdog extras and track their uses."},"preparation":[{"ko":"양쪽 레이팅과 시나리오의 전술 예외, 선택한 전술 카드의 발동 시점을 확인합니다.","en":"Check both Ratings, scenario tactic exceptions and the timing on selected cards."}],"walkthrough":[{"title":{"ko":"비교 기준 확인","en":"Confirm the comparison"},"body":{"ko":"레이팅 비교에 쓰는 명단과 시나리오 예외를 먼저 맞춥니다. 잔액까지 포함한 자산을 레이팅 대신 사용하지 않습니다.","en":"Agree the rosters used for comparison and any scenario exception. Do not substitute Wealth, which includes reserve credits, for Rating."},"result":{"ko":"추가 전술 계산의 입력값이 일치합니다.","en":"Both players use the same inputs."}},{"title":{"ko":"기본과 추가를 따로 적기","en":"Record basic and extra tactics"},"body":{"ko":"각 갱의 기본 전술 1개를 적고, 낮은 레이팅 쪽에 200크레딧 차이마다 추가되는 전술을 계산합니다.","en":"Record 1 basic tactic per gang, then calculate extras for each 200-credit difference for the lower-Rating gang."},"result":{"ko":"추가 전술을 기본 전술로 두 번 세지 않습니다.","en":"Basic tactics are not counted twice as extras."}},{"title":{"ko":"사용 시점과 소모 표시","en":"Track timing and use"},"body":{"ko":"카드의 대상·사용 시점을 읽은 뒤 사용 시 표시합니다. 전투당 한 번 쓴 카드를 다음 라운드에 다시 준비하지 않습니다.","en":"Read the card’s target and timing, then mark it used. Do not refresh a once-per-battle card next round."},"result":{"ko":"양쪽이 남은 전술을 같은 방식으로 확인합니다.","en":"Both players can check which tactics remain."}}],"workedExample":{"situation":{"ko":"비교 레이팅이 1200 대 800이고 별도 시나리오 수정이 없습니다.","en":"The compared Ratings are 1200 and 800 with no scenario modification."},"steps":[{"ko":"차이는 1200 − 800 = 400입니다.","en":"The difference is 1200 − 800 = 400."},{"ko":"400 ÷ 200 = 추가 2개이므로 낮은 쪽은 기본 1 + 추가 2 = 3개입니다.","en":"400 ÷ 200 = 2 extras, so the lower side receives 1 basic + 2 extra = 3."}],"result":{"ko":"높은 쪽 기본 1개, 낮은 쪽 총 3개이며 모두 각 카드의 사용 조건을 지킵니다.","en":"The higher side has its basic 1 and the lower side has 3 total, each still subject to its card conditions."}},"pitfalls":[{"problem":{"ko":"잔액이 많아 자산이 높다는 이유로 추가 전술을 빼거나 더합니다.","en":"Changing underdog tactics because reserve credits change Wealth."},"fix":{"ko":"규칙이 요구한 레이팅 기준으로 다시 비교하고 시나리오 예외만 따로 적용합니다.","en":"Compare the required Rating values again and apply only explicit scenario exceptions."}}],"selfCheck":{"ko":"전술 카드 한 장의 발동 시점·대상·전투당 사용 횟수를 설명할 수 있나요?","en":"Can you explain one card’s timing, target and uses per battle?"}},"priority":{"objective":{"ko":"첫 라운드 동점과 이후 라운드 동점을 구분해 우선권 보유자를 정합니다.","en":"Resolve priority by distinguishing first-round ties from later ties."},"preparation":[{"ko":"라운드 번호와 직전 우선권 보유자 표시, 양쪽 D6을 준비합니다.","en":"Have the round number, previous priority marker and both D6s ready."}],"walkthrough":[{"title":{"ko":"준비 상태 갱신","en":"Ready the models"},"body":{"ko":"새 라운드의 우선권 단계에 모델들을 준비 상태로 표시합니다. 지난 라운드에 활성화했다는 표시를 다음 라운드의 행동권과 혼동하지 않습니다.","en":"Ready models in the new round’s priority phase. Do not confuse last round’s activation marker with this round’s readiness."},"result":{"ko":"이번 라운드에 활성화할 후보가 표시됩니다.","en":"Candidates for this round’s activations are marked."}},{"title":{"ko":"대결하고 동점 조건 확인","en":"Roll and inspect a tie"},"body":{"ko":"양쪽 D6을 비교합니다. 첫 라운드 동점이면 재굴림하며, 이후 동점이면 직전 라운드에 우선권이 없던 쪽을 찾습니다.","en":"Compare both D6s. Reroll a first-round tie; for a later tie, identify who lacked priority last round."},"result":{"ko":"동점 처리에 사용할 규칙이 명확해집니다.","en":"The correct tie procedure is identified."}},{"title":{"ko":"표시를 옮기고 행동 단계로","en":"Move the marker and begin actions"},"body":{"ko":"이번 우선권 보유자를 표시하고 그쪽의 첫 준비 모델 활성화로 행동 단계를 시작합니다.","en":"Mark the new priority holder and start the action phase with that player’s first ready model."},"result":{"ko":"다음 라운드 동점에도 확인할 기록이 남습니다.","en":"A record remains for the next round’s tie."}}],"workedExample":{"situation":{"ko":"2라운드에서 양쪽이 4를 굴렸고 1라운드 우선권은 상대였습니다.","en":"In round 2 both players roll 4; the opponent held round-1 priority."},"steps":[{"ko":"첫 라운드가 아니므로 재굴림 조건을 적용하지 않습니다.","en":"It is not round 1, so do not apply the first-round reroll."},{"ko":"직전 우선권이 없던 나에게 우선권 표시를 옮깁니다.","en":"Move the priority marker to you, who lacked priority in the preceding round."}],"result":{"ko":"내가 첫 준비 모델을 활성화합니다. 갱 전체를 연속 활성화하는 권리는 아닙니다.","en":"You activate the first ready model; this is not permission to activate your whole gang consecutively."}},"pitfalls":[{"problem":{"ko":"동점이면 항상 재굴림해서 직전 우선권 정보를 버립니다.","en":"Rerolling every tie and ignoring previous priority."},"fix":{"ko":"라운드 1인지부터 확인하고, 아니라면 직전 보유자 표시를 사용합니다.","en":"First check whether it is round 1; otherwise use the previous holder marker."}}],"selfCheck":{"ko":"1라운드 동점과 2라운드 동점의 다른 처리법을 설명할 수 있나요?","en":"Can you explain how a round-1 tie differs from a round-2 tie?"},"exerciseHint":{"ko":"문제의 라운드 번호와 직전 우선권 보유자 두 정보를 먼저 찾으세요.","en":"Identify the round number and the previous priority holder first."},"optionFeedback":{"1":{"ko":"재굴림은 첫 라운드 동점의 처리입니다. 이 문제는 두 번째 라운드입니다.","en":"Rerolling applies to a first-round tie; this is round two."},"2":{"ko":"이전 라운드에 우선권이 없던 쪽을 정확히 골랐습니다.","en":"You correctly selected the player who lacked priority in the preceding round."},"3":{"ko":"동점 때 이전 보유자가 계속 갖는 방식이 아니라, 이전에 없던 쪽이 받습니다.","en":"A later tie goes to the player who lacked priority, not the previous holder."}}},"alternate":{"objective":{"ko":"준비 모델 하나의 행동을 마친 다음 상대에게 활성화를 넘기는 순서를 익힙니다.","en":"Finish one ready model’s actions before passing the activation to the opponent."},"preparation":[{"ko":"양쪽 준비 모델을 구분하고 이번 라운드 우선권 표시를 확인합니다.","en":"Identify ready models on both sides and the current priority holder."}],"walkthrough":[{"title":{"ko":"첫 모델 선택","en":"Choose the first model"},"body":{"ko":"우선권 보유자가 자기 준비 모델 하나를 고릅니다. 활성화할 수 없는 상태나 이미 소모한 준비 표시를 먼저 확인합니다.","en":"The priority holder chooses one ready model, checking its state and that its ready marker is still available."},"result":{"ko":"활성화 중인 모델이 분명해집니다.","en":"It is clear which model is activating."}},{"title":{"ko":"모델의 행동을 끝까지 해결","en":"Finish that model’s actions"},"body":{"ko":"그 모델의 행동을 선언하고 결과를 처리합니다. 한 행동의 굴림을 끝내기 전에 다른 모델로 넘어가지 않습니다.","en":"Declare the model’s actions and resolve them. Do not switch to another model before finishing an action’s rolls."},"result":{"ko":"행동·탄약·부상 결과가 같은 활성화 안에서 정리됩니다.","en":"Action, ammunition and injury effects remain in the correct activation."}},{"title":{"ko":"준비 표시 제거 후 교대","en":"Spend readiness and alternate"},"body":{"ko":"활성화가 끝나면 해당 모델의 준비 표시를 정리하고 상대가 다음 준비 모델을 고릅니다. 그룹 활성화는 명시된 별도 절차로 처리합니다.","en":"After activation, update the ready marker and let the opponent choose a ready model. Use the explicit procedure for Group Activation."},"result":{"ko":"같은 모델을 실수로 다시 활성화하지 않습니다.","en":"The same model is not accidentally activated twice."}}],"workedExample":{"situation":{"ko":"내 준비 모델 A·B와 상대 준비 모델 X·Y가 있고 내가 우선권입니다.","en":"You have ready models A and B; the opponent has X and Y; you hold priority."},"steps":[{"ko":"A의 허용 행동을 모두 해결하고 A의 준비 표시를 소모합니다.","en":"Resolve A’s allowed actions and spend A’s ready marker."},{"ko":"상대 X의 활성화 뒤 다음 내 차례에는 남아 있는 B를 선택할 수 있습니다.","en":"After X activates, your next choice can be the still-ready B."}],"result":{"ko":"기본 흐름은 A → X → B → Y처럼 모델 단위로 교대합니다.","en":"The normal flow alternates by model, for example A → X → B → Y."}},"pitfalls":[{"problem":{"ko":"우선권을 얻었으니 A와 B를 한꺼번에 움직입니다.","en":"Moving both A and B simply because you won priority."},"fix":{"ko":"예외가 없는 한 하나의 준비 모델만 활성화하고 상대에게 넘기세요.","en":"Without an exception, activate one ready model and pass to the opponent."}}],"selfCheck":{"ko":"누가 우선권인지와 어느 모델이 아직 준비 상태인지를 따로 표시했나요?","en":"Have you marked priority separately from which models remain ready?"}},"endphase":{"objective":{"ko":"행동 종료와 전투 종료를 구분하고 종료 단계 검사를 정해진 순서로 진행합니다.","en":"Distinguish the end of actions from the end of the battle and resolve end-phase checks in order."},"preparation":[{"ko":"이번 라운드 OOA 발생 기록과 시나리오 승리·목표 조건을 확인합니다.","en":"Have this round’s OOA events and the scenario victory/objective conditions available."}],"walkthrough":[{"title":{"ko":"행동 단계가 끝났는지 확인","en":"Confirm actions are finished"},"body":{"ko":"양쪽 준비 모델의 활성화를 정리하고 이번 라운드에 발생한 상태·OOA를 확인합니다.","en":"Finish the ready-model activations and check states and OOA events from this round."},"result":{"ko":"종료 단계에 사용할 사건 기록이 모입니다.","en":"The relevant end-phase event record is gathered."}},{"title":{"ko":"이탈과 승리·목표 검사","en":"Resolve Bottle and objectives"},"body":{"ko":"보틀 체크의 발동을 확인해 처리한 뒤 시나리오 승리와 목표 통제를 확인합니다. 목표 근처에 있다는 사실만으로 모든 모델이 통제하는 것은 아닙니다.","en":"Check and resolve Bottle triggers, then scenario victory and objective control. Being near an objective does not make every model eligible to control it."},"result":{"ko":"전투가 계속되는지 목표 점수가 어떻게 되는지 판단합니다.","en":"You determine whether play continues and how objectives resolve."}},{"title":{"ko":"증원과 다음 라운드 준비","en":"Resolve reinforcements and continue"},"body":{"ko":"증원 절차를 처리합니다. 시나리오가 끝나지 않았다면 다음 라운드 우선권 단계로 넘어갑니다.","en":"Resolve reinforcements. If the scenario has not ended, move to the next round’s priority phase."},"result":{"ko":"종료 단계에서 누락된 절차 없이 라운드를 이어 갑니다.","en":"The round advances without skipping end-phase procedures."}}],"workedExample":{"situation":{"ko":"이번 라운드에 우리 갱 모델 1명이 OOA가 되었지만 승리 조건은 아직 충족하지 않았습니다.","en":"One of your gang models went OOA this round, but victory conditions are not yet met."},"steps":[{"ko":"OOA 발생을 근거로 보틀 체크 발동 여부를 확인합니다.","en":"Use the OOA event to check the Bottle trigger."},{"ko":"목표·승리와 증원을 해결하고 전투가 계속되면 다음 우선권 단계로 갑니다.","en":"Resolve objectives/victory and reinforcements, then go to the next priority phase if battle continues."}],"result":{"ko":"모델 하나의 OOA만으로 전투가 자동 종료되지는 않습니다.","en":"A single OOA model does not automatically end the battle."}},"pitfalls":[{"problem":{"ko":"모든 모델이 활성화됐으므로 보상과 성장 정산으로 바로 갑니다.","en":"Jumping straight to rewards and advancements after all models activate."},"fix":{"ko":"종료 단계와 시나리오의 실제 전투 종료 조건부터 확인합니다.","en":"First resolve the end phase and the scenario’s actual battle-ending conditions."}}],"selfCheck":{"ko":"보틀 체크 → 승리·목표 → 증원 뒤 계속 여부를 판단할 수 있나요?","en":"Can you follow Bottle → victory/objectives → reinforcements before deciding whether to continue?"}},"sequence-practice":{"objective":{"ko":"첫 라운드 시작을 우선권 판정부터 모델 단위 교대까지 연결해 설명합니다.","en":"Connect the first priority roll to alternating model activations."},"preparation":[{"ko":"배치가 끝난 가상 전장과 아직 활성화하지 않은 준비 모델을 가정합니다.","en":"Assume deployment is complete and all ready models have yet to activate."}],"walkthrough":[{"title":{"ko":"준비 완료 지점 확인","en":"Confirm the start point"},"body":{"ko":"크루·효과·전술·배치를 마쳤는지 확인합니다. 배치 순서와 라운드 우선권 판정을 같은 절차로 취급하지 않습니다.","en":"Confirm crew, effects, tactics and deployment are complete. Deployment order and round priority are separate procedures."},"result":{"ko":"우선권 단계에서 시작할 준비가 됩니다.","en":"You are ready to start the priority phase."}},{"title":{"ko":"첫 동점 재굴림","en":"Reroll the first tie"},"body":{"ko":"첫 라운드 양쪽 D6이 같으면 우선권이 정해질 때까지 해당 동점 절차를 다시 적용합니다.","en":"When the first-round D6s tie, apply the first-round tie procedure again until priority is resolved."},"result":{"ko":"행동을 먼저 시작할 플레이어가 결정됩니다.","en":"The player who acts first is determined."}},{"title":{"ko":"승자의 한 모델부터 교대","en":"Alternate from the winner’s model"},"body":{"ko":"승자가 준비 모델 하나를 활성화하고 끝나면 상대의 준비 모델 차례가 됩니다.","en":"The winner activates one ready model; when it finishes, the opponent chooses a ready model."},"result":{"ko":"첫 우선권 승리가 갱 전체 연속 활성화로 바뀌지 않습니다.","en":"Winning first priority does not become consecutive activations for the entire gang."}}],"workedExample":{"situation":{"ko":"첫 굴림은 3 대 3, 재굴림은 내 5 대 상대 2입니다.","en":"The first roll is 3–3; the reroll is your 5 against the opponent’s 2."},"steps":[{"ko":"3 대 3은 첫 라운드 동점이므로 재굴림합니다.","en":"Reroll 3–3 because it is a first-round tie."},{"ko":"5 대 2로 내가 우선권을 얻고 내 준비 모델 하나를 먼저 활성화합니다.","en":"The 5–2 result gives you priority and you activate one ready model first."}],"result":{"ko":"그 모델이 끝나면 상대에게 넘기며, 즉시 종료 단계로 건너뛰지 않습니다.","en":"Pass to the opponent after that model finishes; do not skip directly to the end phase."}},"pitfalls":[{"problem":{"ko":"재굴림에서 이겼으니 상대 준비 모델을 소모시킵니다.","en":"Spending the opponent’s ready markers because you won the reroll."},"fix":{"ko":"우선권은 첫 활성화 순서를 정합니다. 상대 준비 상태는 정상 절차로 유지합니다.","en":"Priority determines first activation order; the opponent’s ready models remain available normally."}}],"selfCheck":{"ko":"첫 동점 처리와 그 뒤 첫 두 활성화를 순서대로 말할 수 있나요?","en":"Can you describe the first tie procedure and the first two activations in order?"},"exerciseHint":{"ko":"먼저 첫 라운드 동점 규칙을 적용하고, 우선권의 의미를 한 모델의 첫 활성화로 생각하세요.","en":"Apply the first-round tie rule, then think of priority as the first activation of one model."},"optionFeedback":{"1":{"ko":"방어자라는 이유만으로 모든 모델을 연속 활성화하지 않습니다.","en":"Being the defender does not grant consecutive activations of every model."},"2":{"ko":"첫 동점을 재굴림한 뒤 승자부터 준비 모델 하나씩 교대하는 전체 순서를 맞췄습니다.","en":"This correctly rerolls the first tie and then alternates one ready model from the winner."},"3":{"ko":"아직 준비 모델의 행동 단계가 남아 있으므로 종료 단계로 바로 갈 수 없습니다.","en":"The ready models still have an action phase; it cannot be skipped."}}}},"activation-states":{"two-actions":{"objective":{"ko":"행동 이름별 허용 여부와 비용을 따로 검사해 활성화 예산 2개를 배분합니다.","en":"Check action legality separately from cost before spending the normal two-action budget."},"preparation":[{"ko":"활성화할 모델의 현재 상태와 사용할 행동의 싱글·더블·프리 표시를 확인합니다.","en":"Check the model’s state and the Single, Double or Free label on intended actions."}],"walkthrough":[{"title":{"ko":"행동 예산 적기","en":"Set the action budget"},"body":{"ko":"일반 활성화는 행동 2개로 시작합니다. 제압처럼 예산을 바꾸는 상태가 있다면 그 조건부터 적용합니다.","en":"A normal activation starts with 2 actions. Apply any state that changes the budget, such as Suppression, first."},"result":{"ko":"현재 모델의 실제 예산이 정해집니다.","en":"You know this model’s actual allowance."}},{"title":{"ko":"비용과 중복 검사","en":"Check cost and repetition"},"body":{"ko":"싱글 1, 더블 2, 프리 0으로 셉니다. 예산이 남아도 같은 이름 행동 반복은 기본 금지임을 따로 확인합니다.","en":"Count Single as 1, Double as 2 and Free as 0. Separately check the normal prohibition on repeating a named action, even with spare budget."},"result":{"ko":"숫자만 맞고 불법인 행동 조합을 걸러냅니다.","en":"You catch combinations that fit numerically but are illegal."}},{"title":{"ko":"한 행동씩 해결","en":"Resolve one action at a time"},"body":{"ko":"첫 행동을 선언해 모든 결과를 처리한 뒤 다음 행동을 선언합니다. 프리 행동도 이를 허용하는 규칙과 조건이 필요합니다.","en":"Declare and fully resolve the first action before declaring the next. A Free action still needs a rule and conditions allowing it."},"result":{"ko":"미리 예상한 결과가 아니라 실제 결과로 다음 행동을 정합니다.","en":"The next action follows actual results rather than assumed ones."}}],"workedExample":{"situation":{"ko":"정상 액티브 모델이 슈트와 무브를 각각 한 번 하려 합니다.","en":"A normal Active model wants to Shoot once and Move once."},"steps":[{"ko":"슈트 싱글 1 + 무브 싱글 1 = 2입니다.","en":"Shoot (Single) 1 + Move (Single) 1 = 2."},{"ko":"서로 다른 이름이며 각각의 표적·경로 조건도 확인합니다.","en":"They have different names; also check the target and path conditions."}],"result":{"ko":"기본 예산 안의 조합입니다. 첫 행동 결과로 두 번째 행동의 가능성은 다시 확인합니다.","en":"The combination fits the normal budget; recheck the second action after the first action’s result."}},"pitfalls":[{"problem":{"ko":"프리는 비용이 없으니 원하는 만큼 아무 행동이나 할 수 있다고 생각합니다.","en":"Assuming Free means unlimited permission to perform any action."},"fix":{"ko":"어떤 규칙이 프리 행동을 허용하는지와 그 발동 조건부터 찾습니다.","en":"Identify the rule allowing the Free action and check its trigger first."}}],"selfCheck":{"ko":"행동 비용 계산과 같은 이름 반복 검사 두 가지를 따로 했나요?","en":"Have you checked action cost separately from repeated action names?"}},"state-priority":{"objective":{"ko":"동시에 여러 상태가 맞는 것처럼 보일 때 우선순위로 현재 전투 상태를 하나 정합니다.","en":"Use state priority to identify one current battle state when several seem applicable."},"preparation":[{"ko":"교전 거리, 제압 표시와 중상·손상 상태, 별도의 캠페인 회복 기록을 확인합니다.","en":"Check engagement, Suppression, Serious Injury/Damage and the separate campaign Recovery record."}],"walkthrough":[{"title":{"ko":"전투와 캠페인 구분","en":"Separate battle and campaign status"},"body":{"ko":"액티브·인게이지드·서프레스드·시리어슬리 인저드/대미지드를 전투 상태로 확인합니다. 회복·사망 같은 캠페인 기록과 섞지 않습니다.","en":"Identify Active, Engaged, Suppressed and Seriously Injured/Damaged as battle states. Keep campaign Recovery and death separate."},"result":{"ko":"서로 다른 시간 범위의 기록을 구분합니다.","en":"You separate records used at different times."}},{"title":{"ko":"가장 높은 상태 선택","en":"Select the highest-priority state"},"body":{"ko":"중상·손상 → 교전 → 제압 → 액티브 순서로 검사합니다. 더 높은 조건이 맞으면 낮은 상태를 이유로 행동을 고르지 않습니다.","en":"Check Serious Injury/Damage → Engaged → Suppressed → Active. Do not choose actions from a lower state when a higher condition applies."},"result":{"ko":"현재 사용할 행동 목록을 선택할 기준이 생깁니다.","en":"You know which state’s action list to consult."}},{"title":{"ko":"상태 변화 뒤 다시 확인","en":"Recheck after a state changes"},"body":{"ko":"행동이나 부상 결과로 상위 조건이 사라졌다면 남아 있는 다른 조건을 다시 검사합니다. 임의로 항상 액티브로 돌리지 않습니다.","en":"After an action or injury removes a higher condition, check the remaining conditions again. Do not automatically reset to Active."},"result":{"ko":"새 상황에 맞는 상태로 계속 진행합니다.","en":"Play continues with the state matching the new situation."}}],"workedExample":{"situation":{"ko":"제압 표시가 있는 모델이 적과 교전 중이고, 이어 중상 결과를 받았습니다.","en":"A model has Suppression and is engaged, then receives a Serious Injury result."},"steps":[{"ko":"교전만 있었을 때는 교전이 제압보다 우선합니다.","en":"With engagement alone, Engaged takes priority over Suppressed."},{"ko":"중상 조건이 생기면 중상이 교전보다 우선하므로 중상 행동·회복 절차를 확인합니다.","en":"Once Seriously Injured, that state takes priority over Engaged; consult its actions and recovery procedure."}],"result":{"ko":"제압·교전·중상의 이점을 동시에 골라 쓰지 않습니다.","en":"You do not mix selected benefits from Suppressed, Engaged and Seriously Injured states."}},"pitfalls":[{"problem":{"ko":"서 있는 모델처럼 보인다는 이유로 카드의 중상 상태를 무시합니다.","en":"Ignoring Serious Injury because of how the miniature appears to stand."},"fix":{"ko":"기록된 전투 결과와 상태 우선순위를 기준으로 판정하고 필요한 표시를 맞춥니다.","en":"Use recorded battle results and state priority, then align the physical markers."}}],"selfCheck":{"ko":"제압과 교전이 겹칠 때, 교전과 중상이 겹칠 때의 우선 상태를 말할 수 있나요?","en":"Can you name the priority state for Suppressed plus Engaged, and Engaged plus Seriously Injured?"}},"action-choice":{"objective":{"ko":"남은 행동 수가 있어도 같은 행동을 반복하거나 다른 상태의 행동을 쓸 수 없음을 확인합니다.","en":"Recognize that spare actions do not permit repeats or actions from another battle state."},"preparation":[{"ko":"현재 상태의 행동 목록과 이미 이번 활성화에 수행한 행동 이름을 적습니다.","en":"List actions for the current state and names already performed this activation."}],"walkthrough":[{"title":{"ko":"상태에 맞는 목록 선택","en":"Choose the state’s action list"},"body":{"ko":"제압은 보통 행동 1개, 교전은 파이트·리트리트 등 교전 행동을 확인합니다. 중상 모델은 크롤 등 해당 상태 행동을 확인합니다.","en":"Suppressed models normally have 1 action; Engaged models consult actions such as Fight or Retreat; Seriously Injured models check actions such as Crawl."},"result":{"ko":"현재 상태에서 가능한 행동 후보만 남깁니다.","en":"Only actions eligible for the current state remain."}},{"title":{"ko":"같은 이름 제외","en":"Exclude repeated names"},"body":{"ko":"이미 무브를 했다면 예외가 없는 한 다시 무브를 후보로 넣지 않습니다. 행동의 유형 이름만 바꾸는 것으로 반복 제한을 우회하지 않습니다.","en":"After Move, do not offer Move again without an exception. Changing an action’s type label does not bypass the named-action restriction."},"result":{"ko":"남은 예산과 반복 허용을 혼동하지 않습니다.","en":"Spare budget is not confused with repeat permission."}},{"title":{"ko":"조건을 확인하고 결정","en":"Check conditions and decide"},"body":{"ko":"표적·거리·상태·장비 조건을 읽은 뒤 실제로 가능한 행동을 고릅니다. 적법한 행동이 없다면 불가능한 행동을 강제로 만들지 않습니다.","en":"Check target, distance, state and equipment requirements before choosing. Do not force an illegal action when none is available."},"result":{"ko":"행동 비용과 허용 조건을 모두 만족합니다.","en":"Both action cost and permission are satisfied."}}],"workedExample":{"situation":{"ko":"액티브 모델이 무브 싱글로 1개를 썼고 행동 1개가 남았습니다.","en":"An Active model spent 1 action on Move (Single) and has 1 action left."},"steps":[{"ko":"무브는 이번 활성화에 이미 사용한 이름입니다.","en":"Move is already a performed named action this activation."},{"ko":"예외가 없으므로 두 번째 무브 대신 다른 허용 싱글 행동을 검토합니다.","en":"Without an exception, consider a different eligible Single action rather than another Move."}],"result":{"ko":"남은 행동 1개가 두 번째 무브를 허용하지는 않습니다.","en":"The remaining action does not permit a second Move."}},"pitfalls":[{"problem":{"ko":"싱글 무브를 심플 무브라고 부르면 다시 할 수 있다고 생각합니다.","en":"Assuming that renaming Single Move as Simple Move allows a repeat."},"fix":{"ko":"선택한 판본의 실제 행동 이름과 반복 제한을 적용합니다.","en":"Use the selected edition’s actual action names and repeat restriction."}}],"selfCheck":{"ko":"현재 상태와 이미 사용한 행동 이름을 둘 다 확인했나요?","en":"Have you checked both the current state and the action names already used?"},"exerciseHint":{"ko":"행동 예산과 같은 이름 행동의 반복 허용은 서로 다른 조건입니다.","en":"Action budget and permission to repeat a named action are separate conditions."},"optionFeedback":{"1":{"ko":"예산 1개가 남아도 같은 이름 행동의 반복 제한은 계속 적용됩니다.","en":"Having 1 action left does not remove the repeated-name restriction."},"2":{"ko":"반복 금지와 남은 예산을 올바르게 분리했습니다. 명시적 예외가 있어야 반복합니다.","en":"You correctly separated spare budget from repeat permission; an explicit exception is required."},"3":{"ko":"유형 명칭을 바꿔도 무브라는 같은 이름의 행동이라는 사실은 바뀌지 않습니다.","en":"Changing a type label does not change the repeated action name Move."}}},"combat-actions":{"objective":{"ko":"슈트·에임드 슈트·브레이스드 슈트·차지의 비용과 무기 조건을 선택 전에 비교합니다.","en":"Compare costs and weapon requirements for Shoot, Aimed Shoot, Braced Shoot and Charge before choosing."},"preparation":[{"ko":"사용 무기에 헤비 특성이 있는지와 표적까지의 시야·거리를 확인합니다.","en":"Check whether the weapon is Heavy and inspect line of sight and range to the target."}],"walkthrough":[{"title":{"ko":"무기 조건부터 구분","en":"Start with the weapon"},"body":{"ko":"일반 슈트는 비헤비 원거리 무기용 싱글입니다. 헤비 무기라면 브레이스드 슈트 등 실제 허용 행동을 확인합니다.","en":"Normal Shoot is Single for a non-Heavy ranged weapon. For a Heavy weapon, check a permitted action such as Braced Shoot."},"result":{"ko":"사용할 수 없는 슈트를 미리 걸러냅니다.","en":"An ineligible Shoot is rejected before rolling."}},{"title":{"ko":"더블 행동과 잔여 예산","en":"Check Double actions and remaining budget"},"body":{"ko":"에임드 슈트는 더블로 명중 +1, 브레이스드 슈트도 더블입니다. 기본 행동 2개를 모두 쓰므로 이후 싱글 이동을 덧붙이지 않습니다.","en":"Aimed Shoot is Double for +1 to hit, and Braced Shoot is also Double. Each spends the normal 2 actions, leaving no extra Single Move."},"result":{"ko":"정확도·헤비 사격과 기동의 차이를 판단합니다.","en":"You can judge the trade-off between shooting choice and mobility."}},{"title":{"ko":"차지의 추가 행동 조건","en":"Check Charge follow-up permission"},"body":{"ko":"차지는 더블입니다. 성공 시 허용되는 프리 파이트나 라스트 블로는 차지의 명시적 허용에 따라 처리합니다.","en":"Charge is Double. Resolve the allowed Free Fight or Last Blow after a successful charge under its explicit permission."},"result":{"ko":"프리 후속 행동을 아무 상황에서나 쓰지 않습니다.","en":"The free follow-up is not applied outside its allowed situation."}}],"workedExample":{"situation":{"ko":"비헤비 무기를 든 액티브 모델이 사격 후 엄폐로 이동하고 싶습니다.","en":"An Active model with a non-Heavy weapon wants to shoot and then enter cover."},"steps":[{"ko":"슈트 1 + 무브 1은 기본 행동 2개에 맞습니다.","en":"Shoot 1 + Move 1 fits the normal 2 actions."},{"ko":"에임드 슈트 2 + 무브 1은 3이므로 기본 예산을 넘습니다.","en":"Aimed Shoot 2 + Move 1 totals 3 and exceeds the normal budget."}],"result":{"ko":"이번 활성화에 이동이 필요하다면 일반 슈트와 이동의 조합을 검토합니다.","en":"If moving this activation matters, consider normal Shoot plus Move."}},"pitfalls":[{"problem":{"ko":"에임드 슈트의 +1만 얻고 비용은 일반 슈트처럼 1개로 셉니다.","en":"Taking Aimed Shoot’s +1 but paying only the normal Shoot cost of 1."},"fix":{"ko":"보정뿐 아니라 행동 이름·유형·비용을 한 묶음으로 적용합니다.","en":"Apply the modifier together with the action’s name, type and cost."}}],"selfCheck":{"ko":"내 무기가 헤비일 때와 아닐 때 사용할 사격 행동을 각각 고를 수 있나요?","en":"Can you choose an eligible shooting action for both Heavy and non-Heavy weapons?"}},"group-actions":{"objective":{"ko":"그룹 활성화를 추가 모델의 공짜 행동권으로 취급하지 않고 거리·준비·리더십 조건으로 처리합니다.","en":"Resolve Group Activation through readiness, range and Leadership rather than treating it as free extra actions."},"preparation":[{"ko":"행동 모델의 Ld와 3인치 안의 준비된 아군 전투원을 확인합니다.","en":"Check the acting model’s Ld and ready friendly fighters within 3 inches."}],"walkthrough":[{"title":{"ko":"대상 후보 정하기","en":"Select eligible candidates"},"body":{"ko":"그룹 활성화 싱글을 선언할 모델과 준비된 아군 전투원 후보를 정합니다. 선택한 각 모델이 3인치 안에 있는지 확인합니다.","en":"Choose the acting model and ready friendly fighter candidates for Group Activation (Single). Check every selected model is within 3 inches."},"result":{"ko":"거리 밖이나 이미 활성화한 모델을 제외합니다.","en":"Out-of-range or already activated models are excluded."}},{"title":{"ko":"선택 수만큼 보정 계산","en":"Calculate the selection modifier"},"body":{"ko":"선택한 전투원마다 리더십 체크에 −1을 적용합니다. 많이 고르는 것의 위험을 선택 전에 확인합니다.","en":"Apply −1 to the Leadership check per selected fighter. Consider the increased difficulty before selecting more models."},"result":{"ko":"실제 체크의 수정을 공개할 수 있습니다.","en":"You can state the check’s actual modifier."}},{"title":{"ko":"성공 시 정해진 순서 실행","en":"Follow the successful sequence"},"body":{"ko":"성공하면 행동 모델 뒤에 선택 모델을 순서대로 활성화합니다. 각 모델의 상태·장비·행동 예산을 그대로 확인합니다.","en":"On success, activate the selected models in order after the acting model. Each still checks its own state, equipment and action allowance."},"result":{"ko":"그룹이라는 이유로 상태나 행동 제한을 무시하지 않습니다.","en":"Being in a group does not remove state or action restrictions."}}],"workedExample":{"situation":{"ko":"준비된 아군 2명이 모두 3인치 안에 있어 둘 다 선택하려 합니다.","en":"Two ready friendly fighters are within 3 inches and you want to select both."},"steps":[{"ko":"선택 수는 2명이므로 체크 수정은 −2입니다.","en":"Selecting 2 fighters gives a −2 modifier to the check."},{"ko":"체크에 성공해야 선택한 두 전투원이 행동 모델 뒤에 순서대로 활성화합니다.","en":"The check must succeed before those two fighters activate in order after the acting model."}],"result":{"ko":"두 모델을 선택했다는 선언만으로 활성화가 보장되지 않습니다.","en":"Merely declaring two selected models does not guarantee their activations."}},"pitfalls":[{"problem":{"ko":"그룹 활성화에 선택했으니 이미 활성화한 아군도 다시 행동시킵니다.","en":"Reactivating an already activated ally because it was selected for the group."},"fix":{"ko":"선택 단계에서 준비 상태인지 확인하고 각 모델의 활성화를 한 번씩 추적합니다.","en":"Check readiness when selecting and track each model’s activation."}}],"selfCheck":{"ko":"전투원 1명·2명 선택 시 체크 수정이 각각 얼마인지 말할 수 있나요?","en":"Can you state the check modifier for selecting 1 fighter and then 2 fighters?"}},"activation-practice":{"objective":{"ko":"기동 사격 계획을 무기 조건·행동 비용·처리 순서로 나눠 검증합니다.","en":"Validate a shoot-and-move plan through weapon permission, action costs and resolution order."},"preparation":[{"ko":"액티브 전투원, 비헤비 무기, 적법한 표적과 이동 경로라는 연습 조건을 확인합니다.","en":"Assume an Active fighter, non-Heavy weapon, legal target and legal movement path."}],"walkthrough":[{"title":{"ko":"조건을 먼저 고정","en":"Fix the scenario conditions"},"body":{"ko":"표적 시야·사거리가 있고 경로도 적법하다는 조건에서 시작합니다. 헤비 무기나 제압 상태의 다른 상황을 섞지 않습니다.","en":"Start with a visible in-range target and legal path. Do not mix in the different conditions of a Heavy weapon or Suppression."},"result":{"ko":"계산할 상황이 명확합니다.","en":"The scenario being evaluated is clear."}},{"title":{"ko":"각 조합의 합계 비교","en":"Compare each total"},"body":{"ko":"슈트 싱글과 무브 싱글은 1 + 1, 에임드 슈트 더블과 무브 싱글은 2 + 1로 셉니다.","en":"Count Shoot (Single) plus Move (Single) as 1 + 1, and Aimed Shoot (Double) plus Move (Single) as 2 + 1."},"result":{"ko":"기본 2개에 들어가는 조합을 찾습니다.","en":"You identify which combination fits the normal 2 actions."}},{"title":{"ko":"첫 행동 뒤 재평가","en":"Recheck after the first action"},"body":{"ko":"슈트 결과와 관련 특성을 모두 해결한 뒤 현재 상태와 경로를 다시 확인해 무브를 선언합니다.","en":"Fully resolve Shoot and relevant traits, then recheck state and path before declaring Move."},"result":{"ko":"예정된 이동을 결과와 상관없이 자동 실행하지 않습니다.","en":"A planned move is not executed regardless of intervening results."}}],"workedExample":{"situation":{"ko":"일반 슈트 뒤 무브와, 에임드 슈트 뒤 무브를 비교합니다.","en":"Compare normal Shoot then Move with Aimed Shoot then Move."},"steps":[{"ko":"일반 슈트 1 + 무브 1 = 2로 적법한 기본 비용입니다.","en":"Normal Shoot 1 + Move 1 = 2, a valid normal cost."},{"ko":"에임드 슈트 2 + 무브 1 = 3으로 별도 허용 없이는 불가능합니다.","en":"Aimed Shoot 2 + Move 1 = 3, requiring a separate permission."}],"result":{"ko":"사격 후 기동이라는 목적에는 슈트 싱글 → 무브 싱글을 선택합니다.","en":"For the intended shooting then repositioning plan, choose Shoot (Single) → Move (Single)."}},"pitfalls":[{"problem":{"ko":"더블의 단어를 행동 두 종류라는 뜻으로 읽습니다.","en":"Reading Double as two different actions rather than a cost."},"fix":{"ko":"더블은 기본 행동 2개를 쓰는 행동 하나라는 점으로 다시 계산합니다.","en":"Recalculate Double as one action costing both normal action points."}}],"selfCheck":{"ko":"정답 조합이 합계 2인 이유와 다른 두 조합이 넘치는 이유를 설명할 수 있나요?","en":"Can you explain why the correct total is 2 and why the other combinations exceed it?"},"exerciseHint":{"ko":"싱글은 1, 더블은 2로 바꿔 각 보기의 합계를 계산하세요.","en":"Replace Single with 1 and Double with 2, then add each option’s costs."},"optionFeedback":{"1":{"ko":"에임드 슈트 2 + 무브 1 = 3으로 기본 예산 2개를 넘습니다.","en":"Aimed Shoot 2 + Move 1 = 3, exceeding the normal budget of 2."},"2":{"ko":"비헤비 슈트 1과 무브 1이 합계 2이며 서로 다른 이름입니다.","en":"Non-Heavy Shoot 1 plus Move 1 totals 2 and uses different named actions."},"3":{"ko":"더블 두 개는 2 + 2 = 4이며 기본 예산의 두 배입니다.","en":"Two Double actions cost 2 + 2 = 4, twice the normal allowance."}}}},"movement-terrain":{"distance":{"objective":{"ko":"이동의 직선 거리 대신 실제 경로와 높이를 재고 적법한 종료 위치를 정합니다.","en":"Measure the actual path and height, then choose a legal final position."},"preparation":[{"ko":"모델의 M과 베이스 위치, 지형 종류, 다른 모델 위치를 확인합니다.","en":"Check M, base position, terrain types and other models."}],"walkthrough":[{"title":{"ko":"경로를 먼저 표시","en":"Plan the path"},"body":{"ko":"일반 전투원 이동은 꺾인 경로를 정할 수 있지만 차지·인게이지는 최단 경로를 확인합니다. 통과할 수 없는 고체 지형과 다른 모델을 피합니다.","en":"An ordinary fighter move can follow a bent path; Charge and Engage use the shortest path. Avoid solid obstacles and other models."},"result":{"ko":"직선으로 잰 값과 실제 경로를 구별합니다.","en":"Straight-line separation is distinguished from actual travel."}},{"title":{"ko":"구간별로 측정","en":"Measure each segment"},"body":{"ko":"방향이 바뀌는 곳과 높이가 바뀌는 곳을 나눠 인치로 측정합니다. 어려운 지형이나 등반의 추가 비용도 같은 구간에 적용합니다.","en":"Measure bends and height changes as separate inch segments. Apply difficult-terrain or climbing costs to the relevant segments."},"result":{"ko":"소모할 이동량을 구간 합계로 계산합니다.","en":"Movement spent can be totaled by segment."}},{"title":{"ko":"끝 위치 검증","en":"Verify the endpoint"},"body":{"ko":"허용량을 모두 쓸 필요는 없습니다. 종료 지점이 지형 안이나 다른 모델 위가 아닌지, 적 근접 제한이나 선언 행동 조건에 맞는지 확인합니다.","en":"You need not spend the full allowance. Check the endpoint is not inside terrain or another model and respects enemy proximity and action conditions."},"result":{"ko":"짧게 멈추더라도 적법한 이동이 됩니다.","en":"Stopping short can still produce a legal move."}}],"workedExample":{"situation":{"ko":"일반 지형에서 벽을 돌아 2인치, 이어 2인치 이동하는 M 5 전투원입니다.","en":"An M 5 fighter takes 2 inches around a wall and another 2 inches on ordinary ground."},"steps":[{"ko":"꺾인 두 구간을 더하면 2 + 2 = 4인치입니다.","en":"The bent path totals 2 + 2 = 4 inches."},{"ko":"M 5 중 4를 사용하고 적법한 위치에서 멈춥니다. 나머지 1을 반드시 쓸 필요는 없습니다.","en":"Spend 4 of M 5 and stop legally; the remaining 1 need not be used."}],"result":{"ko":"벽을 가로지른 직선 거리가 아니라 실제 4인치 경로를 적용합니다.","en":"Use the actual 4-inch route rather than a straight line through the wall."}},"pitfalls":[{"problem":{"ko":"시작점과 도착점의 직선 거리만 재고 벽을 통과합니다.","en":"Measuring only endpoint separation and moving through a wall."},"fix":{"ko":"통과 가능한 경로의 각 구간을 먼저 정해 다시 측정합니다.","en":"Plan traversable segments first, then measure them."}}],"selfCheck":{"ko":"이동 경로·소모량·종료 지점을 각각 보여 줄 수 있나요?","en":"Can you identify the route, allowance spent and final position separately?"}},"distances":{"objective":{"ko":"M·I·D6를 사용하는 서로 다른 이동 행동의 거리와 비용을 함께 비교합니다.","en":"Compare movement formulas together with their action costs."},"preparation":[{"ko":"현재 모델의 M·I와 선언할 무브·런·차지·인게이지 행동을 확인합니다.","en":"Check the model’s M and I and the intended Move, Run, Charge or Engage action."}],"walkthrough":[{"title":{"ko":"행동과 비용 선택","en":"Choose action and cost"},"body":{"ko":"무브 싱글, 런 더블, 차지 더블, 인게이지 싱글을 구분합니다. 이동 거리만 보고 서로 대체하지 않습니다.","en":"Distinguish Move (Single), Run (Double), Charge (Double) and Engage (Single). Similar travel distances do not make them interchangeable."},"result":{"ko":"예산에 맞는 행동 후보가 정해집니다.","en":"Eligible actions are selected within the budget."}},{"title":{"ko":"해당 거리식 계산","en":"Use the action’s formula"},"body":{"ko":"무브 M, 런 M+I, 차지 M+D6, 인게이지 D6를 적용합니다. I는 런 계산의 해당 능력치이며 차지 주사위를 대신하지 않습니다.","en":"Use M for Move, M+I for Run, M+D6 for Charge and D6 for Engage. I belongs in the Run formula, not in place of the Charge die."},"result":{"ko":"선언한 행동의 최대 이동량을 얻습니다.","en":"You obtain the declared action’s allowance."}},{"title":{"ko":"표적·차량 조건 확인","en":"Check target and vehicle conditions"},"body":{"ko":"차지·인게이지의 표적과 최단 경로 조건을 확인합니다. 차량은 전진·회전과 이동 하위유형의 별도 조건을 읽습니다.","en":"Check Charge/Engage targets and shortest-path conditions. For vehicles, read forward movement, turns and movement-subtype rules."},"result":{"ko":"거리가 충분하다는 이유만으로 모든 이동이 허용되지는 않음을 확인합니다.","en":"Sufficient distance alone does not make every move legal."}}],"workedExample":{"situation":{"ko":"M 5, I 3인 일반 전투원이 있고 차지 D6 결과를 2로 가정합니다.","en":"A normal fighter has M 5 and I 3; assume a Charge D6 result of 2."},"steps":[{"ko":"무브는 5, 런은 5 + 3 = 8인치입니다.","en":"Move is 5 inches and Run is 5 + 3 = 8 inches."},{"ko":"차지는 5 + 2 = 7인치입니다. 인게이지는 해당 D6 결과만 사용합니다.","en":"Charge is 5 + 2 = 7 inches; Engage uses only its D6 result."}],"result":{"ko":"같은 모델도 행동별 거리식·비용·표적 조건이 다릅니다.","en":"The same model has different formulas, costs and target conditions for different actions."}},"pitfalls":[{"problem":{"ko":"런의 M+I 대신 M을 두 배로 해서 거리를 잡습니다.","en":"Doubling M for Run instead of using M+I."},"fix":{"ko":"N26에서 선택한 행동의 거리식을 직접 읽고 대입합니다.","en":"Read the N26 action formula directly before substituting values."}}],"selfCheck":{"ko":"M 5, I 3에서 런 거리와 차지 주사위 2일 때 거리를 구분할 수 있나요?","en":"Can you distinguish Run distance from Charge with a roll of 2 for M 5, I 3?"}},"difficult":{"objective":{"ko":"실제 이동한 거리와 소모 이동량을 분리하고 위험 지형 판정까지 처리합니다.","en":"Separate physical distance from movement spent and include the dangerous-terrain check."},"preparation":[{"ko":"어떤 구간이 일반·어려운·위험 지형인지 시작 전에 합의합니다.","en":"Agree which route segments are ordinary, difficult or dangerous before play."}],"walkthrough":[{"title":{"ko":"구간을 분리","en":"Split the route"},"body":{"ko":"일반 지형과 어려운 지형을 별도로 측정합니다. 모두 어려운 지형인 것처럼 전체 거리를 두 배로 만들지 않습니다.","en":"Measure ordinary and difficult sections separately. Do not double the entire route when only one section is difficult."},"result":{"ko":"각 비용을 적용할 범위가 명확합니다.","en":"The segments receiving each cost are clear."}},{"title":{"ko":"이동 비용 합산","en":"Total movement cost"},"body":{"ko":"일반은 실제 거리, 어려운 지형은 1인치당 이동량 2인치로 계산해 더합니다. 남은 허용량과 비교합니다.","en":"Count ordinary distance normally and difficult ground at 2 inches of allowance per inch traveled. Add and compare with the remaining allowance."},"result":{"ko":"경로를 실제로 끝까지 갈 수 있는지 판단합니다.","en":"You can tell whether the route can be completed."}},{"title":{"ko":"위험 지형 추가 검사","en":"Check dangerous terrain"},"body":{"ko":"위험 지형은 같은 이동 비용 외에 통과 후 D6 위험 판정을 합니다. 1이면 자동 운드·세이브 불가 L1 명중을 해결합니다.","en":"Dangerous terrain also uses that movement cost and adds a hazard D6 after crossing. A 1 causes an automatically wounding, no-save L1 hit."},"result":{"ko":"이동량 지불과 위험 결과를 모두 해결합니다.","en":"Both movement spending and hazard consequences are resolved."}}],"workedExample":{"situation":{"ko":"M 5 모델의 경로가 일반 1인치와 어려운 지형 2인치입니다.","en":"An M 5 model’s route contains 1 ordinary inch and 2 difficult inches."},"steps":[{"ko":"일반 1은 이동량 1, 어려운 2는 2 × 2 = 4를 씁니다.","en":"The ordinary section spends 1; the difficult section spends 2 × 2 = 4."},{"ko":"합계 1 + 4 = 5로 허용량을 모두 씁니다. 실제 전진 거리는 3인치입니다.","en":"Total spending is 1 + 4 = 5, using the whole allowance; physical travel is 3 inches."}],"result":{"ko":"소모량 5와 실제 거리 3은 모두 맞는 서로 다른 값입니다.","en":"Spent allowance 5 and physical distance 3 are both correct but describe different things."}},"pitfalls":[{"problem":{"ko":"어려운 지형 이동량을 지불했으니 위험 지형의 주사위도 생략합니다.","en":"Skipping the hazard die because difficult-terrain movement cost was paid."},"fix":{"ko":"이동 비용과 위험 판정은 별개이므로 위험 지형 통과 후 추가 검사를 합니다.","en":"Movement cost and the hazard check are separate; resolve the extra check after dangerous terrain."}}],"selfCheck":{"ko":"왜 실제 3인치를 움직여도 M 5를 모두 쓰는지 설명할 수 있나요?","en":"Can you explain why traveling 3 physical inches can spend all of M 5?"},"exerciseHint":{"ko":"일반 구간은 그대로, 어려운 구간만 두 배로 계산한 뒤 더하세요.","en":"Count the ordinary section normally, double only the difficult section, then add them."},"optionFeedback":{"1":{"ko":"3은 실제 이동 거리입니다. 어려운 지형 2인치의 추가 비용을 빠뜨렸습니다.","en":"3 is physical distance; it omits the extra cost for the 2 difficult inches."},"2":{"ko":"어려운 지형 2인치는 이동량 4를 쓰며 일반 1을 더해야 합니다.","en":"The 2 difficult inches spend 4 allowance, then the ordinary 1 must be added."},"3":{"ko":"일반 1 + 어려운 2 × 2 = 이동량 5를 정확히 계산했습니다.","en":"You correctly calculated 1 ordinary + 2 × 2 difficult = 5 allowance."}}},"climb-leap":{"objective":{"ko":"등반 비용과 도약 판정의 기준을 분리하고 안전한 도착 위치를 확보합니다.","en":"Separate climbing cost from leap checks and ensure a valid landing position."},"preparation":[{"ko":"높이·틈 폭·이동 허용량과 사다리 또는 계단 여부를 확인합니다.","en":"Measure height, gap width and movement allowance, and identify ladders or stairs."}],"walkthrough":[{"title":{"ko":"지형 종류와 크기 측정","en":"Measure the feature"},"body":{"ko":"일반 등반인지 사다리·계단인지 구분하고 높이를 잽니다. 작은 단차와 틈 도약은 같은 상황으로 처리하지 않습니다.","en":"Distinguish ordinary climbing from ladders or stairs and measure height. A small step and a gap leap are not the same situation."},"result":{"ko":"적용할 이동 규칙을 정합니다.","en":"You identify which movement rule applies."}},{"title":{"ko":"등반의 비용·종료 확인","en":"Check climbing cost and endpoint"},"body":{"ko":"일반 등반은 높이 1인치당 이동량 2인치입니다. 활성화를 등반 중간에서 끝낼 수 없으므로 정상에 도착할 수 있는지 확인합니다.","en":"Ordinary climbing spends 2 inches per inch of height. An activation cannot finish midway, so check that the top is reachable."},"result":{"ko":"완료할 수 없는 등반을 무리하게 시작하지 않습니다.","en":"You avoid starting a climb that cannot be finished."}},{"title":{"ko":"틈과 판정 구분","en":"Check leap requirements"},"body":{"ko":"틈이 2인치 이하면 자동 도약, 더 넓으면 덱스테리티를 확인합니다. 기본 D6 4+에 해당 수정을 적용하며 자연 1·6의 규칙을 지킵니다.","en":"A gap up to 2 inches is automatic; a wider gap needs Dexterity. Use the base D6 4+ with applicable modifiers, respecting natural 1 and 6."},"result":{"ko":"자동 성공 구간과 굴려야 하는 구간을 구분합니다.","en":"You distinguish an automatic crossing from a required roll."}}],"workedExample":{"situation":{"ko":"이동량 5인 모델이 일반 벽 높이 2인치를 올라가려 합니다.","en":"A model with 5 movement allowance wants to climb an ordinary 2-inch wall."},"steps":[{"ko":"높이 2 × 등반 비용 2 = 이동량 4가 필요합니다.","en":"Height 2 × climbing cost 2 = 4 allowance required."},{"ko":"남은 1인치로 정상의 적법한 위치에 놓을 수 있는지 확인합니다. 사다리라면 일반 등반의 두 배 비용은 적용하지 않습니다.","en":"Check a legal position at the top with the remaining allowance. A ladder would avoid the doubled ordinary-climb cost."}],"result":{"ko":"정상에 도착 가능한 일반 등반은 비용 4로 계획할 수 있습니다.","en":"If a legal top position is reachable, the ordinary climb can be planned for 4 allowance."}},"pitfalls":[{"problem":{"ko":"일반 벽과 사다리에 같은 두 배 비용을 일괄 적용합니다.","en":"Applying the doubled ordinary-climb cost to a ladder as well."},"fix":{"ko":"실제 지형 종류를 먼저 확정하고 해당 비용 예외를 확인합니다.","en":"Identify the actual terrain feature first, then use its cost exception."}}],"selfCheck":{"ko":"2인치 틈과 2인치 벽을 넘을 때 어떤 규칙과 비용을 확인할지 말할 수 있나요?","en":"Can you explain which rules and costs apply to a 2-inch gap versus a 2-inch wall?"}},"falling":{"objective":{"ko":"추락 높이 구간을 판정해 부상과 현재 활성화 종료를 빠뜨리지 않습니다.","en":"Use fall-height bands and remember both injury effects and the current activation ending."},"preparation":[{"ko":"실제 낙하 높이와 자발적 하강 여부, 비행 같은 명시적 예외를 확인합니다.","en":"Check actual fall height, whether it is voluntary, and any explicit exception such as Flying."}],"walkthrough":[{"title":{"ko":"높이와 예외 먼저 확인","en":"Measure height and exceptions"},"body":{"ko":"추락 높이를 재고 일반 추락인지, 성공한 자발적 하강의 구간 감소 같은 예외가 있는지 구분합니다.","en":"Measure the fall and distinguish an ordinary fall from exceptions such as a successful voluntary-jump band reduction."},"result":{"ko":"비교할 기본 높이 구간이 정해집니다.","en":"The relevant base height band is established."}},{"title":{"ko":"해당 구간 효과 적용","en":"Apply the height band"},"body":{"ko":"3인치 미만은 제압, 3–6인치는 제압과 자동 운드·세이브 불가 L1 명중, 6인치 초과는 OOA를 적용합니다.","en":"Under 3 inches causes Suppression; 3–6 adds an automatically wounding, no-save L1 hit; over 6 causes OOA."},"result":{"ko":"높이에 맞는 결과만 적용합니다.","en":"Only the appropriate height result is applied."}},{"title":{"ko":"활성화와 전투 후 기록 분리","en":"Separate activation and campaign effects"},"body":{"ko":"자기 활성화 중 추락했다면 그 활성화를 끝냅니다. OOA를 곧바로 캠페인 사망으로 기록하지 않습니다.","en":"End the current activation if the model fell during it. Do not record OOA as automatic campaign death."},"result":{"ko":"행동 종료와 전투 후 생존 판정을 혼동하지 않습니다.","en":"Activation ending is kept separate from post-battle survival."}}],"workedExample":{"situation":{"ko":"일반 모델이 자기 활성화 중 정확히 6인치 추락했습니다.","en":"A normal model falls exactly 6 inches during its activation."},"steps":[{"ko":"6은 3–6인치 구간에 포함되며 6인치 초과 구간이 아닙니다.","en":"Exactly 6 belongs to the 3–6 band, not the over-6 band."},{"ko":"제압과 자동 운드·세이브 불가 L1 명중을 해결하고 현재 활성화를 끝냅니다.","en":"Resolve Suppression plus the automatically wounding, no-save L1 hit and end the activation."}],"result":{"ko":"경계값 6을 이유로 곧바로 OOA 구간을 적용하지 않습니다.","en":"The boundary value 6 does not by itself use the over-6 OOA band."}},"pitfalls":[{"problem":{"ko":"추락으로 부상을 받았지만 남은 이동이 있으니 활성화를 계속합니다.","en":"Continuing the activation after falling because movement allowance remains."},"fix":{"ko":"자기 활성화 중 추락은 현재 활성화를 끝낸다는 별도 결과를 적용합니다.","en":"Apply the separate rule that falling during the model’s activation ends it."}}],"selfCheck":{"ko":"2인치·4인치·7인치 일반 추락의 차이를 설명할 수 있나요?","en":"Can you explain the differences between ordinary falls of 2, 4 and 7 inches?"}},"movement-practice":{"objective":{"ko":"가장 짧은 거리 대신 추락 결과와 도착 후 행동 가능성까지 비교해 경로를 선택합니다.","en":"Choose a route by comparing fall effects and remaining activation, not just shortest distance."},"preparation":[{"ko":"안전한 계단 경로와 4인치 낙차 경로를 나란히 측정합니다.","en":"Measure both the safe stair route and the route with a 4-inch drop."}],"walkthrough":[{"title":{"ko":"경로별 조건 적기","en":"List each route’s conditions"},"body":{"ko":"낙차 높이와 지형 비용을 구분해 적습니다. 자동 도약할 틈과 아래로 떨어지는 추락을 혼동하지 않습니다.","en":"Record drop height separately from terrain movement cost. Do not confuse leaping a gap with falling downward."},"result":{"ko":"거리와 위험의 입력값을 분리합니다.","en":"Distance and danger are listed separately."}},{"title":{"ko":"기본 추락 효과 적용","en":"Apply the ordinary fall"},"body":{"ko":"4인치는 3–6 구간이므로 제압과 자동 운드·세이브 불가 L1 명중입니다. 문제에 없는 비행·성공한 하강 예외는 추가하지 않습니다.","en":"At 4 inches use the 3–6 band: Suppression plus an automatically wounding, no-save L1 hit. Do not add absent Flying or successful-jump exceptions."},"result":{"ko":"연습의 주어진 조건으로 결과를 구합니다.","en":"The result follows the stated scenario."}},{"title":{"ko":"도착 후 가능성 비교","en":"Compare the endpoint consequences"},"body":{"ko":"자기 활성화 중 추락하면 활성화가 끝납니다. 도착 뒤 목표 행동까지 하고 싶은 계획이라면 이 종료 효과도 경로 평가에 포함합니다.","en":"A fall during your activation ends it. If the plan needs an action after arriving, include that ending when evaluating the route."},"result":{"ko":"짧은 경로가 항상 유리하지 않음을 설명할 수 있습니다.","en":"You can explain why the shorter route is not always better."}}],"workedExample":{"situation":{"ko":"목표까지 지름길에는 4인치 추락이 있고, 돌아가면 안전한 계단을 씁니다.","en":"The shortcut to an objective has a 4-inch fall; the longer route uses safe stairs."},"steps":[{"ko":"지름길의 일반 추락은 제압 + 자동 운드·세이브 불가 L1 명중입니다.","en":"The shortcut’s ordinary fall gives Suppression plus an automatically wounding, no-save L1 hit."},{"ko":"그 활성화가 끝나므로 이후 행동을 포함한 계획이 성립하는지 다시 확인합니다.","en":"The activation ends, so recheck whether a plan requiring a later action still works."}],"result":{"ko":"경로 선택에는 소모 이동량뿐 아니라 상태와 활성화 종료도 포함해야 합니다.","en":"Route choice must include state and activation-ending effects as well as movement cost."}},"pitfalls":[{"problem":{"ko":"4인치 추락을 이동량 4를 쓰는 평지 이동과 같게 처리합니다.","en":"Treating a 4-inch fall like spending 4 allowance on flat ground."},"fix":{"ko":"수직 추락의 효과 구간을 먼저 적용하고 이후 행동 가능성을 확인합니다.","en":"Apply the vertical fall band first, then check any remaining action permission."}}],"selfCheck":{"ko":"선택한 경로의 실제 거리, 위험 결과, 종료 후 상태를 각각 말할 수 있나요?","en":"Can you state the chosen route’s distance, hazard outcome and resulting state?"},"exerciseHint":{"ko":"4인치를 추락 표의 어느 구간에 넣는지와 자기 활성화 종료를 함께 확인하세요.","en":"Identify the fall band containing 4 inches and remember the current activation ending."},"optionFeedback":{"1":{"ko":"4인치는 제압만의 3인치 미만 구간이 아니고, 자기 활성화도 끝납니다.","en":"4 inches is not the under-3 Suppression-only band, and the current activation ends."},"2":{"ko":"3–6인치 구간의 명중과 제압, 현재 활성화 종료를 모두 포함했습니다.","en":"This includes the 3–6 band hit, Suppression and the current activation ending."},"3":{"ko":"높이에 따라 결과가 다르고, OOA도 자동 캠페인 사망은 아닙니다.","en":"Results depend on height, and OOA is not automatic campaign death."}}}},"ranged-combat":{"target":{"objective":{"ko":"주사위를 굴리기 전에 표적·사용 프로필·시야·사거리를 확정합니다.","en":"Fix the target, profile, line of sight and range before rolling."},"preparation":[{"ko":"사격할 모델의 무기 카드와 표적 모델 몸체를 볼 수 있는 위치를 확인합니다.","en":"Have the shooting model’s weapon card and a view of the target’s body."}],"walkthrough":[{"title":{"ko":"사용 행과 표적 선언","en":"Declare a profile row and target"},"body":{"ko":"한 무기의 여러 프로필 중 사용할 행을 정하고 표적을 선언합니다. 사거리·S·AP·L·특성은 그 행에서 함께 읽습니다.","en":"Choose one row if the weapon has multiple profiles and declare the target. Read range, S, AP, L and traits from that same row."},"result":{"ko":"사격 뒤 유리한 프로필로 바꾸지 않게 됩니다.","en":"The profile is not switched after seeing the roll."}},{"title":{"ko":"시야와 아크 확인","en":"Check line of sight and Arc"},"body":{"ko":"일반 시야 360도를 기준으로 몸체를 확인합니다. 아크 특성이 있으면 그 제한을 적용하며 장식이나 총열만 보이는 것과 구분합니다.","en":"Use normal 360-degree vision to check the body. Apply an Arc trait’s restriction and distinguish the body from visible decoration or a barrel."},"result":{"ko":"적법한 표적인지 먼저 판단합니다.","en":"You establish target legality first."}},{"title":{"ko":"거리와 수정 확인 후 굴림","en":"Measure, check modifiers, then roll"},"body":{"ko":"거리를 재서 해당 프로필 사거리 안인지 확인합니다. 사거리 밖 공격은 실패이며 거리·상태·특성 수정을 확인한 뒤 BS를 굴립니다.","en":"Measure against the chosen profile’s range. Out-of-range attacks fail; check range, state and trait modifiers before the BS roll."},"result":{"ko":"주사위 결과보다 앞서 적용할 조건이 고정됩니다.","en":"The conditions are fixed before the result is known."}}],"workedExample":{"situation":{"ko":"선택한 프로필 최대 사거리가 18인치이고 표적은 19인치 떨어져 있습니다.","en":"The chosen profile has an 18-inch maximum range and the target is 19 inches away."},"steps":[{"ko":"19 > 18이므로 그 프로필의 사거리 밖입니다.","en":"19 > 18 places the target outside that profile’s range."},{"ko":"좋은 명중 주사위를 얻더라도 사거리 밖 공격이라는 조건을 없애지 못합니다.","en":"A good hit roll cannot remove the out-of-range condition."}],"result":{"ko":"이 공격은 실패합니다. 다음 공격에서는 적법한 표적·프로필을 먼저 고릅니다.","en":"The attack fails; choose a legal target and profile before a future attack."}},"pitfalls":[{"problem":{"ko":"주사위를 먼저 굴린 뒤 결과가 좋으면 더 긴 사거리 행으로 바꿉니다.","en":"Rolling first and switching to a longer-range row after a good result."},"fix":{"ko":"프로필·표적·조건을 먼저 선언하고 해당 값으로 끝까지 해결합니다.","en":"Declare the profile, target and conditions first and resolve with those values."}}],"selfCheck":{"ko":"사격 전에 표적·프로필·시야·거리 네 항목을 차례대로 확인했나요?","en":"Have you checked target, profile, line of sight and distance before shooting?"}},"hit-cover":{"objective":{"ko":"N26의 명중 수정과 엄폐 세이브 보너스를 서로 다른 굴림에 적용합니다.","en":"Apply N26 hit modifiers and cover-save bonuses to their separate rolls."},"preparation":[{"ko":"몸체를 가리는 지형, 선택 프로필의 단·장거리, 표적의 중상 여부를 확인합니다.","en":"Check body-obscuring terrain, the profile’s short/long range and whether the target is Seriously Injured."}],"walkthrough":[{"title":{"ko":"명중 테스트 입력","en":"Set up the hit test"},"body":{"ko":"BS와 실제 명중 수정을 확인합니다. 중상 표적의 −1을 구분하고 자연 1 실패·6 성공을 확인합니다.","en":"Check BS and actual hit modifiers. Include the −1 for a Seriously Injured target and respect natural 1 failure and 6 success."},"result":{"ko":"명중에 적용할 수정만 모읍니다.","en":"Only hit-test modifiers are collected here."}},{"title":{"ko":"엄폐 여부 판단","en":"Assess cover"},"body":{"ko":"표적 몸체가 지형이나 모델에 가려지는지 확인합니다. 베이스나 장식만 가려진 것으로 엄폐를 인정하지 않습니다.","en":"Check whether terrain or models obscure the target’s body. Obscuring only a base or decoration is not cover."},"result":{"ko":"엄폐 보너스를 받을 조건을 확인합니다.","en":"You establish eligibility for a cover bonus."}},{"title":{"ko":"거리대별 세이브 보너스","en":"Apply the range-band save bonus"},"body":{"ko":"N26 원거리 엄폐는 단거리 세이브 +1, 장거리 +2입니다. 이를 N23의 명중 수정처럼 명중 단계에서 빼지 않습니다.","en":"N26 ranged cover gives +1 to the save at short range and +2 at long range. Do not subtract it from the hit test as in N23."},"result":{"ko":"명중과 나중 세이브를 서로 다른 단계로 처리합니다.","en":"The hit and the later save remain separate stages."}}],"workedExample":{"situation":{"ko":"정상 표적의 몸체가 지형에 가려져 있고 선택한 무기의 장거리대에 있습니다.","en":"An ordinary target’s body is obscured by terrain and it lies in the weapon’s long range band."},"steps":[{"ko":"엄폐 보너스를 이유로 BS 명중에 −2를 주지 않습니다.","en":"Do not apply a −2 BS penalty for that cover bonus."},{"ko":"운드가 성공하면 일반 세이브 계산에서 장거리 엄폐 +2를 적용합니다.","en":"If a wound succeeds, apply long-range cover +2 in the normal save calculation."}],"result":{"ko":"엄폐의 이점은 이 상황에서 세이브 단계에 적용됩니다.","en":"In this situation the benefit of cover belongs to the save stage."}},"pitfalls":[{"problem":{"ko":"엄폐를 명중과 세이브에 모두 적용해 두 번 이득을 줍니다.","en":"Applying cover both to the hit test and the save, giving the benefit twice."},"fix":{"ko":"N26 엄폐 보너스를 해당 거리대의 세이브 수정으로 한 번 적용합니다.","en":"Apply the N26 cover bonus once as the appropriate range-band save modifier."}}],"selfCheck":{"ko":"중상 표적 −1과 장거리 엄폐 +2가 각각 어느 굴림에 들어가는지 말할 수 있나요?","en":"Can you identify which rolls receive Seriously Injured −1 and long-range cover +2?"}},"wound":{"objective":{"ko":"S와 T의 대소 관계를 두 배·동일·절반 경계까지 확인해 운드 목표를 찾습니다.","en":"Determine the wound target by checking S against T, including double, equal and half boundaries."},"preparation":[{"ko":"해결 중인 무기 프로필의 S와 해당 표적의 현재 T를 따로 적습니다.","en":"Write down the current weapon profile’s S and the target’s current T."}],"walkthrough":[{"title":{"ko":"현재 값 확인","en":"Read current values"},"body":{"ko":"명중한 공격의 S와 표적 T를 확인합니다. 다른 무기나 다른 표적의 값을 섞지 않고 적용 중인 효과를 반영합니다.","en":"Check the hit’s S and the target’s T. Do not mix in another weapon or target; include applicable effects."},"result":{"ko":"비교할 두 값이 정해집니다.","en":"The two comparison values are fixed."}},{"title":{"ko":"관계의 경계 검사","en":"Check comparison boundaries"},"body":{"ko":"S가 T의 두 배 이상인지 먼저 보고, 아니면 더 큼·같음·작음·절반 이하를 구분합니다.","en":"First check whether S is at least double T, then distinguish greater, equal, lower and at most half."},"result":{"ko":"운드 표의 한 구간을 선택합니다.","en":"You select one row of the wound table."}},{"title":{"ko":"목표값으로 D6 해결","en":"Resolve against the target"},"body":{"ko":"선택한 2+·3+·4+·5+·6+로 운드를 굴립니다. 명중 성공을 운드 성공으로 자동 변환하지 않습니다.","en":"Roll the wound against the chosen 2+, 3+, 4+, 5+ or 6+ target. A successful hit is not an automatic wound."},"result":{"ko":"성공한 운드만 다음 세이브 단계로 넘깁니다.","en":"Only successful wounds proceed to saves."}}],"workedExample":{"situation":{"ko":"S 4가 T 3에 명중했습니다. S가 더 크다는 사실만 보고 2+인지 확인합니다.","en":"S 4 hits T 3. Check whether being greater is enough for a 2+ target."},"steps":[{"ko":"T의 두 배는 2 × 3 = 6이므로 S 4는 그 경계에 못 미칩니다.","en":"Double T is 2 × 3 = 6, so S 4 does not reach it."},{"ko":"T 3보다 크고 두 배 6보다 작으므로 3+ 구간입니다.","en":"S 4 is greater than T 3 but below double 6, giving 3+."}],"result":{"ko":"운드 목표는 3+입니다. S 6이었다면 두 배 이상인 2+ 구간입니다.","en":"The wound target is 3+. S 6 would instead reach the at-least-double 2+ band."}},"pitfalls":[{"problem":{"ko":"S가 T보다 1 높으면 항상 2+라고 판단합니다.","en":"Assuming S one above T always wounds on 2+."},"fix":{"ko":"2+에는 두 배 이상이라는 조건이 필요하므로 먼저 2×T와 비교합니다.","en":"The 2+ band requires at least double T, so compare with 2×T first."}}],"selfCheck":{"ko":"S 4 대 T 3과 S 6 대 T 3이 서로 다른 목표값인 이유를 설명할 수 있나요?","en":"Can you explain why S 4 against T 3 differs from S 6 against T 3?"},"exerciseHint":{"ko":"T 3의 두 배를 먼저 구하고 S 4가 그 값에 도달하는지 보세요.","en":"Find double T 3 first, then check whether S 4 reaches it."},"optionFeedback":{"1":{"ko":"2+는 S가 T의 두 배인 6 이상일 때입니다. S 4는 아직 그보다 작습니다.","en":"2+ requires S at least double T, which is 6; S 4 is below it."},"2":{"ko":"4 > 3이지만 4 < 6이므로 3+ 구간을 정확히 골랐습니다.","en":"Since 4 > 3 but 4 < 6, the 3+ band is correct."},"3":{"ko":"4+는 S와 T가 같은 경우입니다. 이 공격은 S 4가 T 3보다 큽니다.","en":"4+ is for equal S and T; here S 4 exceeds T 3."}}},"save":{"objective":{"ko":"자연 주사위와 수정 합계를 분리하고 성공 운드마다 세이브 하나를 고릅니다.","en":"Separate the natural die from the modified total and choose one save per successful wound."},"preparation":[{"ko":"표적의 일반·무적 세이브, 공격 AP, 엄폐와 세이브 금지 여부를 확인합니다.","en":"Check normal/invulnerable saves, attack AP, cover and any no-save prohibition."}],"walkthrough":[{"title":{"ko":"선택 가능한 세이브 확인","en":"Check available saves"},"body":{"ko":"성공 운드마다 사용할 세이브 하나를 고릅니다. 세이브 금지라면 다른 종류로 우회하지 않습니다.","en":"Choose one available save per successful wound. A no-save prohibition cannot be bypassed by switching save types."},"result":{"ko":"굴릴 수 있는지부터 정합니다.","en":"You first establish whether a roll is allowed."}},{"title":{"ko":"일반 또는 무적 방식 적용","en":"Use normal or invulnerable procedure"},"body":{"ko":"일반 세이브는 D6 + AP + 해당 수정을 Sv와 비교합니다. 무적 세이브는 AP와 엄폐 등 모든 수정을 무시합니다.","en":"Compare D6 + AP + applicable modifiers with Sv for a normal save. An invulnerable save ignores all modifiers, including AP and cover."},"result":{"ko":"두 방식을 섞어 유리한 부분만 고르지 않습니다.","en":"The two procedures are not mixed for selected benefits."}},{"title":{"ko":"자연 1·2를 별도 확인","en":"Check natural 1 and 2 separately"},"body":{"ko":"수정 합이 충분해도 자연 1·2는 실패입니다. 실패한 운드만 W 손실 절차로 넘기며 같은 운드에 두 번째 세이브를 굴리지 않습니다.","en":"Natural 1 or 2 fails even if modifiers would reach Sv. Pass unsaved wounds to W loss; do not roll a second save for the same wound."},"result":{"ko":"자동 실패와 수정 성공을 올바르게 구분합니다.","en":"Automatic failure is distinguished from the modified result."}}],"workedExample":{"situation":{"ko":"Sv 4+, AP −1, 단거리 엄폐 +1, 자연 주사위 4인 일반 세이브입니다.","en":"A normal save uses Sv 4+, AP −1, short-range cover +1 and a natural die of 4."},"steps":[{"ko":"수정 합은 −1 + 1 = 0이며 결과는 4입니다.","en":"Modifiers sum to −1 + 1 = 0, leaving a result of 4."},{"ko":"4는 Sv 4+를 만족하고 자연 1·2도 아니므로 성공합니다.","en":"4 meets Sv 4+ and is not a natural 1 or 2, so the save succeeds."}],"result":{"ko":"운드를 막습니다. 같은 운드에 무적 세이브를 추가로 굴리지 않습니다.","en":"The wound is saved; do not roll an additional invulnerable save for it."}},"pitfalls":[{"problem":{"ko":"일반 세이브 실패 뒤 같은 운드에 무적 세이브도 굴립니다.","en":"Rolling an invulnerable save after the normal save failed against the same wound."},"fix":{"ko":"각 운드마다 처음에 세이브 하나를 선택하며 중복 방어 굴림을 하지 않습니다.","en":"Choose one save at the start for each wound and do not make duplicate defensive rolls."}}],"selfCheck":{"ko":"자연 2와 수정 결과 4를 구분하고 자동 실패 여부를 판단할 수 있나요?","en":"Can you distinguish a natural 2 from a modified total of 4 and apply automatic failure?"}},"ammo":{"objective":{"ko":"화력 주사위 선택·탄약 기호·프로필별 탄약 상태·명중 분배를 순서대로 추적합니다.","en":"Track Firepower selection, Ammo symbols, profile ammunition and hit allocation in order."},"preparation":[{"ko":"사용 프로필의 래피드 파이어 X와 애모 값, 각 프로필의 현재 탄약 상태를 확인합니다.","en":"Check Rapid Fire X, Ammo value and the ammunition state of each profile."}],"walkthrough":[{"title":{"ko":"사용 주사위 수 선언","en":"Choose the Firepower dice"},"body":{"ko":"래피드 파이어 X의 최대 X개 안에서 사용할 화력 주사위 수를 정합니다. 결과를 본 뒤 추가 주사위를 고르지 않습니다.","en":"Choose how many Firepower dice to use, up to Rapid Fire X. Do not choose extra dice after seeing results."},"result":{"ko":"출력과 탄약 위험을 선택 전에 비교합니다.","en":"Output and ammunition risk are considered before the roll."}},{"title":{"ko":"기호와 탄약 상태 기록","en":"Record symbols and ammunition"},"body":{"ko":"탄약 기호 1개면 탄약 부족, 2개 이상이면 해당 전투 사용 불가를 확인합니다. 실패한 애모 테스트는 화력 주사위가 아니라 탄약 기호 1개를 추가합니다.","en":"One Ammo symbol causes Out of Ammo; two or more disable the weapon for the battle. A failed Ammo test adds one Ammo symbol, not another Firepower die."},"result":{"ko":"추가 명중과 탄약 위험을 혼동하지 않습니다.","en":"Extra hits are not confused with ammunition risk."}},{"title":{"ko":"분배와 리로드 처리","en":"Allocate hits and handle Reload"},"body":{"ko":"분할 명중은 운드 굴림 전에 거리·표적 조건으로 정합니다. 탄약 부족은 사용 프로필에 기록하고 리로드 싱글은 선택 프로필 하나를 회복합니다.","en":"Allocate split hits before wound rolls using the target/range conditions. Record Out of Ammo on the used profile; Reload (Single) restores one chosen profile."},"result":{"ko":"한 프로필의 상태로 다른 프로필까지 임의 변경하지 않습니다.","en":"One profile’s condition is not arbitrarily copied to every profile."}}],"workedExample":{"situation":{"ko":"래피드 파이어 2 무기에 화력 주사위 1개만 쓰기로 정하고 탄약 기호 1개가 나왔습니다.","en":"For a Rapid Fire 2 weapon, you choose only 1 Firepower die and roll 1 Ammo symbol."},"steps":[{"ko":"최대 2개라고 반드시 2개를 쓰는 것은 아닙니다. 선언한 1개 결과를 해결합니다.","en":"A maximum of 2 does not require using both; resolve the declared 1 die."},{"ko":"탄약 기호 1개에 따른 탄약 부족을 해당 사용 프로필에 기록합니다.","en":"Record the one-symbol Out of Ammo condition on the profile used."}],"result":{"ko":"이후 리로드 싱글로 선택 프로필 하나를 회복하는 절차를 검토합니다.","en":"A later Reload (Single) can be considered for one chosen profile under its procedure."}},"pitfalls":[{"problem":{"ko":"애모 테스트 실패 때 추가 화력 주사위를 굴려 명중을 더 얻습니다.","en":"Rolling another Firepower die for a failed Ammo test and gaining extra hits."},"fix":{"ko":"추가되는 것은 탄약 기호 1개이며 화력 주사위는 추가되지 않습니다.","en":"The extra effect is one Ammo symbol, not another Firepower die."}}],"selfCheck":{"ko":"현재 탄약 부족인 프로필과 다른 프로필, 전투 사용 불가 상태를 구별할 수 있나요?","en":"Can you distinguish an Out of Ammo profile, other profiles and a weapon disabled for the battle?"}},"ranged-practice":{"objective":{"ko":"사격의 선언부터 운드·세이브·W·부상까지 원인과 결과를 이어서 설명합니다.","en":"Explain the causal sequence from shooting declaration to wounds, saves, W and injury."},"preparation":[{"ko":"선택 프로필의 S·AP·L과 표적 T·Sv·W, 거리대와 엄폐를 준비합니다.","en":"Have profile S/AP/L, target T/Sv/W, range band and cover ready."}],"walkthrough":[{"title":{"ko":"표적·거리·명중 해결","en":"Resolve target, range and hit"},"body":{"ko":"선택 프로필과 적법한 표적을 선언한 뒤 거리와 BS 명중을 처리합니다. 탄약·특성의 해당 시점도 함께 확인합니다.","en":"Declare the profile and legal target, then resolve range and BS hit. Include ammunition and trait checks at their stated timing."},"result":{"ko":"명중한 공격만 다음 운드로 이어집니다.","en":"Only hits advance to wound resolution."}},{"title":{"ko":"운드 후 세이브 계산","en":"Resolve wound, then save"},"body":{"ko":"S와 T로 운드 목표를 정하고 성공 운드마다 세이브 하나를 고릅니다. AP와 엄폐는 해당 세이브 방식에 따라 적용합니다.","en":"Use S versus T for the wound target, then choose one save for each successful wound. Apply AP and cover through that save’s procedure."},"result":{"ko":"명중과 운드와 세이브를 서로 대체하지 않습니다.","en":"Hit, wound and save are not substituted for one another."}},{"title":{"ko":"막지 못한 운드만 W에 적용","en":"Apply only unsaved wounds to W"},"body":{"ko":"세이브 실패한 운드로 W를 줄입니다. W가 0에 도달하면 N26 L에 따른 부상 주사위 절차로 넘어갑니다.","en":"Reduce W for unsaved wounds. When W reaches zero, proceed to N26 injury dice using L."},"result":{"ko":"L을 모든 명중의 W 손실량으로 오해하지 않습니다.","en":"L is not mistaken for W loss on every hit."}}],"workedExample":{"situation":{"ko":"성공 운드 하나에 Sv 4+, AP −1, 장거리 엄폐 +2, 자연 주사위 3입니다.","en":"One successful wound faces Sv 4+, AP −1, long-range cover +2 and a natural die of 3."},"steps":[{"ko":"3 − 1 + 2 = 4로 Sv 4+를 만족합니다.","en":"3 − 1 + 2 = 4, meeting Sv 4+."},{"ko":"자연 주사위는 3이므로 자연 1·2 실패가 아니며 이 운드는 막힙니다.","en":"The natural die is 3, so natural 1–2 failure does not apply and the wound is saved."}],"result":{"ko":"W를 줄이거나 L 부상 주사위를 굴리지 않고 이 운드의 해결을 마칩니다.","en":"Finish resolving this wound without reducing W or rolling L injury dice."}},"pitfalls":[{"problem":{"ko":"명중했으니 운드·세이브와 관계없이 W를 먼저 줄입니다.","en":"Reducing W immediately after a hit regardless of wound and save results."},"fix":{"ko":"명중 → 운드 → 세이브 → 막지 못한 운드의 W 손실 순서를 유지합니다.","en":"Keep hit → wound → save → W loss from an unsaved wound in order."}}],"selfCheck":{"ko":"연습 세이브에서 자연 주사위, AP, 엄폐, 비교 Sv를 각각 가리킬 수 있나요?","en":"Can you identify the natural die, AP, cover and target Sv in the worked save?"},"exerciseHint":{"ko":"주사위 3에 AP −1과 장거리 엄폐 +2를 적용한 뒤, 자연 1·2인지도 확인하세요.","en":"Apply AP −1 and long-range cover +2 to the die of 3, then check natural 1–2 failure separately."},"optionFeedback":{"1":{"ko":"수정 결과 4가 Sv 4+를 만족하고 자연 주사위 3은 자동 실패가 아니므로 성공입니다.","en":"The modified 4 meets Sv 4+ and natural 3 is not an automatic failure, so the save succeeds."},"2":{"ko":"AP는 수치 수정이며, AP가 있다는 이유만으로 세이브가 항상 실패하지 않습니다.","en":"AP modifies the result; its mere presence does not automatically fail the save."},"3":{"ko":"N26의 이 엄폐는 세이브 +2입니다. N23의 명중 수정과 섞으면 안 됩니다.","en":"This N26 cover gives +2 to the save and must not be replaced with an N23 hit modifier."}}}},"close-combat":{"charge-engage":{"objective":{"ko":"차지와 인게이지의 행동 비용·사거리·성공 후 처리를 구분합니다.","en":"Distinguish Charge and Engage by action cost, range, and the resolution after contact."},"preparation":[{"ko":"활성 모델의 M, 남은 행동, 상대 상태와 선언 시 시야를 확인하세요.","en":"Check the active model’s M, remaining actions, target state, and visibility at declaration."}],"walkthrough":[{"title":{"ko":"행동 선택","en":"Choose the action"},"body":{"ko":"차지는 더블로 두 행동을 사용하고 M+D6인치를 이동합니다. 인게이지는 싱글로 한 행동을 사용하고 D6인치를 이동합니다.","en":"Charge spends both actions and moves M+D6 inches; Engage spends one Single action and moves D6 inches."},"result":{"ko":"이동 전에 사용할 행동과 그 비용을 확정합니다.","en":"The selected action and its cost are established before movement."}},{"title":{"ko":"선언과 경로 확인","en":"Declare and inspect the route"},"body":{"ko":"표적과 경로를 정하고 선언 시 표적이 보였는지 기억합니다. 베이스 접촉 여부와 일반 이동의 적 접근 제한도 확인합니다.","en":"Identify the target and route and note whether the target was visible when declared. Check base contact and enemy exclusion rather than treating this as ordinary movement."},"result":{"ko":"성공한 접촉과 보이지 않던 적에 대한 명중 보정 여부를 구분합니다.","en":"Contact success and the modifier for an initially unseen enemy are identified separately."}},{"title":{"ko":"접촉 후 처리","en":"Resolve contact"},"body":{"ko":"중상이 아닌 적과 베이스가 닿으면 교전입니다. 성공한 행동이 허용하는 프리 파이트 또는 라스트 블로를 해당 표적 상태에 맞게 처리합니다.","en":"Base contact with a non-Seriously Injured enemy establishes engagement. Resolve the Free Fight or Last Blow permitted by the successful action for that target state."},"result":{"ko":"접촉만 기록하고 허용된 후속 처리를 빠뜨리지 않습니다.","en":"The permitted follow-up is resolved rather than stopping at contact."}}],"workedExample":{"situation":{"ko":"M 4 모델에게 행동 두 개가 남았고 차지 D6은 3입니다. 다른 거리 수정은 없습니다.","en":"A model has M 4, two actions remaining, and a Charge D6 result of 3, with no other distance modifiers."},"steps":[{"ko":"차지 비용은 더블이므로 두 행동을 배정합니다.","en":"Allocate both actions because Charge is Double."},{"ko":"이동 가능 거리는 4+3=7인치입니다. 실제 경로와 접촉 가능 여부를 확인합니다.","en":"The available movement is 4+3=7 inches. Check the actual route and whether contact is possible."}],"result":{"ko":"최대 7인치 경로로 차지를 해결하고 성공하면 허용된 후속 처리를 합니다.","en":"Resolve the Charge along a route of up to 7 inches and apply its permitted follow-up if successful."}},"pitfalls":[{"problem":{"ko":"싱글 행동 하나만 남았는데 차지를 선언하거나 인게이지 거리에 M을 더합니다.","en":"Declaring Charge with only one action remaining, or adding M to Engage distance."},"fix":{"ko":"차지는 두 행동, 인게이지는 D6이라는 두 가지 제한을 별도로 확인하세요.","en":"Check both restrictions independently: Charge requires two actions, while Engage moves D6 inches."}}],"selfCheck":{"ko":"선언 전에 남은 행동과 보이는 표적 여부를 말하고, 선택한 행동의 거리 공식을 설명할 수 있나요?","en":"Can you state the actions remaining, visibility at declaration, and the distance formula of your chosen action?"}},"weapons-attacks":{"objective":{"ko":"활성 모델과 비활성 참가자의 공격 주사위를 무기별로 나눕니다.","en":"Allocate attacks by weapon while distinguishing the active model from non-active participants."},"preparation":[{"ko":"A와 두 무기의 특성, 이번 활성화의 차지 여부, 탑승 제한을 펼쳐 두세요.","en":"Have A, both weapon traits, this activation’s charge status, and any Mounted restrictions available."}],"walkthrough":[{"title":{"ko":"주·보조무기 지정","en":"Designate primary and offhand"},"body":{"ko":"사용할 주무기와 적법한 보조무기를 정합니다. 라이트나 탑승 제한 때문에 선택이 달라질 수 있으므로 무기 이름만 보고 쌍수로 계산하지 않습니다.","en":"Choose a primary weapon and a legal offhand. Light or Mounted restrictions can alter the selection, so merely carrying two weapons is insufficient."},"result":{"ko":"어느 무기에 어떤 프로필을 쓸지 정해집니다.","en":"Each selected weapon has an identified profile."}},{"title":{"ko":"활성 공격 수 계산","en":"Count active attacks"},"body":{"ko":"일반 주무기는 A에 이번 활성화의 차지 보너스 1을 더합니다. 적법한 보조무기는 1회이며 라이트 무기는 최대 1회라는 제한을 따로 적용합니다.","en":"For an ordinary primary, use A plus 1 for charging in this activation. A legal offhand makes 1 attack; separately apply the maximum of 1 attack for a Light weapon."},"result":{"ko":"주무기 묶음과 보조무기 묶음이 분리됩니다.","en":"Primary and offhand dice form separate groups."}},{"title":{"ko":"비활성 공격 구분","en":"Separate non-active attacks"},"body":{"ko":"비활성 참가자는 높은 A를 그대로 쓰지 않고 주무기로 1회 공격합니다. 각 묶음은 해당 무기의 S·AP·L로 해결합니다.","en":"A non-active participant makes 1 primary attack instead of using its full A. Resolve each dice group with its own S, AP, and L."},"result":{"ko":"상대와 내 공격 수·프로필이 섞이지 않습니다.","en":"Both sides’ attack counts and profiles remain distinct."}}],"workedExample":{"situation":{"ko":"활성 모델 A는 3이고 이번 활성화에 차지하지 않았습니다. 적법한 보조무기가 있으며 상대 A는 4지만 비활성입니다.","en":"The active model has A 3, did not charge this activation, and has a legal offhand. The opponent has A 4 but is non-active."},"steps":[{"ko":"활성 주무기는 3회, 보조무기는 1회로 나눕니다.","en":"Allocate 3 active primary attacks and 1 offhand attack."},{"ko":"비활성 상대는 A 4와 관계없이 주무기 1회를 준비합니다.","en":"Prepare 1 primary attack for the non-active opponent regardless of A 4."}],"result":{"ko":"활성 측 3+1회와 비활성 측 1회가 각각 자신의 무기 프로필로 해결됩니다.","en":"Resolve active attacks as 3+1 and the non-active attack as 1, each with its own profile."}},"pitfalls":[{"problem":{"ko":"보조무기에도 A를 전부 주거나 비활성 상대에게 A만큼 공격을 줍니다.","en":"Giving the offhand the full A value or allowing a non-active opponent to use all of A."},"fix":{"ko":"활성 여부를 먼저 표시한 뒤 주무기·보조무기·제한을 한 줄씩 계산하세요.","en":"Mark which model is active, then calculate primary, offhand, and restrictions separately."}}],"selfCheck":{"ko":"각 공격 주사위 묶음을 어느 무기에서 얻었는지, 어느 특성이 수를 제한하는지 설명할 수 있나요?","en":"Can you identify the source of every dice group and the traits that limit its size?"}},"initiative":{"objective":{"ko":"차지로 수정한 I를 비교하고 동률 공격을 누락하지 않습니다.","en":"Compare charge-modified I and preserve all attacks tied for the same timing."},"preparation":[{"ko":"양쪽의 기본 I와 순서에 영향을 주는 무기 특성, 차지 성공 여부를 확인하세요.","en":"Check both base I values, weapon timing traits, and whether a charge succeeded this activation."}],"walkthrough":[{"title":{"ko":"순서용 I 적기","en":"Write the ordering I"},"body":{"ko":"기본 I에 이번 활성화의 성공한 차지 보너스 +2와 명시된 순서 수정을 적용합니다. 공격 수 보너스 +1과 같은 칸에 합치지 않습니다.","en":"Apply +2 ordering I for a successful charge this activation and any explicit timing effects. Keep it separate from the +1 attack bonus."},"result":{"ko":"각 모델의 비교할 I가 명확해집니다.","en":"The I values to compare are explicit."}},{"title":{"ko":"높은 수부터 배치","en":"Arrange highest first"},"body":{"ko":"수정 I가 높은 공격부터 해결합니다. 동률인 공격은 같은 시점 묶음으로 표시합니다.","en":"Resolve higher modified I first and mark tied attacks as one timing group."},"result":{"ko":"굴리는 순서와 실제 규칙상 시점이 구분됩니다.","en":"Convenient dice order is separated from rules timing."}},{"title":{"ko":"동률 공격 보존","en":"Preserve tied attacks"},"body":{"ko":"동률 묶음은 한쪽 주사위를 먼저 굴렸더라도 다른 쪽의 공격을 보존합니다. 첫 굴림으로 OOA·중상이 되어도 같은 시점 공격은 취소하지 않습니다.","en":"Preserve every tied attack even if one side rolls first. Becoming OOA or Seriously Injured from that first roll does not cancel attacks at the tied timing."},"result":{"ko":"동시 공격이 빠짐없이 해결됩니다.","en":"All simultaneous attacks are resolved."}}],"workedExample":{"situation":{"ko":"모델 A의 I는 3이고 이번에 차지했습니다. 모델 B의 I는 5이며 다른 수정은 없습니다.","en":"Model A has I 3 and charged this activation; model B has I 5, with no other modifiers."},"steps":[{"ko":"A의 순서용 I는 3+2=5이고 B는 5입니다.","en":"A has ordering I 3+2=5 and B has I 5."},{"ko":"5 대 5이므로 같은 시점 묶음으로 두 공격을 모두 준비합니다.","en":"The 5-to-5 tie places both sets of attacks in the same timing group."}],"result":{"ko":"A가 먼저 주사위를 굴려 B를 OOA로 만들어도 B의 동률 공격을 해결합니다.","en":"Even if A rolls first and causes B to become OOA, resolve B’s tied attacks."}},"pitfalls":[{"problem":{"ko":"차지한 모델이 동률을 자동으로 이긴다고 생각합니다.","en":"Assuming that the charging model automatically wins a tied I comparison."},"fix":{"ko":"차지는 순서용 I를 +2할 뿐이며 동률 자체는 동시 공격으로 남습니다.","en":"Charge adds +2 ordering I; an actual tie still means simultaneous attacks."}}],"selfCheck":{"ko":"계산한 I와 동시 공격 묶음을 상대에게 보여 줄 수 있나요?","en":"Can you show your calculated I and identify the simultaneous timing group?"},"exerciseHint":{"ko":"공격 수가 아니라 순서용 I에 차지 +2를 더해 두 값을 비교하세요.","en":"Add the charge bonus to ordering I, rather than attack count, and compare both totals."},"optionFeedback":{"1":{"ko":"3+2=5로 같은 값이므로 두 공격은 같은 시점입니다.","en":"The values tie at 3+2=5, placing both attacks at the same timing."},"2":{"ko":"차지는 +2 I를 줄 뿐 동률을 자동으로 깨지 않습니다.","en":"Charge gives +2 I; it does not automatically break an actual tie."},"3":{"ko":"A의 차지 보너스를 누락했습니다. A도 I 5입니다.","en":"This omits A’s charge bonus; A also reaches I 5."}}},"hits-support":{"objective":{"ko":"WS 명중 보정의 자격을 확인하고 지원·방해를 중첩하지 않습니다.","en":"Verify WS modifiers and avoid stacking multiple assistance or interference sources."},"preparation":[{"ko":"참가자의 베이스 접촉, 다른 적과의 교전, 무기 프로필을 확인하세요.","en":"Check base contact, engagement with other enemies, and the selected weapon profiles."}],"walkthrough":[{"title":{"ko":"명중 묶음 분리","en":"Separate hit groups"},"body":{"ko":"무기와 표적이 다른 공격은 주사위 묶음을 나눕니다. 각각의 WS 목표와 무기 특성을 먼저 적습니다.","en":"Separate attacks using different weapons or targets. Note the WS target and relevant traits for each group."},"result":{"ko":"다른 S·AP·L을 가진 공격을 잘못 합산하지 않습니다.","en":"Attacks with different S, AP, or L are not mixed."}},{"title":{"ko":"지원·방해 자격 검토","en":"Check assistance and interference"},"body":{"ko":"주변 모델이 단순히 가깝다는 이유로 보너스를 주지 않습니다. 교전 조건을 만족하는 지원은 +1, 방해는 -1이며 같은 종류의 보정은 한 번만 적용합니다.","en":"Proximity alone gives no bonus. Qualifying assistance gives +1 and interference gives −1; apply each kind only once even when several models qualify."},"result":{"ko":"자격을 확인한 보정만 한 번씩 적용합니다.","en":"Only eligible modifiers are applied, once per kind."}},{"title":{"ko":"자연 결과와 후속 판정","en":"Resolve natural results and follow-up"},"body":{"ko":"근접 WS 테스트에서 자연 1은 실패, 자연 6은 성공입니다. 명중한 공격만 자신의 프로필로 운드·세이브 절차를 진행합니다.","en":"A natural 1 fails and a natural 6 succeeds on a melee WS test. Only hits proceed to wounds and saves using their own profiles."},"result":{"ko":"명중 성공과 피해 적용을 별도로 처리합니다.","en":"Hitting and applying damage remain separate operations."}}],"workedExample":{"situation":{"ko":"WS 4+ 공격에 적법한 지원자 두 명이 있고 방해는 없습니다. 다른 보정도 없습니다.","en":"A WS 4+ attack has two qualifying assistants, no interference, and no other modifiers."},"steps":[{"ko":"지원은 두 명이어도 +1 한 번만 적용합니다.","en":"Apply assistance as +1 once, despite having two assistants."},{"ko":"자연 3은 수정 4가 되어 명중하고 자연 1은 여전히 실패합니다.","en":"A natural 3 becomes a modified 4 and hits; a natural 1 still fails."}],"result":{"ko":"지원자 수를 그대로 더한 +2가 아니라 +1 보정으로 해결합니다.","en":"Resolve with +1 assistance rather than adding +2 for the two assistants."}},"pitfalls":[{"problem":{"ko":"지원 모델 수만큼 +1을 계속 더합니다.","en":"Adding +1 for every assisting model."},"fix":{"ko":"지원과 방해 각각에 대해 적법한 모델이 있는지만 확인하고 같은 보정은 한 번만 적용하세요.","en":"For each modifier kind, check whether an eligible model exists and then apply it only once."}}],"selfCheck":{"ko":"보정마다 어떤 모델이 자격을 충족했는지와 최종 명중 목표를 설명할 수 있나요?","en":"Can you identify the eligible model for each modifier and explain the final hit requirement?"}},"after-fight":{"objective":{"ko":"정리 이동의 종료 제한과 라스트 블로의 대결을 따로 해결합니다.","en":"Resolve consolidation endpoints separately from the Last Blow contest."},"preparation":[{"ko":"활성 모델의 I·S, 교전했던 적들의 최종 상태와 주위 적까지 거리를 확인하세요.","en":"Check the active model’s I and S, the final states of its engaged enemies, and distances to nearby enemies."}],"walkthrough":[{"title":{"ko":"정리 이동 자격 확인","en":"Check consolidation eligibility"},"body":{"ko":"활성 모델과 교전하던 적 전부가 OOA·중상·중손상 상태가 되었는지 확인합니다. 아직 정상 적과 교전 중이면 이 조건을 충족하지 못합니다.","en":"Check whether every enemy engaged with the active model became OOA or Seriously Injured/Damaged. A remaining healthy engaged enemy prevents this eligibility."},"result":{"ko":"정리 이동 가능 여부를 먼저 정합니다.","en":"Eligibility is decided before measuring a consolidation."}},{"title":{"ko":"경로와 종료점 구분","en":"Separate route and endpoint"},"body":{"ko":"허용 정리 이동은 I인치입니다. 도중에 적 1인치 안을 지나도 종료는 모든 적에서 최소 1인치 밖이어야 합니다.","en":"A permitted consolidation moves I inches. It may pass within 1 inch of an enemy, but must end at least 1 inch from every enemy."},"result":{"ko":"이동 가능 거리와 합법적인 종료점이 모두 확인됩니다.","en":"Both the distance allowance and a legal endpoint are checked."}},{"title":{"ko":"라스트 블로 대결","en":"Resolve the Last Blow contest"},"body":{"ko":"라스트 블로가 허용된 경우 1인치 내 중상 적과 양쪽 D6+S를 비교합니다. 실행 모델이 동점 이상이면 표적을 OOA로 만듭니다.","en":"When Last Blow is permitted, compare both models’ D6+S against a Seriously Injured enemy within 1 inch. A tie or better for the acting model causes OOA."},"result":{"ko":"중상을 자동 사망 처리하지 않고 대결 결과를 적용합니다.","en":"Apply the contest instead of treating Serious injury as automatic death."}}],"workedExample":{"situation":{"ko":"라스트 블로 실행자의 S는 4이고 D6은 2, 표적의 S는 3이고 D6은 3입니다.","en":"A Last Blow actor has S 4 and rolls 2; its target has S 3 and rolls 3."},"steps":[{"ko":"실행자는 4+2=6, 표적은 3+3=6입니다.","en":"The actor totals 4+2=6 and the target totals 3+3=6."},{"ko":"동점 이상 조건에 해당하므로 이 라스트 블로는 OOA를 발생시킵니다.","en":"The tie meets the tie-or-better condition, so this Last Blow causes OOA."}],"result":{"ko":"표적은 OOA가 되지만 캠페인 사망 여부는 이후 지속 부상 절차와 구분합니다.","en":"The target becomes OOA; campaign death remains a separate lasting-injury determination."}},"pitfalls":[{"problem":{"ko":"중상 표적을 자동 사망 처리하거나 적 베이스 바로 옆에 정리 이동을 끝냅니다.","en":"Automatically declaring a Seriously Injured target dead or ending consolidation next to an enemy base."},"fix":{"ko":"해당 행동의 대결을 굴리고 정리 이동 종료는 모든 적에서 1인치 이상 떨어지게 하세요.","en":"Roll the action’s contest and ensure consolidation ends at least 1 inch from every enemy."}}],"selfCheck":{"ko":"정리 이동 조건과 라스트 블로 성공 조건을 각각 말할 수 있나요?","en":"Can you state the separate eligibility for consolidation and success condition for Last Blow?"}},"melee-practice":{"objective":{"ko":"차지한 A 2 모델의 공격을 주무기 3회와 보조무기 1회로 검산합니다.","en":"Audit a charging A 2 model as 3 primary attacks and 1 offhand attack."},"preparation":[{"ko":"연습에서는 라이트·탑승 등 예외가 없는 적법한 두 무기라고 가정하세요.","en":"For this exercise, assume two legal weapons with no Light, Mounted, or other exceptions."}],"walkthrough":[{"title":{"ko":"주어진 조건 표시","en":"Mark the stated conditions"},"body":{"ko":"활성 모델의 A 2, 이번 활성화 차지 성공, 보조무기 적법성을 표시합니다. 상대가 비활성이라는 조건도 별도로 적습니다.","en":"Mark A 2, a successful charge this activation, and a legal offhand. Separately note that the opponent is non-active."},"result":{"ko":"실제 주어진 정보만 사용합니다.","en":"Only the supplied conditions are used."}},{"title":{"ko":"주무기 계산","en":"Calculate the primary"},"body":{"ko":"활성 주무기 공격은 A 2에 차지 보너스 1을 더해 3회입니다. I +2는 공격 순서 보너스여서 여기 더하지 않습니다.","en":"Active primary attacks are A 2 plus 1 for charging, totaling 3. The +2 I bonus affects order and is not added here."},"result":{"ko":"주무기 주사위 세 개를 준비합니다.","en":"Prepare three primary dice."}},{"title":{"ko":"보조무기와 상대 계산","en":"Calculate offhand and opponent"},"body":{"ko":"적법한 보조무기는 1회입니다. 따라서 내 공격은 3+1이고 비활성 상대는 자신의 주무기 1회로 구분합니다.","en":"The legal offhand contributes 1 attack. Your groups are therefore 3+1, while the non-active opponent has its own 1 primary attack."},"result":{"ko":"주무기와 보조무기의 프로필을 섞지 않고 답을 고릅니다.","en":"Choose the answer while retaining distinct weapon profiles."}}],"workedExample":{"situation":{"ko":"연습 모델은 A 2, 차지 성공, 일반 주무기와 적법한 보조무기를 갖췄습니다.","en":"The exercise model has A 2, a successful charge, an ordinary primary, and a legal offhand."},"steps":[{"ko":"주무기: 2+1=3회입니다.","en":"Primary: 2+1=3 attacks."},{"ko":"보조무기: 1회, 합계는 4회지만 무기별로는 3+1입니다.","en":"Offhand: 1 attack. The total is 4, allocated as 3+1 between the weapons."}],"result":{"ko":"총 네 번이라는 숫자보다 3+1 배분이 실제 해결에 필요합니다.","en":"The 3+1 allocation, rather than the total of four alone, is required to resolve the attacks."}},"pitfalls":[{"problem":{"ko":"공격 총수가 같다는 이유로 주무기 네 번으로 처리합니다.","en":"Resolving four primary attacks merely because the overall total is four."},"fix":{"ko":"무기마다 S·AP·L이 다를 수 있으므로 주무기 3회와 보조무기 1회를 유지하세요.","en":"Keep 3 primary and 1 offhand attack because their S, AP, and L can differ."}}],"selfCheck":{"ko":"차지 공격 수 보너스와 I 보너스를 구분하고 주·보조무기 배분을 말할 수 있나요?","en":"Can you distinguish the charge attack bonus from its I bonus and state the weapon allocation?"},"exerciseHint":{"ko":"주무기는 A와 차지, 보조무기는 별도의 1회로 계산하세요.","en":"Calculate A plus charge for the primary, then add the separate one offhand attack."},"optionFeedback":{"1":{"ko":"A를 두 무기에 똑같이 배분하지 않습니다. 보조무기는 1회입니다.","en":"A is not duplicated across both weapons; the offhand gets one attack."},"2":{"ko":"주무기 2+1=3, 보조무기 1로 정확히 나눴습니다.","en":"This correctly separates primary 2+1=3 from the one offhand attack."},"3":{"ko":"네 번 전부를 주무기로 바꾸면 보조무기 프로필을 잃습니다.","en":"Putting all four into the primary incorrectly removes the offhand profile."}}}},"wounds-recovery":{"wounds-lethality":{"objective":{"ko":"W 감소와 L 부상 주사위를 서로 다른 단계로 계산합니다.","en":"Calculate W loss and L injury dice as separate stages."},"preparation":[{"ko":"공격의 L, 막지 못한 운드 수, 표적의 현재 W를 기록하세요.","en":"Record the attack’s L, unsaved wounds, and the target’s current W."}],"walkthrough":[{"title":{"ko":"운드 확인","en":"Confirm the wound"},"body":{"ko":"명중과 운드 성공 뒤 세이브까지 해결했는지 확인합니다. 막지 못한 운드 하나마다 W를 1만 줄입니다.","en":"Confirm hits, wound tests, and saves have resolved. Each unsaved wound reduces W by exactly one."},"result":{"ko":"명중만으로 W를 줄이지 않습니다.","en":"A hit alone never removes W."}},{"title":{"ko":"0에 도달했는지 확인","en":"Check for zero W"},"body":{"ko":"W는 0 아래로 내려가지 않습니다. W가 0에 도달하거나 이미 0에서 추가 피해를 받으면 부상 주사위 단계로 갑니다.","en":"W cannot fall below zero. Reaching zero, or suffering further damage while already at zero, triggers injury dice."},"result":{"ko":"현재 W와 부상 발생 여부가 분리됩니다.","en":"Current W and injury eligibility are tracked separately."}},{"title":{"ko":"L개 굴리고 하나 선택","en":"Roll L and select one"},"body":{"ko":"그 공격의 L만큼 부상 주사위를 굴린 뒤 결과 하나를 선택하고 나머지를 버립니다. L을 W 감소량으로 쓰지 않습니다.","en":"Roll the attack’s L injury dice, select one result, and discard the others. Never use L as the amount of W loss."},"result":{"ko":"선택한 부상 결과 하나만 적용합니다.","en":"Apply only the selected injury result."}}],"workedExample":{"situation":{"ko":"W 2 모델이 L 3 공격에서 막지 못한 운드 하나를 받았습니다.","en":"A W 2 model suffers one unsaved wound from an L 3 attack."},"steps":[{"ko":"W는 2−1=1입니다. L 3이라도 W를 세 번 줄이지 않습니다.","en":"W becomes 2−1=1. L 3 does not remove three W."},{"ko":"W가 아직 0이 아니므로 이 운드로 부상 주사위를 굴리지 않습니다.","en":"W remains above zero, so this wound does not trigger injury dice."}],"result":{"ko":"현재 W는 1이고 부상 결과는 아직 없습니다.","en":"The model has W 1 and no injury result from this wound."}},"pitfalls":[{"problem":{"ko":"L을 피해 수치처럼 W에서 그대로 차감합니다.","en":"Subtracting L directly from W as a damage amount."},"fix":{"ko":"W 감소는 운드당 1, L은 부상 주사위 수라고 각각 적으세요.","en":"Write two separate quantities: one W lost per wound, and L injury dice."}}],"selfCheck":{"ko":"W 1과 L 3에서 운드 하나를 받으면 W와 부상 주사위 수를 각각 말할 수 있나요?","en":"For W 1 and L 3 with one unsaved wound, can you state the new W and injury-dice count separately?"}},"injury-results":{"objective":{"ko":"전장 부상 상태, OOA와 캠페인 사망을 구별합니다.","en":"Distinguish battlefield injury states, OOA, and campaign death."},"preparation":[{"ko":"선택한 부상 결과와 모델의 기존 상태를 확인하세요.","en":"Check the selected injury result and the model’s previous state."}],"walkthrough":[{"title":{"ko":"결과 이름 읽기","en":"Read the result"},"body":{"ko":"인저드·대미지드, 시리어슬리 인저드·대미지드, 아웃 오브 액션 중 무엇인지 확인합니다. 전투원과 차량의 용어를 구분합니다.","en":"Identify Injured/Damaged, Seriously Injured/Damaged, or Out of Action, using the appropriate fighter or vehicle terminology."},"result":{"ko":"정확한 상태를 표시합니다.","en":"Mark the exact state."}},{"title":{"ko":"기존 상태와 비교","en":"Compare the previous state"},"body":{"ko":"이미 중상인 모델에게 중상 결과를 다시 적용해도 그 자체로 추가 효과는 없습니다. OOA는 전장에서 제거하는 결과입니다.","en":"Repeating Seriously Injured on an already Seriously Injured model causes no extra effect by itself. OOA removes the model from the battlefield."},"result":{"ko":"중상 반복을 자동 OOA로 올리지 않습니다.","en":"Repeated Serious injury is not automatically escalated to OOA."}},{"title":{"ko":"캠페인 결과 따로 처리","en":"Resolve campaign consequences separately"},"body":{"ko":"캠페인의 OOA 사건은 필요한 지속 부상·손상 표를 별도로 처리합니다. OOA라는 이유만으로 앱의 킬 파이터나 삭제를 누르지 않습니다.","en":"In a campaign, resolve the required lasting-injury or damage table separately after OOA. Do not select Kill Fighter or Delete merely because the model became OOA."},"result":{"ko":"전장 제거와 영구 기록 변경을 분리합니다.","en":"Battlefield removal and permanent roster changes remain separate."}}],"workedExample":{"situation":{"ko":"중상인 파이터에게 다시 시리어슬리 인저드 결과가 선택되었습니다.","en":"A Seriously Injured fighter receives another selected Seriously Injured result."},"steps":[{"ko":"기존 상태와 새 결과가 모두 중상인지 확인합니다.","en":"Confirm that both the existing state and the new result are Seriously Injured."},{"ko":"다른 규칙의 OOA 원인이 없다면 중상 표시를 유지합니다.","en":"With no separate OOA cause, retain the Seriously Injured state."}],"result":{"ko":"중상 반복만으로 OOA나 사망을 추가하지 않습니다.","en":"Do not add OOA or death solely for repeating Serious injury."}},"pitfalls":[{"problem":{"ko":"OOA·중상·킬·삭제를 모두 같은 처리를 뜻한다고 봅니다.","en":"Treating OOA, Serious injury, Kill, and Delete as interchangeable."},"fix":{"ko":"전투 상태를 먼저 기록하고 지속 부상 결과가 확정된 다음 캠페인 기록을 변경하세요.","en":"Record the battle state first, then apply campaign changes only after the lasting result is established."}}],"selfCheck":{"ko":"OOA만 확인된 파이터에게 왜 바로 사망 처리를 하지 않는지 설명할 수 있나요?","en":"Can you explain why OOA alone does not justify marking a fighter dead?"}},"injury-practice":{"objective":{"ko":"W 1, L 2 상황을 W 감소 → 부상 굴림 → 하나 선택으로 해결합니다.","en":"Resolve W 1 and L 2 in the order W loss, injury roll, then selection."},"preparation":[{"ko":"막지 못한 운드는 하나이며 별도 무기 예외는 없다고 가정합니다.","en":"Assume one unsaved wound and no separate weapon exception."}],"walkthrough":[{"title":{"ko":"W 갱신","en":"Update W"},"body":{"ko":"운드 하나로 W 1을 0으로 줄입니다. 음수 W를 쓰지 않습니다.","en":"One unsaved wound reduces W 1 to zero. Do not record negative W."},"result":{"ko":"W 0이 부상 굴림 조건을 만족합니다.","en":"W zero triggers injury resolution."}},{"title":{"ko":"주사위 수 선택","en":"Choose the dice count"},"body":{"ko":"L 2를 읽고 부상 주사위 두 개를 준비합니다. W 감소량과 주사위 수를 혼동하지 않습니다.","en":"Read L 2 and prepare two injury dice, keeping that count separate from the W lost."},"result":{"ko":"두 주사위를 굴릴 준비가 됩니다.","en":"Two dice are ready to roll."}},{"title":{"ko":"하나만 적용","en":"Apply only one result"},"body":{"ko":"굴린 두 결과 중 하나를 선택합니다. 남은 결과를 추가 적용하지 않고 선택한 결과에 맞게 상태를 기록합니다.","en":"Select one of the two rolled results. Discard the other and record the state produced by the selected result."},"result":{"ko":"선택 결과 한 개만 모델에 적용됩니다.","en":"Exactly one selected result affects the model."}}],"workedExample":{"situation":{"ko":"W 1 모델에게 L 2의 막지 못한 운드가 하나 들어옵니다. 두 부상 주사위 결과가 서로 다릅니다.","en":"A W 1 model takes one unsaved L 2 wound, and the two injury dice show different results."},"steps":[{"ko":"W는 1−1=0입니다.","en":"W becomes 1−1=0."},{"ko":"L 2에 따라 두 개를 굴리고 그중 하나의 결과만 적용합니다.","en":"Roll two for L 2 and apply only one selected result."}],"result":{"ko":"정답은 W 0, 부상 주사위 두 개 중 하나 선택입니다.","en":"The correct resolution is W zero and one selected result from two injury dice."}},"pitfalls":[{"problem":{"ko":"두 주사위 결과를 모두 누적합니다.","en":"Applying both injury-dice results cumulatively."},"fix":{"ko":"부상 굴림 옆에 선택 1개라고 써서 결과 누적을 방지하세요.","en":"Write “select one” beside the injury roll to prevent cumulative application."}}],"selfCheck":{"ko":"선택지에서 W 감소와 주사위 선택 규칙이 모두 맞는 답을 찾았나요?","en":"Have you chosen an option that gets both W loss and result selection right?"},"exerciseHint":{"ko":"운드 하나는 W 1만 줄이고, L은 부상 주사위 수를 정합니다.","en":"One wound removes only one W; L determines the number of injury dice."},"optionFeedback":{"1":{"ko":"W는 0 아래로 내려가지 않으며 0이 되면 부상 굴림을 합니다.","en":"W cannot fall below zero; reaching zero triggers injury dice."},"2":{"ko":"W 감소량과 L의 역할, 하나 선택 규칙을 모두 적용했습니다.","en":"This applies W loss, the role of L, and selection of one result correctly."},"3":{"ko":"L 2는 두 결과를 모두 적용하라는 뜻이 아닙니다. 하나만 선택합니다.","en":"L 2 does not apply both results; select one."}}},"recovery-assist":{"objective":{"ko":"회복 자격과 근처 적을 먼저 확인하고 적법한 아군의 +1 주사위를 적용합니다.","en":"Check recovery eligibility and nearby enemies before adding a legal friendly assistance die."},"preparation":[{"ko":"활성화 시작 상태, 1인치 내 적·아군, 차량·비스트 여부를 확인하세요.","en":"Check the activation’s starting state, enemies and friendlies within 1 inch, and vehicle or Beast restrictions."}],"walkthrough":[{"title":{"ko":"회복 시점 확인","en":"Check the timing"},"body":{"ko":"중상·중손상으로 활성화를 시작한 모델은 활성화 끝에 회복합니다. 트리트 앨라이·리페어의 즉시 회복 테스트와 시점을 구분합니다.","en":"A model that started its activation Seriously Injured/Damaged recovers at its end. Distinguish this timing from immediate tests granted by Treat Ally or Repair."},"result":{"ko":"어떤 규칙으로 회복하는지 정합니다.","en":"Identify which rule grants the recovery."}},{"title":{"ko":"적의 자동 OOA 조건","en":"Check enemy-caused OOA"},"body":{"ko":"1인치 내에 중상·중손상이 아닌 적이 있으면 굴림 없이 OOA입니다. 아군 지원을 먼저 더해 이 조건을 무시하지 않습니다.","en":"A non-Seriously Injured/Damaged enemy within 1 inch causes OOA without a roll. Friendly assistance does not bypass that condition."},"result":{"ko":"자동 OOA라면 회복 주사위를 굴리지 않습니다.","en":"Do not roll recovery dice when automatic OOA applies."}},{"title":{"ko":"지원 자격과 결과 선택","en":"Check assistance and select a result"},"body":{"ko":"적 조건을 통과하면 적법한 아군 전투원 하나가 +1 주사위로 지원할 수 있습니다. 비스트·차량은 지원 불가이고 차량은 지원받지도 못합니다.","en":"If the enemy condition is absent, one eligible friendly fighter can add one die. Beasts and vehicles cannot assist, and vehicles cannot receive assistance."},"result":{"ko":"여러 주사위에서는 결과 하나만 선택합니다.","en":"Select one result when multiple dice are rolled."}}],"workedExample":{"situation":{"ko":"중상 파이터 1인치 내에 적은 없고, 비교전 정상 아군 전투원 한 명이 있습니다.","en":"No enemy is within 1 inch of a Seriously Injured fighter; one unengaged, non-Seriously Injured friendly fighter is in range."},"steps":[{"ko":"아군의 거리·상태·유형이 지원 조건을 충족하는지 확인합니다.","en":"Confirm the friendly model meets the assistance distance, state, and type requirements."},{"ko":"기본 회복 주사위에 지원 +1개를 더한 뒤 결과 하나를 선택합니다.","en":"Add one assistance die to the base recovery roll, then select one result."}],"result":{"ko":"지원자가 여러 명이어도 모델 수만큼 주사위를 계속 추가하지 않습니다.","en":"Do not add a die for every nearby friendly model."}},"pitfalls":[{"problem":{"ko":"차량을 지원자로 쓰거나 적 1인치 조건보다 지원을 우선합니다.","en":"Using a vehicle as an assistant or applying assistance before checking an enemy within 1 inch."},"fix":{"ko":"회복 자격 → 적 거리 → 아군 지원 자격 순서로 확인하세요.","en":"Check recovery eligibility, enemy distance, then friendly assistance eligibility."}}],"selfCheck":{"ko":"지원자에게 거리·상태·유형 제한을 각각 확인했나요?","en":"Have you checked distance, state, and type restrictions for the assistant?"}},"lasting-recovery":{"objective":{"ko":"OOA 사건의 D66과 이후 사이클의 리커버리를 별도 기록합니다.","en":"Track the OOA event’s D66 separately from Recovery during the remaining cycle."},"preparation":[{"ko":"해당 전투가 캠페인인지와 OOA 발생 사건 수를 확인하세요.","en":"Confirm whether this is a campaign battle and identify distinct OOA events."}],"walkthrough":[{"title":{"ko":"사건별 굴림 확인","en":"Identify event-based rolls"},"body":{"ko":"캠페인에서는 OOA 사건마다 상대가 지속 부상·손상 D66을 굴립니다. 여러 원인이 동시에 만든 한 사건은 표를 한 번만 굴립니다.","en":"In a campaign, the opponent rolls lasting injury/damage D66 per OOA event. Several simultaneous causes of one event still produce one table roll."},"result":{"ko":"원인 수를 사건 수로 잘못 늘리지 않습니다.","en":"The count of causes is not confused with the count of events."}},{"title":{"ko":"D66 읽기","en":"Read D66"},"body":{"ko":"첫 D6을 십의 자리, 두 번째 D6을 일의 자리로 읽습니다. 두 수를 더하거나 백분위 주사위처럼 읽지 않습니다.","en":"Read the first D6 as tens and the second as units. Do not add the dice or treat them as percentile dice."},"result":{"ko":"표에서 찾을 두 자리 결과를 얻습니다.","en":"You obtain the two-digit table result."}},{"title":{"ko":"리커버리 시점 기록","en":"Track Recovery timing"},"body":{"ko":"결과에 따라 캠페인 리커버리를 기록하면 그 사이클의 남은 전투와 포스트 사이클 행동에 참가할 수 없습니다. 명부 업데이트 시 해제합니다.","en":"If the result places a model in campaign Recovery, it cannot join later battles or post-cycle actions in that cycle. Clear it during roster updating."},"result":{"ko":"전투 중 중상과 사이클 리커버리를 구분합니다.","en":"Battlefield Serious injury remains distinct from cycle Recovery."}}],"workedExample":{"situation":{"ko":"하나의 OOA 사건 후 D66의 첫 주사위는 4, 두 번째는 2입니다.","en":"After one OOA event, the first D66 die shows 4 and the second shows 2."},"steps":[{"ko":"십의 자리 4와 일의 자리 2를 합쳐 42로 읽습니다.","en":"Read tens 4 and units 2 as 42."},{"ko":"현재 판본의 해당 표에서 42 항목을 찾아 적용하고, 상태와 수정치를 따로 기록합니다.","en":"Look up 42 on the matching-edition table and record its state changes and modifiers separately."}],"result":{"ko":"이 예시는 D66 읽기 연습이며 42의 특정 부상 효과를 추측하지 않습니다.","en":"This example practices reading D66; it does not guess the injury associated with 42."}},"pitfalls":[{"problem":{"ko":"D66을 4+2=6으로 읽거나 중상만으로 리커버리를 임의 부여합니다.","en":"Reading D66 as 4+2=6 or assigning campaign Recovery solely for battlefield Serious injury."},"fix":{"ko":"표 결과를 확인한 뒤 실제 적용되는 캠페인 상태만 기록하세요.","en":"Apply only the campaign state specified by the actual table result."}}],"selfCheck":{"ko":"중상, OOA, 지속 부상, 리커버리 네 항목의 기록 시점을 구분할 수 있나요?","en":"Can you distinguish when Serious injury, OOA, lasting injury, and Recovery are recorded?"}},"recovery-practice":{"objective":{"ko":"근처 적에 의한 자동 OOA가 아군 지원보다 우선함을 확인합니다.","en":"Recognize that enemy-caused automatic OOA takes precedence over friendly assistance."},"preparation":[{"ko":"중상 모델과 정상 적 사이 거리는 1인치 이내라고 가정하세요.","en":"Assume a non-Seriously Injured enemy is within 1 inch of the Seriously Injured model."}],"walkthrough":[{"title":{"ko":"회복 대상 확인","en":"Identify the recovering model"},"body":{"ko":"대상은 중상 파이터이며 회복할 시점입니다. 지원 아군이 있다는 사실만으로 굴림 가능 여부를 확정하지 않습니다.","en":"The target is a Seriously Injured fighter at recovery timing. A friendly assistant’s presence does not establish that a roll is permitted."},"result":{"ko":"회복 시점과 대상은 확인됩니다.","en":"The target and timing are established."}},{"title":{"ko":"적 거리 검사","en":"Inspect enemy distance"},"body":{"ko":"정상 적이 1인치 안에 있는지 먼저 봅니다. 이 연습은 그 조건을 충족하므로 회복 굴림 없이 OOA입니다.","en":"Check the nearby healthy enemy first. This exercise meets the within-1-inch condition, so OOA occurs without rolling."},"result":{"ko":"주사위 추가 단계로 넘어가지 않습니다.","en":"The process stops before adding recovery dice."}},{"title":{"ko":"캠페인 후속 분리","en":"Separate campaign follow-up"},"body":{"ko":"아군 지원 보너스로 자동 OOA를 취소하지 않습니다. OOA를 기록하고 캠페인이라면 필요한 지속 부상 절차를 따로 진행합니다.","en":"Do not cancel automatic OOA through assistance. Record OOA and separately resolve any required campaign lasting-injury procedure."},"result":{"ko":"굴림 없음과 캠페인 사망 아님을 구분합니다.","en":"No recovery roll does not mean automatic campaign death."}}],"workedExample":{"situation":{"ko":"중상 파이터에서 0.5인치 떨어진 정상 적과 0.5인치 떨어진 정상 아군이 있습니다.","en":"A healthy enemy and a healthy friendly model are each 0.5 inch from a Seriously Injured fighter."},"steps":[{"ko":"적 0.5인치는 자동 OOA 거리인 1인치 안입니다.","en":"The enemy at 0.5 inch is inside the 1-inch automatic OOA distance."},{"ko":"아군 거리도 가까우나 이 조건은 회복 굴림 자체를 허용하지 않습니다.","en":"The friendly model is also close, but that does not permit the prohibited recovery roll."}],"result":{"ko":"주사위를 굴리지 않고 OOA를 적용합니다.","en":"Apply OOA without rolling."}},"pitfalls":[{"problem":{"ko":"적과 아군이 모두 있으니 서로 상쇄한다고 생각합니다.","en":"Assuming the enemy and friendly models cancel each other out."},"fix":{"ko":"지원은 굴림에 주사위를 더할 뿐, 적에 의한 자동 OOA 조건을 제거하지 않습니다.","en":"Assistance adds a die to a permitted roll; it does not remove enemy-caused automatic OOA."}}],"selfCheck":{"ko":"답을 고르기 전에 회복 주사위를 아예 굴릴 수 있는 상황인지 확인했나요?","en":"Before answering, did you check whether recovery dice may be rolled at all?"},"exerciseHint":{"ko":"아군 지원을 계산하기 전에 정상 적 1인치 조건부터 검사하세요.","en":"Check for a healthy enemy within 1 inch before calculating assistance."},"optionFeedback":{"1":{"ko":"아군은 적의 자동 OOA 조건을 지우지 못합니다.","en":"A friendly model cannot remove the enemy’s automatic OOA condition."},"2":{"ko":"추가 주사위 수의 문제가 아니라 회복 굴림이 허용되지 않는 상황입니다.","en":"The issue is not the bonus dice count; no recovery roll is permitted."},"3":{"ko":"정상 적이 1인치 안에 있으므로 굴림 없이 OOA입니다.","en":"A healthy enemy within 1 inch causes OOA without a roll."}}}},"morale-objectives":{"tests-checks":{"objective":{"ko":"테스트는 목표 이상, 체크는 목표 이하라는 방향부터 확인합니다.","en":"Identify the comparison direction: tests meet or exceed a target, checks meet or fall below it."},"preparation":[{"ko":"판정 이름, 사용할 능력치와 주사위 종류를 확인하세요.","en":"Check the named roll, characteristic, and dice type."}],"walkthrough":[{"title":{"ko":"판정 이름 읽기","en":"Read the roll name"},"body":{"ko":"WS·BS의 D6 테스트인지 정신 능력치의 2D6 체크인지 구분합니다. 숫자만 보고 큰 수가 항상 좋다고 가정하지 않습니다.","en":"Distinguish a WS/BS D6 test from a mental-characteristic 2D6 check. Do not assume larger results are always better."},"result":{"ko":"주사위 종류와 비교 방향을 정합니다.","en":"Identify both the dice and comparison direction."}},{"title":{"ko":"목표와 비교","en":"Compare with the target"},"body":{"ko":"테스트는 목표 이상이면 성공하고 체크는 능력치 이하이면 성공합니다. 자연 결과 예외가 명시되어 있으면 함께 적용합니다.","en":"Tests succeed at or above their target; checks succeed at or below the characteristic. Apply explicit natural-result exceptions as well."},"result":{"ko":"같은 굴림이라도 판정 종류에 맞게 해석합니다.","en":"Interpret the result using the correct kind of roll."}},{"title":{"ko":"리롤 기록","en":"Track rerolls"},"body":{"ko":"리롤은 같은 주사위에 한 번만 적용하며 새 결과를 사용합니다. 두 결과 중 좋은 것을 고르는 방식이 아닙니다.","en":"A die may be rerolled only once, and the new result must be used. This does not mean choosing the better of both rolls."},"result":{"ko":"리롤 사용 여부와 최종 결과가 분명합니다.","en":"Reroll usage and the final result are clear."}}],"workedExample":{"situation":{"ko":"자연 결과 예외가 없는 Cool 7 체크에서 2D6 합이 6입니다.","en":"A Cool 7 check totals 6 on 2D6, with no natural-result exception relevant."},"steps":[{"ko":"체크이므로 6이 Cool 7 이하인지 비교합니다.","en":"Because this is a check, compare whether 6 is at or below Cool 7."},{"ko":"6≤7이므로 성공입니다. 목표 이상 규칙을 가져오지 않습니다.","en":"It succeeds because 6≤7; do not substitute the test’s meet-or-exceed rule."}],"result":{"ko":"같은 능력치 체크에서 합 8은 7을 초과하므로 실패합니다.","en":"A total of 8 would fail the same check because it exceeds 7."}},"pitfalls":[{"problem":{"ko":"높은 수가 좋다는 WS·BS 감각을 Cool 체크에 그대로 씁니다.","en":"Using the high-is-good logic of WS/BS for a Cool check."},"fix":{"ko":"굴리기 전에 테스트인가 체크인가를 말하고 성공 비교식을 적으세요.","en":"Before rolling, say whether it is a test or check and state its success comparison."}}],"selfCheck":{"ko":"판정에 쓸 주사위와 성공 방향을 굴리기 전에 설명할 수 있나요?","en":"Can you state the dice and success direction before rolling?"}},"nerve":{"objective":{"ko":"OOA 관찰자의 거리와 적법한 리더십 지원을 확인해 신경 체크를 해결합니다.","en":"Resolve Nerve by checking observer distance and eligible leadership support."},"preparation":[{"ko":"OOA가 된 아군과 관찰 모델의 거리, 시야, Cool을 확인하세요.","en":"Check the distance to the friendly OOA event, visibility, and the observer’s Cool."}],"walkthrough":[{"title":{"ko":"관찰 대상 찾기","en":"Find affected observers"},"body":{"ko":"아군 모델이 OOA가 되면 그 사건에서 3인치 이내인 관찰 모델을 확인합니다. 멀리 있는 모델에게 같은 이유로 자동 체크를 주지 않습니다.","en":"When a friendly model becomes OOA, identify observers within 3 inches. Do not extend that trigger automatically to distant models."},"result":{"ko":"체크가 필요한 관찰자를 구분합니다.","en":"Identify which observers must check."}},{"title":{"ko":"지원 능력치 자격","en":"Check supported Cool"},"body":{"ko":"보이는 적법한 챔피언은 6인치, 리더는 12인치 범위에서 Cool을 제공할 수 있습니다. 거리뿐 아니라 유형과 상태 조건을 확인합니다.","en":"An eligible visible Champion can provide Cool within 6 inches, or a Leader within 12 inches. Check type and state as well as distance."},"result":{"ko":"사용할 Cool의 출처가 분명합니다.","en":"The source of the Cool value is established."}},{"title":{"ko":"체크와 상태 표시","en":"Roll and mark the state"},"body":{"ko":"선택한 적법한 Cool로 체크하고 실패하면 서프레스드 상태를 표시합니다. OOA가 된 모델의 상태와 관찰자의 상태를 따로 기록합니다.","en":"Make the check using the eligible Cool value; failure makes the observer Suppressed. Track this separately from the original model’s OOA state."},"result":{"ko":"연쇄 효과를 대상별로 정확히 기록합니다.","en":"Record the consequence for each affected observer."}}],"workedExample":{"situation":{"ko":"OOA 사건에서 2인치 떨어진 관찰자가 있고, 보이는 적법한 챔피언이 그 관찰자에게서 5인치 거리에 있습니다.","en":"An observer is 2 inches from the OOA event, with an eligible visible Champion 5 inches from that observer."},"steps":[{"ko":"관찰자는 3인치 안이므로 신경 체크 대상입니다.","en":"The observer is inside 3 inches and must make the Nerve check."},{"ko":"챔피언은 6인치 안이므로 나머지 자격도 충족하면 그 Cool을 사용할 수 있습니다.","en":"The Champion is inside 6 inches, so its Cool may be used if its other eligibility conditions are met."}],"result":{"ko":"체크에 실패하면 관찰자를 서프레스드로 표시하며 즉시 OOA로 만들지는 않습니다.","en":"Failure makes the observer Suppressed, rather than immediately OOA."}},"pitfalls":[{"problem":{"ko":"챔피언이 가깝기만 하면 시야나 상태와 무관하게 Cool을 씁니다.","en":"Using a nearby Champion’s Cool without checking visibility or state."},"fix":{"ko":"지원자의 거리·시야·유형·상태를 모두 확인한 다음 Cool을 선택하세요.","en":"Choose supported Cool only after checking distance, visibility, type, and state."}}],"selfCheck":{"ko":"OOA 거리와 지원 거리 두 가지를 서로 다른 기준점에서 재었나요?","en":"Did you measure the OOA-trigger distance and support distance from their separate reference models?"}},"bottle":{"objective":{"ko":"이번 라운드의 OOA 발동 조건과 전투 이탈 결과를 확인합니다.","en":"Check this round’s OOA trigger and resolve the resulting Bottle consequences."},"preparation":[{"ko":"이번 라운드 자갱 OOA 기록과 전장에 남은 적법한 Ld를 확인하세요.","en":"Review your gang’s OOA events this round and eligible Ld values still on the battlefield."}],"walkthrough":[{"title":{"ko":"이번 라운드만 확인","en":"Inspect this round"},"body":{"ko":"종료 단계에서 이번 라운드에 자갱 OOA가 하나 이상 있었는지 확인합니다. 이전 라운드의 사건만으로 이번 기본 발동 조건을 채우지 않습니다.","en":"At the end phase, check whether your gang suffered at least one OOA this round. An event only in an earlier round does not meet this basic trigger."},"result":{"ko":"불필요한 반복 체크를 막습니다.","en":"Avoid an unwarranted repeated check."}},{"title":{"ko":"적법한 Ld 선택","en":"Choose eligible Ld"},"body":{"ko":"발동했다면 전장에 남은 적법한 모델 중 최고 Ld로 체크합니다. 별도 시나리오 예외도 확인합니다.","en":"If triggered, check against the highest eligible Ld on the battlefield. Also inspect any scenario-specific exception."},"result":{"ko":"대상 능력치와 판정이 정해집니다.","en":"The eligible characteristic and check are established."}},{"title":{"ko":"철수 대상 선택","en":"Choose withdrawals"},"body":{"ko":"실패하면 모델 하나, 자연 12면 둘을 철수시킵니다. 비교전 아군이 남아 있으면 교전 모델을 먼저 선택하지 않습니다. 중상 철수자는 굴복도 별도 처리합니다.","en":"Failure withdraws one model; natural 12 withdraws two. Do not choose an engaged model first while unengaged friendlies remain. Resolve Succumb separately for Seriously Injured withdrawals."},"result":{"ko":"철수 수와 선택 제한을 함께 지킵니다.","en":"Respect both the withdrawal count and selection restrictions."}}],"workedExample":{"situation":{"ko":"이번 라운드에 자갱 OOA 한 명이 발생했고 전투 이탈 체크의 자연 합이 12입니다.","en":"Your gang suffered one OOA this round, and the Bottle check has a natural total of 12."},"steps":[{"ko":"이번 라운드 사건이 있으므로 기본 체크가 발동합니다.","en":"An OOA this round establishes the basic trigger."},{"ko":"자연 12 결과에 따라 철수 모델 두 명을 선택하며 비교전 우선 제한을 지킵니다.","en":"The natural 12 withdraws two models, chosen under the unengaged-first restriction."}],"result":{"ko":"이전 사건의 수를 더해 철수 수를 임의로 늘리지 않습니다.","en":"Do not add previous OOA counts to invent extra withdrawals."}},"pitfalls":[{"problem":{"ko":"한 번 OOA가 있으면 이후 매 라운드 자동 체크한다고 생각합니다.","en":"Assuming one OOA forces a check in every later round."},"fix":{"ko":"라운드별 OOA 칸을 새로 구분해 이번 라운드 발동을 확인하세요.","en":"Track OOA events by round so the current trigger can be checked explicitly."}}],"selfCheck":{"ko":"이번 라운드의 발동 사건과 철수 대상 선택 제한을 말할 수 있나요?","en":"Can you identify this round’s trigger and the restrictions on choosing withdrawn models?"},"exerciseHint":{"ko":"이번 라운드라는 발동 조건에 밑줄을 긋고 이전 라운드 기록과 분리하세요.","en":"Underline “this round” in the trigger and separate it from earlier-round events."},"optionFeedback":{"1":{"ko":"이번 라운드 OOA가 없어 기본 발동 조건이 없습니다.","en":"There is no OOA this round, so the basic trigger is absent."},"2":{"ko":"이전 사건을 이후 모든 라운드로 자동 연장하지 않습니다.","en":"An earlier OOA does not automatically extend the trigger to every later round."},"3":{"ko":"단순 인원 감소가 발동 조건이 아니며 판정도 임의의 D6이 아닙니다.","en":"A smaller crew alone is not the trigger, and the check is not an arbitrary D6 roll."}}},"voluntary":{"objective":{"ko":"자발적 전투 포기 기준과 중상 모델의 굴복을 구분합니다.","en":"Distinguish the threshold for voluntary fleeing from Succumb for injured models."},"preparation":[{"ko":"시작 크루 수, OOA·철수 수, 남은 중상 모델을 기록하세요.","en":"Record the starting crew size, OOA/withdrawn count, and remaining Seriously Injured models."}],"walkthrough":[{"title":{"ko":"3분의 1 올림 계산","en":"Round up one third"},"body":{"ko":"시작 크루의 3분의 1을 올림한 수가 자발적 전투 포기 기준입니다. 현재 전장 인원 수로 기준을 다시 줄이지 않습니다.","en":"The voluntary-fleeing threshold is one third of the starting crew, rounded up. Do not recalculate it from the reduced current crew."},"result":{"ko":"전투 시작 기준이 유지됩니다.","en":"The battle’s starting reference remains fixed."}},{"title":{"ko":"시점과 패배 확인","en":"Check timing and defeat"},"body":{"ko":"OOA·철수 합계가 기준 이상이면 승리 확인 시작에 자발적으로 도망칠 수 있습니다. 선택하면 갱을 제거하고 자동 패배를 적용합니다.","en":"Once OOA plus withdrawals reaches the threshold, voluntary fleeing is available at the start of the victory check. Choosing it removes the gang and applies automatic defeat."},"result":{"ko":"가능 여부와 선택의 결과를 구분합니다.","en":"Separate eligibility from the consequences of choosing it."}},{"title":{"ko":"굴복 별도 처리","en":"Resolve Succumb separately"},"body":{"ko":"종료 시 중상·중손상 모델은 D6 3+로 생존하고 1–2면 OOA와 지속 부상·손상을 처리합니다. 중상으로 철수한 모델도 확인합니다.","en":"At battle end, a Seriously Injured/Damaged model survives on D6 3+; 1–2 causes OOA and lasting injury/damage. Also check models withdrawn while Seriously Injured."},"result":{"ko":"도망침이 중상 후속 처리를 지우지 않습니다.","en":"Fleeing does not erase injured-model follow-up."}}],"workedExample":{"situation":{"ko":"시작 크루가 7명이며 OOA 두 명과 철수 한 명이 있습니다.","en":"A gang started with seven crew and now has two OOA models plus one withdrawal."},"steps":[{"ko":"7÷3은 약 2.33이므로 올림한 기준은 3입니다.","en":"Seven divided by three is about 2.33, rounded up to a threshold of three."},{"ko":"OOA 2+철수 1=3으로 기준에 도달합니다. 정해진 시점에 포기를 선택할 수 있습니다.","en":"Two OOA plus one withdrawal equals three, meeting the threshold for the specified decision timing."}],"result":{"ko":"선택하면 자동 패배이며 중상 모델의 굴복은 별도로 확인합니다.","en":"Choosing to flee means automatic defeat; injured models still require their separate Succumb resolution."}},"pitfalls":[{"problem":{"ko":"7명의 3분의 1을 2로 내림하거나 현재 크루 수를 기준으로 씁니다.","en":"Rounding one third of seven down to two or using the current crew size."},"fix":{"ko":"시작 크루 수를 남겨 두고 항상 올림 계산을 하세요.","en":"Retain the starting crew size and always round the fraction upward."}}],"selfCheck":{"ko":"포기 가능 기준, 선택 시점, 선택 후 중상 처리를 모두 구분했나요?","en":"Have you separated the threshold, decision timing, and injured-model follow-up?"}},"control":{"objective":{"ko":"통제 가능한 아군과 방해 가능한 적을 유형·상태별로 확인합니다.","en":"Assess controlling friendlies and contesting enemies by type and state."},"preparation":[{"ko":"목표 중심 3인치 내 모든 모델의 진영·유형·상태를 확인하세요.","en":"Identify the side, type, and state of every model within 3 inches of the objective center."}],"walkthrough":[{"title":{"ko":"범위와 상태 확인","en":"Check range and state"},"body":{"ko":"목표 중심에서 3인치 범위를 재고 중상·중손상 모델은 이 판정에서 제외합니다. 단순히 베이스끼리 가까운지를 보지 않습니다.","en":"Measure 3 inches from the objective center and ignore Seriously Injured/Damaged models for this determination. Do not measure only between bases."},"result":{"ko":"통제 판정에 참여하는 모델 목록이 정해집니다.","en":"Identify the models relevant to objective control."}},{"title":{"ko":"통제·방해 자격 구분","en":"Separate control and contest"},"body":{"ko":"펫이 아닌 적법한 아군 전투원 한 명 이상과 적 모델 0명이 필요합니다. 차량·펫은 통제할 수 없지만 적이라면 방해합니다.","en":"Control requires at least one eligible non-Pet friendly fighter and zero enemy models. Vehicles and Pets cannot control but may contest for the enemy."},"result":{"ko":"수적 우세가 아니라 조건 충족 여부를 판단합니다.","en":"Judge conditions rather than numerical superiority."}},{"title":{"ko":"XP 수령자 선택","en":"Choose the XP recipient"},"body":{"ko":"통제했다면 적법한 통제 전투원 중 한 명을 선택해 목표 XP를 줍니다. 전투원별 전투당 한 번 제한과 시나리오 예외를 확인합니다.","en":"If controlling, choose one eligible controlling fighter for objective XP. Check its once-per-fighter-per-battle limit and any scenario exception."},"result":{"ko":"목표 주변 모두에게 XP를 주지 않습니다.","en":"XP is not distributed to every nearby model."}}],"workedExample":{"situation":{"ko":"정상 아군 갱어 두 명만 목표 중심 2인치 내에 있고 적은 없습니다.","en":"Two healthy friendly Gangers are within 2 inches of the objective center, and no enemy is present."},"steps":[{"ko":"두 갱어는 통제 가능한 아군이며 적 모델은 0명입니다.","en":"Both Gangers can control and the enemy-model count is zero."},{"ko":"통제 후 아직 이번 전투에 목표 XP를 받지 않은 적법한 전투원 한 명을 선택합니다.","en":"After establishing control, choose one eligible fighter that has not already received its objective XP this battle."}],"result":{"ko":"목표를 통제하지만 두 모델 모두에게 자동으로 XP를 주지는 않습니다.","en":"The gang controls the objective without automatically awarding XP to both fighters."}},"pitfalls":[{"problem":{"ko":"아군이 더 많으니 적 모델이 있어도 통제한다고 생각합니다.","en":"Assuming a friendly numerical advantage permits control despite an enemy being present."},"fix":{"ko":"적법한 적 모델이 하나라도 범위 안에 있으면 기본 통제 조건을 다시 확인하세요.","en":"If any eligible enemy is in range, recheck the basic no-enemy condition."}}],"selfCheck":{"ko":"목표 범위의 각 모델을 통제 가능·방해만 가능·상태 때문에 제외로 구분했나요?","en":"Have you classified nearby models as controlling, contesting only, or ignored because of state?"}},"objective-practice":{"objective":{"ko":"적 펫이 통제는 못 해도 아군 통제를 방해한다는 점을 적용합니다.","en":"Apply the distinction that an enemy Pet may contest even though it cannot control."},"preparation":[{"ko":"정상 아군 갱어와 정상 적 펫이 모두 목표 중심 3인치 안이라고 가정합니다.","en":"Assume both the healthy friendly Ganger and healthy enemy Pet are within 3 inches of the center."}],"walkthrough":[{"title":{"ko":"아군 자격 확인","en":"Check the friendly fighter"},"body":{"ko":"아군 갱어는 펫이 아닌 전투원이며 중상이 아니므로 통제 가능한 모델입니다. 이것만으로 통제 결론을 내리지는 않습니다.","en":"The healthy friendly Ganger is a non-Pet fighter able to control. This alone does not establish control."},"result":{"ko":"첫 조건은 충족됩니다.","en":"The first condition is met."}},{"title":{"ko":"적 모델 확인","en":"Inspect enemy models"},"body":{"ko":"적 펫도 적 모델이며 중상이 아닙니다. 펫의 통제 불가와 방해 불가를 혼동하지 않습니다.","en":"The healthy enemy Pet is an enemy model. Its inability to control does not imply inability to contest."},"result":{"ko":"적 모델 0명 조건이 충족되지 않습니다.","en":"The zero-enemy-model condition is not met."}},{"title":{"ko":"통제·XP 결론","en":"Conclude control and XP"},"body":{"ko":"기본 조건상 아군은 통제하지 못합니다. 동수라는 이유로 양쪽에 XP를 주거나 펫을 없는 것으로 처리하지 않습니다.","en":"Under the basic conditions the friendly gang does not control. Equal counts do not grant XP to both sides, and the Pet is not ignored."},"result":{"ko":"통제 없음이라는 결과를 기록합니다.","en":"Record that there is no friendly control."}}],"workedExample":{"situation":{"ko":"갱어는 중심에서 2인치, 적 펫은 2.5인치이며 모두 정상 상태입니다.","en":"The Ganger is 2 inches from the center; the healthy enemy Pet is 2.5 inches away."},"steps":[{"ko":"두 모델 모두 3인치 범위에 포함됩니다.","en":"Both models are inside the 3-inch radius."},{"ko":"펫은 방해하므로 갱어의 통제 가능성만으로 점수를 줄 수 없습니다.","en":"The Pet contests, so the Ganger’s eligibility alone does not produce control."}],"result":{"ko":"적 펫이 목표 통제를 막으므로 이 상황에서 목표 통제 XP를 주지 않습니다.","en":"The enemy Pet prevents control, so no objective-control XP is awarded for this situation."}},"pitfalls":[{"problem":{"ko":"펫이 XP를 못 받으니 목표 판정에서도 무시합니다.","en":"Ignoring a Pet for control merely because it cannot earn control XP."},"fix":{"ko":"통제 자격과 방해 자격을 각각 따로 검사하세요.","en":"Check controlling eligibility and contesting eligibility separately."}}],"selfCheck":{"ko":"펫이 할 수 없는 것과 할 수 있는 것을 한 문장씩 구분할 수 있나요?","en":"Can you state separately what the Pet cannot do and what it still can do?"},"exerciseHint":{"ko":"펫의 통제 가능과 방해 가능을 별도 칸으로 나눠 보세요.","en":"Put the Pet’s ability to control and ability to contest in separate columns."},"optionFeedback":{"1":{"ko":"펫은 통제할 수 없어도 적의 통제를 방해할 수 있습니다.","en":"A Pet can contest enemy control even though it cannot control."},"2":{"ko":"범위 안의 정상 적 펫이 적 모델 0명 조건을 깨뜨립니다.","en":"The healthy enemy Pet in range breaks the zero-enemy-model condition."},"3":{"ko":"동수 비교로 XP를 나누지 않습니다. 통제 조건을 충족해야 합니다.","en":"XP is not split by equal model counts; control conditions must be met."}}}},"postbattle-cycle":{"postbattle-order":{"objective":{"ko":"전투 직후 정산과 사이클 종료 정산을 구분해 순서대로 보고합니다.","en":"Report the post-battle sequence in order without confusing it with the end-of-cycle sequence."},"preparation":[{"ko":"참가 갱·승패·내건 영토·적 OOA 사건 기록을 준비하세요.","en":"Prepare participating gangs, outcome, staked territory, and enemy OOA event records."}],"walkthrough":[{"title":{"ko":"양측 기록 대조","en":"Compare both records"},"body":{"ko":"전투 마무리에서 모델 상태와 전투 결과를 상대와 맞춥니다. 이후 영토 재배분·보상·정리·보고 순서를 함께 확인합니다.","en":"Compare model states and the outcome with the opponent during wrap-up. Then follow territory reallocation, rewards, cleanup, and reporting together."},"result":{"ko":"양측이 같은 종료 상태를 사용합니다.","en":"Both players use the same final battle state."}},{"title":{"ko":"영토와 보상 기록","en":"Record territory and rewards"},"body":{"ko":"승자는 내건 영토를 얻고 무승부는 기존 소유·공석을 유지합니다. 영토 결과와 크레딧·장비 보상은 서로 다른 칸에 기록합니다.","en":"The winner receives the staked territory; a draw preserves ownership or vacancy. Record territory separately from credit and equipment rewards."},"result":{"ko":"영토 이동과 수입이 중복되지 않습니다.","en":"Territory changes and rewards are not conflated."}},{"title":{"ko":"보고와 시점 확인","en":"Report and confirm timing"},"body":{"ko":"참가 갱, 결과, 획득 영토, 갱별 유발 적 OOA를 보고합니다. 아직 사이클 종료가 아니라면 포스트 사이클 행동·수입 전체를 자동 실행하지 않습니다.","en":"Report gangs, outcome, territory gained, and enemy OOA caused by each gang. Do not automatically run all post-cycle actions and income if the cycle has not ended."},"result":{"ko":"전투 정산 완료와 사이클 종료를 구분합니다.","en":"Post-battle completion remains distinct from cycle completion."}}],"workedExample":{"situation":{"ko":"내건 영토가 있는 전투가 무승부로 끝났고 사이클에는 다음 전투가 남았습니다.","en":"A battle over staked territory ends in a draw, and another battle remains in the cycle."},"steps":[{"ko":"무승부이므로 영토는 기존 소유 또는 공석 상태를 유지합니다.","en":"The draw leaves the territory with its previous owner or vacant."},{"ko":"전투 결과와 보상을 보고하되 사이클 전체의 수입·행동을 바로 추가하지 않습니다.","en":"Report the battle and rewards without immediately adding the full cycle’s income and actions."}],"result":{"ko":"무승부 보고는 남기지만 임의 영토 획득이나 조기 사이클 정산은 없습니다.","en":"The draw is reported without invented territory gains or premature cycle settlement."}},"pitfalls":[{"problem":{"ko":"전투 보고 저장을 누를 때마다 포스트 사이클 수입까지 받습니다.","en":"Collecting post-cycle income every time a battle report is saved."},"fix":{"ko":"전투 후와 포스트 사이클을 별도 체크리스트로 관리하세요.","en":"Maintain separate checklists for post-battle and post-cycle processing."}}],"selfCheck":{"ko":"보고한 항목 중 전투별 보상과 사이클별 수입을 구분할 수 있나요?","en":"Can you distinguish battle rewards from cycle income in your report?"}},"xp-events":{"objective":{"ko":"XP를 사건별로 기록하고 같은 활성화·같은 적의 보상을 중복하지 않습니다.","en":"Record XP by event and avoid duplicating awards for the same enemy in one activation."},"preparation":[{"ko":"참가 여부, 직접 중상·OOA 사건, 대상 유형, 목표·지원 기록을 준비하세요.","en":"Prepare participation, direct Serious-injury/OOA events, target types, and objective or assistance records."}],"walkthrough":[{"title":{"ko":"사건과 실행자 연결","en":"Link each event to its actor"},"body":{"ko":"누가 어떤 행동으로 직접 중상·OOA를 유발했는지 적습니다. 전투 참가 +1과 행동으로 얻는 보상을 분리합니다.","en":"Record which model directly caused each Serious injury or OOA with its action. Separate the +1 participation award from action awards."},"result":{"ko":"XP의 원인과 대상이 남습니다.","en":"Each award has a recorded cause and recipient."}},{"title":{"ko":"중복과 대상 보너스 확인","en":"Check duplication and target bonuses"},"body":{"ko":"같은 활성화·같은 적에게 중상 뒤 OOA를 유발했다면 기본 보상은 OOA +2만 적용합니다. 리더·챔피언·브루트·차량 대상의 +1은 별도로 확인합니다.","en":"For Serious injury followed by OOA to the same enemy in one activation, apply only the base OOA +2 award. Separately check the +1 bonus for a Leader, Champion, Brute, or Vehicle target."},"result":{"ko":"동일 사건을 1+2로 두 번 계산하지 않습니다.","en":"The same sequence is not double-counted as 1+2."}},{"title":{"ko":"기타 보상과 합산","en":"Add other eligible awards"},"body":{"ko":"적법한 회복 지원 성공과 목표 통제 보상을 확인합니다. 목표 XP는 전투원당 전투 한 번이며 차량·펫은 받지 않습니다.","en":"Check successful eligible recovery assistance and objective control. Objective XP is once per fighter per battle and unavailable to vehicles or Pets."},"result":{"ko":"총 XP와 사건별 이유를 함께 저장합니다.","en":"Save the total together with the event breakdown."}}],"workedExample":{"situation":{"ko":"일반 적 하나를 같은 활성화에 중상 후 OOA로 만들고 전투에도 참가한 파이터입니다. 다른 보상은 없습니다.","en":"A fighter participated and caused Serious injury then OOA to one ordinary enemy in the same activation, with no other awards."},"steps":[{"ko":"직접 공격 보상은 OOA 2 XP만 적용합니다.","en":"The direct-action award is 2 XP for OOA only."},{"ko":"전투 참가 1 XP를 별도로 더해 합계 3 XP입니다.","en":"Add the separate 1 participation XP, giving 3 total XP."}],"result":{"ko":"3 XP의 내역은 참가 1+OOA 2이며 중상 보상은 추가하지 않습니다.","en":"The 3 XP is participation 1 plus OOA 2, without another Serious-injury award."}},"pitfalls":[{"problem":{"ko":"중상 1+OOA 2+참가 1로 4 XP를 기록합니다.","en":"Recording Serious injury 1 plus OOA 2 plus participation 1 as 4 XP."},"fix":{"ko":"동일 활성화·동일 적의 중상과 OOA를 하나의 보상 묶음으로 표시하세요.","en":"Group Serious injury and OOA to the same enemy in one activation as one award sequence."}}],"selfCheck":{"ko":"XP 합계에서 각 수치가 어떤 사건에서 나왔는지 설명할 수 있나요?","en":"Can you identify the event behind every number in the XP total?"}},"rewards-equipment":{"objective":{"ko":"장비 보상·사망 장비 회수·명성 증감을 각각 처리합니다.","en":"Resolve equipment rewards, recovered equipment, and Reputation adjustments separately."},"preparation":[{"ko":"보상 목록과 종료 시 전장에 남은 자갱 모델, 사망 모델 유형을 확인하세요.","en":"Check rewards, whether a gang model remains on the battlefield at the end, and the dead model’s type."}],"walkthrough":[{"title":{"ko":"보상은 보관고로","en":"Place rewards in the stash"},"body":{"ko":"장비 보상은 보관고에 넣고 포스트 사이클 장비 재분배 때 지급합니다. 획득 기록과 장착 기록을 혼동하지 않습니다.","en":"Put equipment rewards in the stash for allocation during post-cycle redistribution. Receiving an item and equipping it are separate records."},"result":{"ko":"장비가 어디에 있는지 추적됩니다.","en":"The equipment’s location remains traceable."}},{"title":{"ko":"사망 장비 회수 검사","en":"Check recovery of dead equipment"},"body":{"ko":"종료 시 자갱 모델이 전장에 남아 있어야 사망 파이터 장비 회수가 가능합니다. 차량·브루트·행어온의 장비 소멸 예외를 확인합니다.","en":"Recovering dead fighters’ equipment requires a gang model remaining on the battlefield at the end. Check removal exceptions for Vehicles, Brutes, and Hangers-on."},"result":{"ko":"회수 자격과 유형 예외가 모두 확인됩니다.","en":"Both recovery eligibility and type exceptions are checked."}},{"title":{"ko":"명성 증감 순서","en":"Apply Reputation in order"},"body":{"ko":"명성 증가는 먼저 적용하고 감소를 나중에 적용합니다. 최종 명성은 최소 1이며 영토·보상과 별도 기록합니다.","en":"Apply Reputation gains before losses, with a minimum of 1. Record this independently of territory and equipment."},"result":{"ko":"증감 순서와 하한을 지킵니다.","en":"Respect both adjustment order and the minimum."}}],"workedExample":{"situation":{"ko":"명성 1 갱이 보상으로 +2, 다른 결과로 −4를 받습니다.","en":"A Reputation 1 gang receives +2 from one reward and −4 from another consequence."},"steps":[{"ko":"증가부터 적용해 1+2=3입니다.","en":"Apply the gain first: 1+2=3."},{"ko":"이후 4를 감소시키되 최소 1을 적용합니다.","en":"Then apply the loss of four, respecting the minimum of one."}],"result":{"ko":"최종 명성은 1입니다. 장비 보상은 별도로 보관고에 기록합니다.","en":"Final Reputation is 1; any equipment reward is separately recorded in the stash."}},"pitfalls":[{"problem":{"ko":"전장에 남은 모델이나 유형 예외를 보지 않고 사망 장비를 모두 자동 회수합니다.","en":"Automatically recovering all dead equipment without checking remaining gang models or type exceptions."},"fix":{"ko":"전장 잔류 자격과 해당 모델 유형의 장비 제거 규칙을 먼저 확인하세요.","en":"Check the battlefield-presence requirement and the model type’s equipment-removal rule first."}}],"selfCheck":{"ko":"장비의 획득·회수·지급 중 어느 작업을 하고 있는지 구분했나요?","en":"Have you distinguished receiving, recovering, and allocating equipment?"},"exerciseHint":{"ko":"문항은 같은 활성화·같은 적의 두 공격 사건만 묻고 참가 XP는 제외합니다.","en":"The question asks only about two action events against the same enemy in one activation; participation XP is excluded."},"optionFeedback":{"1":{"ko":"동일 활성화·동일 적의 중상과 OOA 기본 보상은 중복하지 않습니다.","en":"Serious injury and OOA base awards for the same enemy in one activation do not stack."},"2":{"ko":"이 두 사건은 OOA 기본 보상 2 XP만 적용합니다.","en":"These events receive only the base OOA award of 2 XP."},"3":{"ko":"직접 OOA를 유발한 행동에는 기본 2 XP가 있습니다.","en":"An action directly causing OOA grants a base award of 2 XP."}}},"cycle-actions":{"objective":{"ko":"적격 모델마다 하나의 포스트 사이클 행동만 배정합니다.","en":"Assign exactly one post-cycle action to each eligible model."},"preparation":[{"ko":"사이클 종료 명부, 리커버리·크리티컬 상태와 시작 크레딧을 준비하세요.","en":"Prepare the end-of-cycle roster, Recovery/Critical states, and starting credits."}],"walkthrough":[{"title":{"ko":"행동 전 자격 확인","en":"Check eligibility before assignment"},"body":{"ko":"리커버리·크리티컬 모델을 제외하고 각 모델의 유형별 행동 조건을 확인합니다. 상태를 먼저 지워 참가 자격을 만들지 않습니다.","en":"Exclude Recovery and Critical models and inspect type-specific action conditions. Do not clear those states early to create eligibility."},"result":{"ko":"실제로 행동 가능한 모델만 남깁니다.","en":"Only genuinely eligible models remain."}},{"title":{"ko":"모델당 행동 하나","en":"Assign one action per model"},"body":{"ko":"각 모델에 영토 작업·트레인 등 한 행동만 배정합니다. 영토 작업은 적법한 리더·챔피언·갱어·프로스펙트 최대 다섯 명입니다.","en":"Assign one action such as Work Territory or Train to each model. Work Territory allows at most five eligible Leaders, Champions, Gangers, or Prospects."},"result":{"ko":"중복 배정과 영토 작업 인원 초과를 막습니다.","en":"Prevent duplicate actions and excessive Work Territory assignments."}},{"title":{"ko":"비용·효과 확인","en":"Check costs and effects"},"body":{"ko":"영토 작업은 각 15크레딧, 트레인은 각 2 XP입니다. 치료·교역 등은 행위자·대상·선지급 비용을 각각 확인한 뒤 적용합니다.","en":"Work Territory earns 15 credits each; Train grants 2 XP each. For treatment and trade actions, check actor, target, and upfront cost requirements before applying them."},"result":{"ko":"행동별 지출·수입·XP를 분리합니다.","en":"Track action costs, earnings, and XP separately."}}],"workedExample":{"situation":{"ko":"적격 갱어 여섯 명이 있습니다. 다섯 명을 영토 작업에, 한 명을 트레인에 배정합니다.","en":"Six Gangers are eligible. Assign five to Work Territory and one to Train."},"steps":[{"ko":"영토 작업은 최대 다섯 명이므로 5×15=75크레딧입니다.","en":"Work Territory reaches its five-model maximum and earns 5×15=75 credits."},{"ko":"여섯 번째 모델은 트레인으로 2 XP를 얻고 영토 작업 수입에는 포함되지 않습니다.","en":"The sixth model earns 2 XP from Train and is excluded from Work Territory earnings."}],"result":{"ko":"각 모델은 행동 하나를 수행하며 갱은 75크레딧과 해당 모델의 2 XP를 얻습니다.","en":"Each model performs one action; the gang earns 75 credits and the trainee earns 2 XP."}},"pitfalls":[{"problem":{"ko":"한 모델에게 영토 작업과 트레인을 모두 배정합니다.","en":"Assigning both Work Territory and Train to one model."},"fix":{"ko":"모델별 행동 칸 하나와 행동별 대상·비용 칸을 사용하세요.","en":"Use one action slot per model with separate target and cost entries."}}],"selfCheck":{"ko":"모든 행동의 모델 자격·중복 여부·선지급 비용을 확인했나요?","en":"Have you checked actor eligibility, duplicate assignments, and upfront costs?"}},"income-update":{"objective":{"ko":"수입 수집 뒤 명부 업데이트를 정해진 순서로 처리합니다.","en":"Collect income before following the ordered roster-update substeps."},"preparation":[{"ko":"확정 영토 수입·보너스, 명성, 행동 수입과 현재 크레딧을 준비하세요.","en":"Prepare confirmed territory income/boons, Reputation, action earnings, and current credits."}],"walkthrough":[{"title":{"ko":"수입 원인 분리","en":"Separate income sources"},"body":{"ko":"영토 작업 수입, 영토 자체 수입·보너스, 명성당 10크레딧을 각각 적습니다. 영토 작업을 영토 자체 수입에 다시 포함하지 않습니다.","en":"List Work Territory earnings, territory income/boons, and 10 credits per Reputation separately. Do not count Work Territory again as territory income."},"result":{"ko":"수입 중복 없이 합계를 구할 수 있습니다.","en":"Income can be totaled without duplication."}},{"title":{"ko":"명부 업데이트 순서","en":"Follow the roster-update order"},"body":{"ko":"승급 → 교역 → 장비 재분배 → 정리 순으로 진행합니다. 성장 가치 증가와 실제 크레딧 지출을 같은 것으로 취급하지 않습니다.","en":"Proceed through advancement, trading, equipment redistribution, and cleanup. Do not confuse increased fighter value with actual credit expenditure."},"result":{"ko":"자산·크레딧·모델 가치가 구분됩니다.","en":"Assets, cash credits, and model value remain distinct."}},{"title":{"ko":"정리에서 상태 해제","en":"Clear states during cleanup"},"body":{"ko":"장비 처리부터 확인한 뒤 사망·파괴·은퇴 모델을 정리하고 리커버리를 해제합니다. 해제는 앞선 행동 단계로 소급하지 않습니다.","en":"Check equipment handling before removing dead, destroyed, or retired models, and clear Recovery during cleanup. This does not retroactively grant earlier action eligibility."},"result":{"ko":"다음 사이클 명부가 준비됩니다.","en":"The roster is ready for the next cycle."}}],"workedExample":{"situation":{"ko":"명성 3이며 확정 영토 수입·보너스가 40크레딧입니다. 행동 수입은 별도 장부에 이미 있습니다.","en":"Reputation is 3 and confirmed territory income/boons are 40 credits. Action earnings are already tracked separately."},"steps":[{"ko":"명성 수입은 3×10=30크레딧입니다.","en":"Reputation income is 3×10=30 credits."},{"ko":"이 수집 항목의 합은 40+30=70이며 행동 수입은 한 번만 합칩니다.","en":"These collection entries total 40+30=70; add separately tracked action income only once."}],"result":{"ko":"70크레딧의 수집 내역과 행동 수입을 구분한 뒤 명부 업데이트로 이동합니다.","en":"Retain the 70-credit income breakdown separately from action earnings, then update the roster."}},"pitfalls":[{"problem":{"ko":"리커버리를 수입 수집 전에 지워 이전 행동 단계에 뒤늦게 참가시킵니다.","en":"Clearing Recovery before income collection to retrospectively assign an action."},"fix":{"ko":"행동 자격은 행동 단계의 상태로 판정하고 해제는 명부 정리에서 하세요.","en":"Determine action eligibility from the action-step state and clear Recovery during roster cleanup."}}],"selfCheck":{"ko":"같은 수입을 두 번 더하지 않았고 리커버리를 올바른 단계에서 지웠나요?","en":"Have you avoided duplicate earnings and cleared Recovery at the correct stage?"}},"cycle-practice":{"objective":{"ko":"수입 세 원인을 나눠 130크레딧이라는 합계를 검산합니다.","en":"Audit the 130-credit result by separating its three income sources."},"preparation":[{"ko":"영토 작업 네 명, 명성 3, 영토 수입·보너스 40이라는 연습 조건을 사용하세요.","en":"Use the exercise conditions: four workers, Reputation 3, and 40 territory/boon credits."}],"walkthrough":[{"title":{"ko":"영토 작업 수입","en":"Calculate work earnings"},"body":{"ko":"적격 모델 네 명은 최대 다섯 명 제한 안입니다. 한 명당 15크레딧이므로 4×15를 계산합니다.","en":"Four eligible workers are within the five-model limit. Calculate four times 15 credits."},"result":{"ko":"영토 작업 수입은 60입니다.","en":"Work Territory earns 60."}},{"title":{"ko":"명성과 영토 수입","en":"Calculate reputation and territory"},"body":{"ko":"명성 3에 10을 곱해 30을 얻고 주어진 영토·보너스 40을 별도 줄에 적습니다.","en":"Multiply Reputation 3 by 10 for 30 credits, and list the supplied 40 territory/boon credits separately."},"result":{"ko":"서로 다른 수입 원인 세 줄이 완성됩니다.","en":"All three distinct income lines are present."}},{"title":{"ko":"합계와 지출 확인","en":"Total and inspect costs"},"body":{"ko":"60+30+40을 합산합니다. 이 문항은 다른 지출이 없다고 했으므로 치료·구매 비용을 임의로 만들지 않습니다.","en":"Add 60+30+40. This question states there are no other costs, so do not invent treatment or purchase deductions."},"result":{"ko":"연습의 총 수입을 답으로 선택합니다.","en":"Choose the exercise’s total income."}}],"workedExample":{"situation":{"ko":"수입 장부의 세 줄은 영토 작업 60, 명성 30, 영토·보너스 40입니다.","en":"The ledger lines are Work Territory 60, Reputation 30, and territory/boons 40."},"steps":[{"ko":"60+30=90을 먼저 계산합니다.","en":"First calculate 60+30=90."},{"ko":"90+40=130으로 합산하고 각 원인으로 역산합니다.","en":"Then add 40 for 130 and trace the total back to each source."}],"result":{"ko":"총 수입은 130크레딧이며 현재 보유 크레딧 전체를 묻는 문제는 아닙니다.","en":"Total income is 130 credits; the question is not asking for the gang’s entire current credit balance."}},"pitfalls":[{"problem":{"ko":"70크레딧만 골라 영토 작업 60을 누락합니다.","en":"Choosing 70 credits and omitting the 60 earned by workers."},"fix":{"ko":"영토 작업·명성·영토 자체 수입을 세 줄로 쓴 뒤 합산하세요.","en":"Write Work Territory, Reputation, and territory income as three lines before adding them."}}],"selfCheck":{"ko":"총수입, 지출 후 순변화, 현재 잔액 세 개를 구분할 수 있나요?","en":"Can you distinguish gross income, net change after costs, and the current balance?"},"exerciseHint":{"ko":"4×15, 3×10, 40을 각각 구한 뒤 합산하세요.","en":"Calculate 4×15, 3×10, and 40 separately, then total them."},"optionFeedback":{"1":{"ko":"70은 명성 30+영토 40뿐이며 영토 작업 60이 빠졌습니다.","en":"Seventy includes only Reputation 30 and territory 40; worker earnings 60 are missing."},"2":{"ko":"각 수입을 다시 세 줄로 확인하세요. 60+30+40은 100이 아닙니다.","en":"Recheck the three income lines: 60+30+40 does not equal 100."},"3":{"ko":"영토 작업 60+명성 30+영토·보너스 40=130입니다.","en":"Work 60 plus Reputation 30 plus territory/boons 40 equals 130."}}}},"growth-special-rules":{"cumulative-xp":{"objective":{"ko":"N26 누적 XP를 유지하고 새 구간의 성장을 한 번만 처리합니다.","en":"Retain cumulative N26 XP and resolve each newly entered advancement band once."},"preparation":[{"ko":"이전 누적 XP, 새 XP, 처리한 성장 구간과 가치 증가 기록을 준비하세요.","en":"Prepare previous and current cumulative XP, resolved bands, and added-value records."}],"walkthrough":[{"title":{"ko":"누적 합계 기록","en":"Record cumulative totals"},"body":{"ko":"전투·행동 XP를 기존 합계에 더합니다. N26은 성장 구매 때 XP를 소비하는 방식이 아니므로 합계를 낮추지 않습니다.","en":"Add battle/action XP to the previous total. N26 advancement does not spend XP, so do not reduce the cumulative total."},"result":{"ko":"이전 값과 새 값이 모두 남습니다.","en":"Both previous and new values are retained."}},{"title":{"ko":"구간 진입 확인","en":"Check band entry"},"body":{"ko":"이전과 새 값을 XP 구간표에서 비교합니다. 새 행에 진입한 경우 포스트 사이클 성장 대상으로 표시하고 이미 처리한 구간은 반복하지 않습니다.","en":"Compare previous and new totals against the XP bands. Mark a newly entered row for post-cycle advancement and never grant an already resolved band again."},"result":{"ko":"성장 자격과 실제 처리 시점이 구분됩니다.","en":"Eligibility is separated from resolution timing."}},{"title":{"ko":"성장 결과·가치 기록","en":"Record result and value"},"body":{"ko":"확인된 표 결과에 따라 성장과 크레딧 가치 증가를 기록합니다. 시작 XP와 미확정 결과 선택 방향은 임의 성장 보상으로 바꾸지 않습니다.","en":"Record the established advancement result and its credit-value increase. Do not turn starting XP or unresolved result-selection directions into invented awards."},"result":{"ko":"XP·성장 이력·모델 가치를 함께 검산합니다.","en":"Audit XP, advancement history, and model value together."}}],"workedExample":{"situation":{"ko":"누적 XP 6 파이터가 XP 1을 얻고 아직 새 구간 성장을 처리하지 않았습니다.","en":"A fighter at cumulative XP 6 earns 1 XP and has not yet resolved the new band."},"steps":[{"ko":"누적 XP는 6+1=7로 기록합니다.","en":"Record cumulative XP as 6+1=7."},{"ko":"6→7은 확인된 새 구간 예이므로 포스트 사이클에 한 번 처리할 대상으로 표시합니다.","en":"The confirmed 6-to-7 example enters a new band, so mark it for one post-cycle resolution."}],"result":{"ko":"XP는 7로 유지하며 성장 결과와 가치 증가를 별도로 적습니다.","en":"XP remains 7; the advancement result and added value are recorded separately."}},"pitfalls":[{"problem":{"ko":"성장을 받았다는 이유로 XP를 0으로 되돌립니다.","en":"Resetting XP to zero after an advancement."},"fix":{"ko":"누적 XP 칸은 유지하고 처리한 구간 이력으로 중복을 막으세요.","en":"Retain the cumulative XP field and prevent duplication through resolved-band history."}}],"selfCheck":{"ko":"새 구간 여부와 이전 처리 여부를 확인했으며 XP를 소비하지 않았나요?","en":"Have you checked band entry and prior resolution without spending XP?"}},"promotion":{"objective":{"ko":"일반 성장과 갱어·프로스펙트 역할 승급을 시점별로 구분합니다.","en":"Distinguish ordinary advancement from Ganger and Prospect subtype promotions by timing."},"preparation":[{"ko":"누적 XP와 원래 명명된 유형, 현재 하위유형 목록을 확인하세요.","en":"Check cumulative XP, the original named type, and the current subtype list."}],"walkthrough":[{"title":{"ko":"현재 하위유형 확인","en":"Inspect the subtype"},"body":{"ko":"표시 이름만 보고 판단하지 말고 갱어인지 프로스펙트인지 확인합니다. 다른 하위유형과 원래 명명된 유형도 함께 적습니다.","en":"Check whether the model is a Ganger or Prospect rather than inferring this from its display name. Retain its other subtypes and original named type."},"result":{"ko":"어느 승급 규칙을 쓸지 정합니다.","en":"Identify the applicable promotion rule."}},{"title":{"ko":"XP·시점 분기","en":"Branch by XP and timing"},"body":{"ko":"갱어는 누적 37 XP 이상에서 포스트 사이클 성장 굴림 뒤 챔피언으로 바뀝니다. 프로스펙트는 13 XP 이상에서 성장 굴림 대신 승급합니다.","en":"At 37+ cumulative XP a Ganger becomes a Champion after its post-cycle advancement roll. At 13+ XP a Prospect promotes instead of making that roll."},"result":{"ko":"굴림 후와 굴림 대신을 구분합니다.","en":"Distinguish after-the-roll from instead-of-the-roll."}},{"title":{"ko":"유형과 가치 갱신","en":"Update subtypes and value"},"body":{"ko":"프로스펙트는 해당 하위유형을 제거하고 갱어·스페셜리스트를 얻으며 가치 +15를 기록합니다. 적법한 전문분야와 무료 스킬 대응을 확인합니다.","en":"A Prospect loses that subtype, gains Ganger and Specialist, and adds 15 value. Verify the legal specialisation and associated free skill mapping."},"result":{"ko":"원래 명명된 유형과 다른 하위유형은 유지합니다.","en":"The original named type and other subtypes remain."}}],"workedExample":{"situation":{"ko":"프로스펙트가 누적 XP 13에 도달했고 현재 가치가 60크레딧입니다.","en":"A Prospect reaches cumulative XP 13 and currently has a value of 60 credits."},"steps":[{"ko":"포스트 사이클에 일반 성장 굴림 대신 프로스펙트 승급을 적용합니다.","en":"Apply Prospect promotion during post-cycle instead of the ordinary advancement roll."},{"ko":"하위유형을 갱어·스페셜리스트로 바꾸고 가치 60+15=75를 기록합니다.","en":"Replace the subtype with Ganger and Specialist and record value 60+15=75."}],"result":{"ko":"누적 XP 13은 유지되고 가치만 75가 됩니다. 무료 스킬은 확인된 대응으로 정합니다.","en":"Cumulative XP stays 13 and value becomes 75; choose the free skill through a verified mapping."}},"pitfalls":[{"problem":{"ko":"모든 파이터에게 같은 XP 기준과 같은 성장 굴림 순서를 적용합니다.","en":"Applying the same XP threshold and roll timing to every subtype."},"fix":{"ko":"갱어 37 이후 굴림 뒤, 프로스펙트 13 이후 굴림 대신으로 분기하세요.","en":"Branch explicitly: Ganger 37+ after the roll; Prospect 13+ instead of the roll."}}],"selfCheck":{"ko":"원래 유형을 보존하고 추가·제거한 하위유형만 정확히 바꿨나요?","en":"Have you preserved the named type and changed only the specified subtypes?"}},"advancement-practice":{"objective":{"ko":"6→7 XP 예에서 XP 소비 없이 포스트 사이클 성장을 표시합니다.","en":"Mark post-cycle advancement for the 6-to-7 example without spending XP."},"preparation":[{"ko":"파이터는 갱어이며 시작 XP 보상이 아니라 전투 후 얻은 XP라고 가정합니다.","en":"Assume the model is a Ganger gaining XP after battle, not receiving starting XP."}],"walkthrough":[{"title":{"ko":"변화량 계산","en":"Calculate the change"},"body":{"ko":"이전 누적 XP 6에 이번 XP 1을 더해 7로 기록합니다. XP 획득 이유도 남깁니다.","en":"Add this award of 1 to previous cumulative XP 6 and record 7, retaining the reason for the award."},"result":{"ko":"XP 기록이 6→7로 이어집니다.","en":"The XP history shows 6 to 7."}},{"title":{"ko":"새 구간 표시","en":"Mark the new band"},"body":{"ko":"현재 구간표와 처리 이력을 확인해 새 구간 자격을 표시합니다. 성장 수령을 위해 XP를 차감하거나 전투 도중 즉시 구매하지 않습니다.","en":"Check bands and prior resolutions and mark new-band eligibility. Do not deduct XP or purchase an immediate mid-battle advancement."},"result":{"ko":"처리 대기 성장으로 남깁니다.","en":"The advancement remains pending for its proper timing."}},{"title":{"ko":"승급 기준과 분리","en":"Separate subtype promotion"},"body":{"ko":"포스트 사이클에 성장 결과를 처리합니다. 갱어 37 XP 챔피언 승급은 별도 조건이므로 7 XP의 일반 성장을 막지 않습니다.","en":"Resolve the advancement in post-cycle. The separate 37-XP Ganger-to-Champion condition does not prevent ordinary advancement at 7 XP."},"result":{"ko":"정답은 누적 7 유지와 새 구간 성장입니다.","en":"The correct interpretation retains 7 XP and resolves the new band."}}],"workedExample":{"situation":{"ko":"갱어의 이전 XP는 6, 이번 획득은 1이며 별도 승급 조건은 없습니다.","en":"A Ganger previously had XP 6, earns 1, and has no separate promotion condition."},"steps":[{"ko":"6+1=7을 계산합니다.","en":"Calculate 6+1=7."},{"ko":"새 구간 성장을 포스트 사이클에 표시하고 XP 7을 그대로 유지합니다.","en":"Mark new-band advancement for post-cycle while retaining XP 7."}],"result":{"ko":"챔피언 승급 자격이 없어도 일반 새 구간 성장은 가능합니다.","en":"Ordinary new-band advancement remains possible without Champion promotion eligibility."}},"pitfalls":[{"problem":{"ko":"37 XP가 되기 전에는 갱어가 성장하지 못한다고 생각합니다.","en":"Assuming a Ganger cannot advance before reaching 37 XP."},"fix":{"ko":"일반 XP 구간 성장과 하위유형 승급 조건을 두 줄로 나누세요.","en":"Separate ordinary XP-band advancement and subtype-promotion eligibility into two entries."}}],"selfCheck":{"ko":"XP 7 유지·포스트 사이클 처리·승급과 별개라는 세 조건을 모두 찾았나요?","en":"Have you identified all three: retain 7 XP, resolve in post-cycle, and separate promotion eligibility?"},"exerciseHint":{"ko":"N26은 XP를 쓰지 않습니다. 6→7의 구간 진입과 처리 시점만 확인하세요.","en":"N26 does not spend XP. Check only the 6-to-7 band entry and its timing."},"optionFeedback":{"1":{"ko":"XP를 소비하는 다른 방식과 혼동했습니다. N26 누적 XP는 7로 남습니다.","en":"This confuses a spending model with N26; cumulative XP remains 7."},"2":{"ko":"누적 XP 유지, 새 구간, 포스트 사이클 시점을 모두 반영했습니다.","en":"This correctly retains XP, recognizes the new band, and uses post-cycle timing."},"3":{"ko":"37 XP는 갱어의 챔피언 승급 기준이며 그 전 일반 성장을 막지 않습니다.","en":"The 37-XP threshold governs Champion promotion, not all earlier ordinary advancement."}}},"trade":{"objective":{"ko":"구매 접근·크레딧·TP·받는 모델 제한을 따로 검토합니다.","en":"Check purchase access, credits, TP, and recipient restrictions separately."},"preparation":[{"ko":"현재 크레딧과 확인된 TP, 구매 목록, 받을 모델의 장비 목록을 준비하세요.","en":"Prepare current credits, confirmed TP, the trading list, and the recipient’s equipment list."}],"walkthrough":[{"title":{"ko":"목록 접근 확인","en":"Check list access"},"body":{"ko":"갱 장비 목록은 항상 접근 가능하지만 외부 교역소는 방문 행동이 필요합니다. E 독점 장비는 받는 모델 목록에도 있어야 합니다.","en":"The gang list is always accessible; external trade requires a Visit Trading Post action. Exclusive E equipment must also appear on the receiving model’s list."},"result":{"ko":"살 수 있는 항목과 받을 수 있는 모델을 확인합니다.","en":"Verify both availability and the eligible recipient."}},{"title":{"ko":"자원 두 개 확인","en":"Check both resources"},"body":{"ko":"구매의 크레딧과 TP 비용을 각각 확인합니다. TP 생성 산식이 미확정이면 아비트레이터와 합의한 값을 기록하며, 남은 TP는 교역 단계 끝에 소멸합니다.","en":"Verify both credit and TP costs. If TP generation is unresolved, record the arbitrator’s agreed value; unused TP expires at the end of the trade substep."},"result":{"ko":"추측한 TP를 크레딧처럼 자동 생성하지 않습니다.","en":"No guessed TP pool is created automatically."}},{"title":{"ko":"판매·재분배 분리","en":"Separate selling and redistribution"},"body":{"ko":"보관고 판매는 물품을 제거하고 가치 절반, 최소 5크레딧을 받습니다. 재분배는 받는 모델의 장비 제한을 다시 확인합니다.","en":"A stash sale removes the item and grants half its value, minimum 5 credits. Redistribution separately rechecks the recipient’s restrictions."},"result":{"ko":"물품 이동과 크레딧 변화를 함께 기록합니다.","en":"Track item movement alongside credit changes."}}],"workedExample":{"situation":{"ko":"보관고의 30크레딧 물품 하나를 판매합니다. 이 예에는 홀수 반올림 문제가 없습니다.","en":"You sell one stash item worth 30 credits; this example has no odd-value rounding issue."},"steps":[{"ko":"가치 절반은 30÷2=15로 최소 5보다 큽니다.","en":"Half its value is 30÷2=15, exceeding the minimum of 5."},{"ko":"물품을 보관고에서 제거하고 크레딧 15만 추가합니다.","en":"Remove the item from the stash and add 15 credits."}],"result":{"ko":"장비는 남지 않고 15크레딧을 받습니다. 판매를 무료 복제처럼 처리하지 않습니다.","en":"The item is gone and 15 credits are received; selling does not duplicate equipment."}},"pitfalls":[{"problem":{"ko":"크레딧만 충분하면 TP·목록·E 제한을 무시할 수 있다고 봅니다.","en":"Assuming sufficient credits bypass TP, list access, or Exclusive restrictions."},"fix":{"ko":"접근·모델 제한·크레딧·TP를 각각 통과한 구매만 확정하세요.","en":"Confirm a purchase only after independently passing access, recipient, credit, and TP checks."}}],"selfCheck":{"ko":"물품의 이전·새 위치와 크레딧·TP의 전후 값을 설명할 수 있나요?","en":"Can you identify the item’s old/new location and the before/after credit and TP values?"}},"special-rules":{"objective":{"ko":"특수규칙의 발동 조건·효과·후속 위험을 순서대로 해석합니다.","en":"Read a special rule’s trigger, effect, and subsequent risks in order."},"preparation":[{"ko":"판본과 해당 능력의 유형·시점·거리·시야·비용·종료 조건을 펼쳐 두세요.","en":"Have the edition and the ability’s type, timing, distance, visibility, cost, and ending condition available."}],"walkthrough":[{"title":{"ko":"규칙 범위 표시","en":"Mark the scope"},"body":{"ko":"판본과 대상 유형이 맞는지 먼저 확인합니다. 일반 규칙을 바꾸는 문장과 발동 시점·거리·시야 조건을 나눠 읽습니다.","en":"First check edition and eligible type. Separate the exception to the ordinary rule from its timing, distance, and visibility conditions."},"result":{"ko":"아직 발동하지 않은 효과를 적용하지 않습니다.","en":"Effects are not applied before their trigger is met."}},{"title":{"ko":"성공과 위험 분리","en":"Separate success from risk"},"body":{"ko":"워드 발현은 자연 2와 12 모두 역류를 일으키지만 발현 결과는 다릅니다. 자연 2는 자동 발현 뒤 역류, 자연 12는 자동 실패 뒤 역류입니다.","en":"Natural 2 and 12 both cause Perils during Wyrd manifestation, but with different outcomes: 2 manifests automatically then causes Perils; 12 fails automatically then causes Perils."},"result":{"ko":"발현 성공 여부와 역류를 두 칸에 기록합니다.","en":"Record manifestation outcome and Perils separately."}},{"title":{"ko":"명시적 무기 예외 확인","en":"Apply explicit weapon exceptions"},"body":{"ko":"워드가 만든 무기는 탄약 부족이 되지 않으며 화력 주사위의 탄약 기호를 무시합니다. 이 예외를 일반 무기에 확대하지 않습니다.","en":"Weapons created by Wyrd powers cannot run Out of Ammo and ignore Firepower Ammo symbols. Do not extend this exception to ordinary weapons."},"result":{"ko":"특수규칙의 적용 대상만 바꿉니다.","en":"Only the rule’s stated subjects receive the exception."}}],"workedExample":{"situation":{"ko":"워드 발현 굴림의 자연 합이 2인 경우와 12인 경우를 비교합니다.","en":"Compare Wyrd manifestation with natural totals of 2 and 12."},"steps":[{"ko":"자연 2: 발현 자동 성공을 먼저 기록하고 역류를 처리합니다.","en":"Natural 2: record automatic manifestation success, then resolve Perils."},{"ko":"자연 12: 발현 자동 실패를 기록하고 역시 역류를 처리합니다.","en":"Natural 12: record automatic failure, then still resolve Perils."}],"result":{"ko":"두 경우 모두 역류지만 발현 성공은 자연 2에서만 발생합니다.","en":"Both cause Perils, but automatic manifestation success occurs only on natural 2."}},"pitfalls":[{"problem":{"ko":"역류가 발생했으니 모든 발현은 실패라고 처리합니다.","en":"Treating every manifestation as failed merely because Perils occurred."},"fix":{"ko":"발현 결과와 역류 발생을 별도 항목으로 적으세요.","en":"Write manifestation outcome and Perils as two separate results."}}],"selfCheck":{"ko":"이 예외가 적용되는 대상과 적용되지 않는 일반 규칙을 구분할 수 있나요?","en":"Can you identify which subjects receive the exception and which ordinary rules remain unchanged?"}},"reading-practice":{"objective":{"ko":"확인된 규칙과 미확정 해석을 분리해 일관된 합의 기록을 만듭니다.","en":"Separate established rules from unresolved interpretation and record a consistent agreed ruling."},"preparation":[{"ko":"확인 필요 표시가 있는 항목과 현재 캠페인의 아비트레이터 합의를 준비하세요.","en":"Have the marked unresolved entry and the campaign arbitrator’s ruling available."}],"walkthrough":[{"title":{"ko":"확정된 부분 추출","en":"Extract what is established"},"body":{"ko":"외부 교역 접근에 방문 행동이 필요하다는 확인된 조건을 먼저 적용합니다. 산식이 불명확하다는 이유로 접근 조건까지 생략하지 않습니다.","en":"Apply the established requirement for a visit action to access external trade. An unresolved formula does not remove established access conditions."},"result":{"ko":"확인된 규칙은 그대로 유지합니다.","en":"Established rules remain in force."}},{"title":{"ko":"미확정 부분 표시","en":"Mark the unresolved part"},"body":{"ko":"TP 생성 산식이나 성장 표의 다른 행 선택 방향처럼 확인이 필요한 부분을 구체적으로 적습니다. 다른 판본의 익숙한 값으로 자동 대체하지 않습니다.","en":"Identify the unresolved TP-generation formula or cross-row advancement selection direction precisely. Do not automatically substitute familiar values from another edition."},"result":{"ko":"모르는 부분과 아는 부분이 분리됩니다.","en":"Unknown and established parts are separated."}},{"title":{"ko":"합의와 적용 범위 기록","en":"Record the ruling and scope"},"body":{"ko":"아비트레이터와 정한 임시 판정을 메모에 남깁니다. 언제 어떤 상황에 적용했는지 적어 이후 같은 상황에도 일관되게 사용합니다.","en":"Record the arbitrator’s agreed interim ruling, including when and where it applies, so equivalent later situations receive the same treatment."},"result":{"ko":"합의를 확정 기본 규칙으로 위장하지 않습니다.","en":"An agreed ruling is not presented as definitive core text."}}],"workedExample":{"situation":{"ko":"외부 교역 방문은 했지만 TP 산식은 확인 필요로 표시되어 있습니다.","en":"The gang completed a visit for external trade, but the TP formula remains marked unresolved."},"steps":[{"ko":"방문에 따른 접근 조건 충족은 확인합니다.","en":"Confirm that the visit meets the established access condition."},{"ko":"사용할 TP 값은 임의 계산하지 않고 아비트레이터와 합의해 기록합니다.","en":"Do not invent a TP calculation; agree the value with the arbitrator and record it."}],"result":{"ko":"접근 허용과 TP 수치 합의를 별도로 기록합니다.","en":"Record access eligibility separately from the agreed TP value."}},"pitfalls":[{"problem":{"ko":"빈칸을 큰 수나 다른 판본의 규칙으로 조용히 채웁니다.","en":"Silently filling the gap with a generous number or another edition’s rule."},"fix":{"ko":"미확정 부분만 합의 대상으로 남기고 적용 근거와 범위를 기록하세요.","en":"Limit the ruling to the unresolved portion and document its basis and scope."}}],"selfCheck":{"ko":"확인된 조건, 확인 필요 부분, 캠페인 합의를 각각 구분해 설명할 수 있나요?","en":"Can you distinguish established conditions, unresolved details, and the campaign ruling?"},"exerciseHint":{"ko":"외부 교역 접근은 확인됐지만 TP 산식은 미확정이라는 두 상태를 분리하세요.","en":"Separate the established trading-access rule from the unresolved TP formula."},"optionFeedback":{"1":{"ko":"다른 판본은 빈칸을 확정해 주는 근거가 아닙니다.","en":"Another edition is not evidence that definitively fills this gap."},"2":{"ko":"가장 유리한 수를 고르는 것은 확인된 규칙이나 합의가 아닙니다.","en":"Choosing the most generous value is neither an established rule nor an agreed ruling."},"3":{"ko":"확인된 접근은 적용하고 미확정 산식만 합의·기록해 구분했습니다.","en":"This applies established access while separately agreeing and recording the unresolved formula."}}}}};
const minutes={"gang-foundations":28,"prepare-round":24,"activation-states":28,"movement-terrain":30,"ranged-combat":32,"close-combat":30,"wounds-recovery":28,"morale-objectives":26,"postbattle-cycle":30,"growth-special-rules":30};
if(!Array.isArray(globalThis.UK_TUTORIALS))return;
for(const lesson of globalThis.UK_TUTORIALS){
 const additions=details[lesson.id];if(!additions||lesson.editions?.length!==1||lesson.editions[0]!=='n26')continue;
 lesson.minutes=Math.max(lesson.minutes||0,minutes[lesson.id]||0);
 for(const step of lesson.steps||[]){
  const detail=additions[step.id];if(!detail)continue;
  const {exerciseHint,optionFeedback,...teaching}=detail;Object.assign(step,teaching);
  if(step.exercise){if(exerciseHint)step.exercise.hint=exerciseHint;for(const option of step.exercise.options||[])if(optionFeedback?.[option.id])option.feedback=optionFeedback[option.id];}
 }
}
})();
